def _context_roots(
    root: Path, findings: list[dict[str, Any]]
) -> tuple[Path, Path, dict[str, Any]]:
    context = _read_json(root / "START_CONTEXT.json", findings)
    if not isinstance(context, dict):
        return root, root, {}
    candidate_value = str(
        context.get("candidate_root") or context.get("target_root") or root
    )
    execution_value = str(context.get("execution_root") or candidate_value)
    if _portable_context(context):
        candidate_root = _contract_path(candidate_value)
        execution_root = _contract_path(execution_value)
    else:
        candidate_root = Path(candidate_value).expanduser().resolve()
        execution_root = Path(execution_value).expanduser().resolve()
    return candidate_root, execution_root, context


def _portable_context(context: Mapping[str, Any]) -> bool:
    return (
        context.get("portability_mode") == PORTABLE_MODE
        or (
            context.get("candidate_root") == LOGICAL_CANDIDATE_ROOT
            and context.get("execution_root") == LOGICAL_EXECUTION_ROOT
        )
    )


def _local_profile_external_authority_not_applicable(
    root: Path,
    target: Mapping[str, Any] | None,
) -> bool:
    if not isinstance(target, Mapping):
        return False
    try:
        profile = json.loads(
            (root / "EPOCH38_GENERATION_PROFILE.json").read_text(
                encoding="utf-8"
            )
        )
    except (OSError, UnicodeError, json.JSONDecodeError):
        return False
    correction = target.get("v2_9_charter_architecture_correction_epoch38")
    threat_model = (
        correction.get("threat_model")
        if isinstance(correction, Mapping)
        else None
    )
    return bool(
        target.get("architecture_epoch") == 4
        and target.get("control_plane_epoch") == 4
        and target.get("assurance_profile_id")
        == "SELF_USE_LOCAL_TRUSTED_OPERATOR"
        and target.get("operating_assurance_profile")
        == "SELF_USE_LOCAL_TRUSTED_OPERATOR"
        and isinstance(threat_model, Mapping)
        and threat_model.get("external_trust_anchor") == "NOT_APPLICABLE"
        and threat_model.get("external_certification_offered") is False
        and isinstance(profile, Mapping)
        and profile.get("profile_kind")
        == "SELF_USE_LOCAL_CORE_CANDIDATE_ROUTE"
        and profile.get("assurance_profile")
        == "SELF_USE_LOCAL_TRUSTED_OPERATOR"
        and profile.get("external_certification_claimed") is False
        and profile.get("optional_security_hardening")
        in {"NOT_APPLICABLE", "NOT_RUN"}
        and profile.get("external_trust_anchor") == "NOT_APPLICABLE"
    )


def _external_receiver_authority_required(
    root: Path,
    target: Mapping[str, Any] | None,
) -> bool:
    if not isinstance(target, Mapping):
        return False
    if _local_profile_external_authority_not_applicable(root, target):
        return False
    try:
        profile = json.loads(
            (root / "EPOCH38_GENERATION_PROFILE.json").read_text(
                encoding="utf-8"
            )
        )
    except (OSError, UnicodeError, json.JSONDecodeError):
        profile = None
    declared_profile = target.get("operating_assurance_profile") or target.get(
        "assurance_profile_id"
    )
    epoch4_active = bool(
        target.get("architecture_epoch") == 4
        and target.get("control_plane_epoch") == 4
    )
    return bool(
        isinstance(target.get("v0_24_human_review_remediation"), Mapping)
        or (
            epoch4_active
            and (
                isinstance(declared_profile, str)
                or (
                    isinstance(profile, Mapping)
                    and (
                        profile.get("external_certification_claimed") is not False
                        or profile.get("optional_security_hardening")
                        not in {"NOT_APPLICABLE", "NOT_RUN"}
                        or profile.get("external_trust_anchor") != "NOT_APPLICABLE"
                    )
                )
            )
        )
    )


def _external_receiver_authority_disposition(
    root: Path,
    target: Mapping[str, Any] | None,
) -> str:
    if _local_profile_external_authority_not_applicable(root, target):
        return "NOT_APPLICABLE_SELF_USE_LOCAL_TRUSTED_OPERATOR"
    if _external_receiver_authority_required(root, target):
        return "REQUIRED_FOR_EXTERNAL_CERTIFICATION"
    return "NOT_APPLICABLE_NO_EXTERNAL_CERTIFICATION_PROFILE"


def _logical_path_within(value: Any, expected_root: Path) -> bool:
    path = _contract_path(value)
    return path == expected_root or path.is_relative_to(expected_root)


def _contract_path(value: Any) -> Path:
    """Map logical Resource URIs to non-filesystem paths for containment checks."""

    text = str(value)
    for uri, virtual_root in (
        (LOGICAL_CANDIDATE_ROOT, VIRTUAL_CANDIDATE_ROOT),
        (LOGICAL_EXECUTION_ROOT, VIRTUAL_EXECUTION_ROOT),
    ):
        if text == uri:
            return virtual_root
        prefix = f"{uri}/"
        if text.startswith(prefix):
            suffix = text[len(prefix) :]
            return virtual_root / suffix
    return Path(text)


def _contract_identity_parts(value: Any) -> tuple[str, ...] | None:
    """Return a strict identity that rejects traversal and foreign URI schemes."""

    text = str(value)
    for uri, identity in (
        (LOGICAL_CANDIDATE_ROOT, ("resource", "candidate")),
        (LOGICAL_EXECUTION_ROOT, ("resource", "execution")),
    ):
        if text == uri:
            return identity
        prefix = f"{uri}/"
        if text.startswith(prefix):
            suffix = text[len(prefix) :]
            pieces = suffix.split("/")
            if not pieces or any(piece in {"", ".", ".."} for piece in pieces):
                return None
            return (*identity, *pieces)
    if "://" in text:
        return None
    path = Path(text)
    raw_pieces = text.replace("\\", "/").split("/")
    if (
        not path.is_absolute()
        or any(piece in {".", ".."} for piece in raw_pieces)
    ):
        return None
    return ("filesystem", path.anchor, *path.parts[1:])


def _contract_path_is_contained(value: Any, allowed_root: Any) -> bool:
    value_parts = _contract_identity_parts(value)
    root_parts = _contract_identity_parts(allowed_root)
    return bool(
        value_parts is not None
        and root_parts is not None
        and value_parts[: len(root_parts)] == root_parts
    )


def _contract_serialized_path(root: Path, relative: str) -> str:
    """Return the persisted form for a path below a physical or logical root."""

    if root == VIRTUAL_CANDIDATE_ROOT:
        return f"{LOGICAL_CANDIDATE_ROOT}/{relative.lstrip('/')}"
    if root == VIRTUAL_EXECUTION_ROOT:
        return f"{LOGICAL_EXECUTION_ROOT}/{relative.lstrip('/')}"
    return str(root / relative)


def _artifact_write_roots_from_refs(
    execution_root: Path, artifact_refs: Sequence[str]
) -> list[str] | None:
    prefix = f"{LOGICAL_EXECUTION_ROOT}/"
    roots: list[str] = []
    for artifact_ref in artifact_refs:
        if not isinstance(artifact_ref, str) or not artifact_ref.startswith(
            prefix
        ):
            return None
        relative = artifact_ref[len(prefix) :]
        if "/" not in relative or any(
            part in {"", ".", ".."} for part in relative.split("/")
        ):
            return None
        root = _contract_serialized_path(
            execution_root, relative.rsplit("/", 1)[0]
        )
        if root not in roots:
            roots.append(root)
    return roots


def _artifact_dependency_read_roots_from_manifest(
    execution_root: Path,
    artifact_manifest: Mapping[str, Any],
    required_artifact_ids: Sequence[str],
) -> list[str] | None:
    artifact_index = artifact_manifest.get("artifact_index")
    if artifact_index is None and "artifact_index" not in artifact_manifest:
        return []
    if not isinstance(artifact_index, Mapping):
        return None
    artifact_refs: list[str] = []
    evidence_refs: list[str] = []
    queue = [str(artifact_id) for artifact_id in required_artifact_ids]
    visited: set[str] = set()
    while queue:
        artifact_id = queue.pop(0)
        if artifact_id in visited:
            continue
        visited.add(artifact_id)
        artifact = artifact_index.get(artifact_id)
        if artifact is None:
            continue
        if not isinstance(artifact, Mapping):
            return None
        for evidence_ref in artifact.get("depends_on_evidence_refs", []):
            if not isinstance(evidence_ref, str) or not evidence_ref:
                return None
            if evidence_ref not in evidence_refs:
                evidence_refs.append(evidence_ref)
        for dependency_id in artifact.get("depends_on_artifact_ids", []):
            dependency_key = str(dependency_id)
            dependency = artifact_index.get(dependency_key)
            if not isinstance(dependency, Mapping):
                return None
            dependency_ref = str(dependency.get("artifact_ref") or "")
            if dependency_ref and dependency_ref not in artifact_refs:
                artifact_refs.append(dependency_ref)
            if dependency_key not in visited:
                queue.append(dependency_key)
    return _artifact_write_roots_from_refs(
        execution_root, [*artifact_refs, *evidence_refs]
    )


def _independent_registry_read_plans(artifact_index):
    """Reconstruct expected Case read domains without importing the Producer."""
    matches = {}
    for identity, artifact in artifact_index.items():
        if not isinstance(artifact, Mapping) or not isinstance(artifact.get("schema"), Mapping):
            return {}
        key = (artifact.get("artifact_kind"), _json_hash(artifact["schema"]))
        matches.setdefault(key, set()).add(identity)
    result = {}
    for key, bases in matches.items():
        closure = set(bases)
        while True:
            if any(identity not in artifact_index for identity in closure):
                return {}
            expanded = closure | {child for identity in closure
                                  for child in artifact_index[identity].get("depends_on_artifact_ids", [])}
            if expanded == closure:
                break
            closure = expanded
        fixture_ids = set()
        for identity in closure:
            for evidence_ref in artifact_index[identity].get("depends_on_evidence_refs", []):
                if evidence_ref.removeprefix(f"{LOGICAL_EXECUTION_ROOT}/") == "evidence/cases" or evidence_ref.startswith(
                    f"{LOGICAL_EXECUTION_ROOT}/evidence/cases/"
                ):
                    fixture_ids.add(identity)
        pending_consumers = True
        while pending_consumers:
            pending_consumers = False
            for identity in closure - fixture_ids:
                if any(child in fixture_ids for child in artifact_index[identity].get("depends_on_artifact_ids", [])):
                    fixture_ids.add(identity)
                    pending_consumers = True
        shared_refs, by_job = set(), {}
        for identity in closure:
            entry = artifact_index[identity]
            ref, job = entry.get("artifact_ref"), entry.get("job_id")
            if not isinstance(ref, str):
                return {}
            if job:
                if not ref.startswith(f"harness-resource://execution/jobs/{job}/"):
                    return {}
            if identity in fixture_ids:
                continue
            if job:
                by_job.setdefault(job, set()).add(ref)
            else:
                shared_refs.add(ref)
        result[key] = {
            "base_artifact_ids": sorted(bases), "shared_artifact_refs": sorted(shared_refs),
            "evaluation_context": "ISOLATED_CONTRACT_FIXTURE",
            "fixture_artifacts": [{"artifact_id": identity,
                "artifact_ref": artifact_index[identity]["artifact_ref"],
                "dependency_artifact_ids": sorted(artifact_index[identity].get("depends_on_artifact_ids", [])),
                "evidence_refs": sorted(artifact_index[identity].get("depends_on_evidence_refs", []))}
                for identity in sorted(fixture_ids)],
            "job_read_partitions": [{"job_id": job, "artifact_refs": sorted(refs),
                "lease_receipt_ref": f"{LOGICAL_EXECUTION_ROOT}/evidence/job_artifact_leases/"
                                     f"LAB-CERTIFICATION/LAB-RUN-REGISTRY-CASE/{job}.lease.json"}
                for job, refs in sorted(by_job.items())],
        }
    return result


def _job_artifact_scopes(
    artifact_roots: Sequence[str], *, roots_field: str
) -> list[dict[str, Any]]:
    scopes: dict[str, list[str]] = {}
    for artifact_root in artifact_roots:
        marker = "/jobs/"
        if marker not in artifact_root:
            continue
        suffix = artifact_root.split(marker, 1)[1]
        job_id = suffix.split("/", 1)[0]
        if job_id and artifact_root not in scopes.setdefault(job_id, []):
            scopes[job_id].append(artifact_root)
    return [
        {"job_id": job_id, roots_field: scopes[job_id]}
        for job_id in sorted(scopes)
    ]


def _expected_job_artifact_lease_contract(
    *,
    command_id: str,
    workpack_id: str,
    read_scopes: Sequence[Mapping[str, Any]],
    write_scopes: Sequence[Mapping[str, Any]],
    selection_cardinality: str = "EXACTLY_ONE_ACTIVE_JOB_LEASE_PER_INVOCATION",
) -> dict[str, Any] | None:
    reads = {
        str(scope.get("job_id")): sorted(
            str(value) for value in scope.get("allowed_read_roots", [])
        )
        for scope in read_scopes
        if isinstance(scope, Mapping) and scope.get("job_id")
    }
    writes = {
        str(scope.get("job_id")): sorted(
            str(value) for value in scope.get("allowed_write_roots", [])
        )
        for scope in write_scopes
        if isinstance(scope, Mapping) and scope.get("job_id")
    }
    job_ids = sorted(set(reads) | set(writes))
    if not job_ids:
        return None
    bindings = []
    for job_id in job_ids:
        read_roots = reads.get(job_id, [])
        write_roots = writes.get(job_id, [])
        scope_document = {
            "job_id": job_id,
            "allowed_read_roots": read_roots,
            "allowed_write_roots": write_roots,
        }
        bindings.append(
            {
                **scope_document,
                "allowed_read_roots_sha256": _json_hash(read_roots),
                "allowed_write_roots_sha256": _json_hash(write_roots),
                "scope_sha256": _json_hash(scope_document),
                "lease_receipt_ref": (
                    f"{LOGICAL_EXECUTION_ROOT}/evidence/job_artifact_leases/"
                    f"{workpack_id}/{command_id}/{job_id}.lease.json"
                ),
            }
        )
    root_array = {
        "type": "array",
        "uniqueItems": True,
        "items": {"type": "string", "minLength": 1},
    }
    hash_field = {"type": "string", "pattern": "^[0-9a-f]{64}$"}
    return {
        "schema_version": "1.0",
        "contract_id": f"JOB-ARTIFACT-LEASE-{workpack_id}-{command_id}",
        "selection_cardinality": selection_cardinality,
        "job_scope_bindings": bindings,
        "receipt_schema": {
            "type": "object",
            "additionalProperties": False,
            "required": [
                "lease_id",
                "program_id",
                "project_id",
                "workpack_id",
                "command_id",
                "job_id",
                "lease_receipt_ref",
                "allowed_read_roots",
                "allowed_read_roots_sha256",
                "allowed_write_roots",
                "allowed_write_roots_sha256",
                "scope_sha256",
                "holder_id",
                "fencing_token",
                "issued_at",
                "expires_at",
                "lease_state_sha256",
                "consumed",
                "status",
            ],
            "properties": {
                "lease_id": {"type": "string", "minLength": 1},
                "program_id": {"type": "string", "minLength": 1},
                "project_id": {"type": "string", "minLength": 1},
                "workpack_id": {"const": workpack_id},
                "command_id": {"const": command_id},
                "job_id": {"enum": job_ids},
                "lease_receipt_ref": {
                    "enum": [item["lease_receipt_ref"] for item in bindings]
                },
                "allowed_read_roots": deepcopy(root_array),
                "allowed_read_roots_sha256": deepcopy(hash_field),
                "allowed_write_roots": deepcopy(root_array),
                "allowed_write_roots_sha256": deepcopy(hash_field),
                "scope_sha256": deepcopy(hash_field),
                "holder_id": {"type": "string", "minLength": 1},
                "fencing_token": {"type": "integer", "minimum": 1},
                "issued_at": {"type": "string", "format": "date-time"},
                "expires_at": {"type": "string", "format": "date-time"},
                "lease_state_sha256": deepcopy(hash_field),
                "consumed": {"const": False},
                "status": {"const": "ACTIVE"},
            },
            "oneOf": [
                {
                    "properties": {
                        "job_id": {"const": item["job_id"]},
                        "lease_receipt_ref": {
                            "const": item["lease_receipt_ref"]
                        },
                        "allowed_read_roots": {
                            "const": item["allowed_read_roots"]
                        },
                        "allowed_read_roots_sha256": {
                            "const": item["allowed_read_roots_sha256"]
                        },
                        "allowed_write_roots": {
                            "const": item["allowed_write_roots"]
                        },
                        "allowed_write_roots_sha256": {
                            "const": item["allowed_write_roots_sha256"]
                        },
                        "scope_sha256": {"const": item["scope_sha256"]},
                    }
                }
                for item in bindings
            ],
            "x-invariants": [
                "LEASE_PROGRAM_PROJECT_WORKPACK_AND_COMMAND_MATCH_INVOCATION",
                "LEASE_JOB_ID_SELECTS_EXACTLY_ONE_DECLARED_SCOPE_BINDING",
                "LEASE_RECEIPT_REF_MATCHES_SELECTED_JOB_BINDING",
                "LEASE_READ_AND_WRITE_ROOTS_EQUAL_SELECTED_JOB_SCOPE",
                "LEASE_ROOT_AND_SCOPE_SHA256S_RECOMPUTE_FROM_CANONICAL_ARRAYS",
                "LEASE_FENCING_TOKEN_IS_CURRENT_AND_SINGLE_USE",
                "LEASE_ISSUED_AT_PRECEDES_EXPIRES_AT_AND_IS_NOT_EXPIRED",
            ],
        },
        "failure_codes": [
            "JOB_ARTIFACT_LEASE_MISSING",
            "JOB_ARTIFACT_LEASE_CARDINALITY_INVALID",
            "JOB_ARTIFACT_LEASE_SCOPE_MISMATCH",
            "JOB_ARTIFACT_LEASE_FENCING_TOKEN_INVALID",
            "JOB_ARTIFACT_LEASE_EXPIRED",
            "JOB_ARTIFACT_LEASE_REPLAYED",
        ],
    }


def _acceptance_write_roots(bundle: Mapping[str, Any] | None) -> list[str] | None:
    """Independently check the producer role of post-observation control results."""
    if bundle is None:
        return []
    roots = []
    try:
        for task in bundle["task_contracts"]:
            for artifact in task["artifact_obligations"]:
                control = artifact.get("artifact_kind") == "WORKPACK_CONTROL_RESULT"
                owner = artifact.get("production_owner") == "WORKPACK_ACCEPTANCE_CONTROLLER"
                if control != owner or control and artifact.get("production_timing") != "AFTER_NATIVE_COMMANDS_AND_ORACLES":
                    return None
                if control:
                    root = artifact["artifact_ref"].rsplit("/", 1)[0]
                    if root not in roots:
                        roots.append(root)
    except (KeyError, TypeError, AttributeError):
        return None
    return roots


def _expected_workpack_commands(
    commands_by_id: Mapping[str, Mapping[str, Any]],
    command_ids: Sequence[str],
    artifact_write_roots: Sequence[str],
    artifact_read_roots: Sequence[str] = (),
    *,
    workpack_id: str,
    workpack_read_roots: Sequence[str] = (),
    acceptance_write_roots: Sequence[str] = (),
) -> list[dict[str, Any]] | None:
    job_scopes: dict[str, list[str]] = {}
    shared_roots: list[str] = []
    for artifact_root in artifact_write_roots:
        if artifact_root in acceptance_write_roots:
            continue
        marker = "/jobs/"
        if marker in artifact_root:
            suffix = artifact_root.split(marker, 1)[1]
            job_id = suffix.split("/", 1)[0]
            if job_id:
                job_scopes.setdefault(job_id, []).append(artifact_root)
                continue
        shared_roots.append(artifact_root)
    shared_read_roots = [
        root for root in artifact_read_roots if "/jobs/" not in root
    ]

    commands: list[dict[str, Any]] = []
    for command_id in command_ids:
        source = commands_by_id.get(command_id)
        if not isinstance(source, Mapping):
            return None
        command = deepcopy(dict(source))
        command.pop("workpack_artifact_write_roots", None)
        command.pop("shared_artifact_write_roots", None)
        command.pop("job_artifact_write_scopes", None)
        command.pop("job_artifact_read_scopes", None)
        command.pop("job_artifact_lease_contract", None)
        command.pop("shared_artifact_read_roots", None)
        roots = [
            root
            for root in command.get("allowed_write_roots") or []
            if root not in artifact_write_roots
        ]
        is_coding_command = command_id.endswith("CODEX-CODING")
        for artifact_root in shared_roots:
            if artifact_root not in roots:
                roots.append(artifact_root)
        command["allowed_write_roots"] = roots
        read_roots = [
            root
            for root in command.get("allowed_read_roots") or []
            if root not in artifact_read_roots
        ]
        for artifact_root in [*workpack_read_roots, *shared_read_roots]:
            if artifact_root not in read_roots:
                read_roots.append(artifact_root)
        command["allowed_read_roots"] = read_roots
        command["shared_artifact_read_roots"] = list(shared_read_roots)
        command["shared_artifact_write_roots"] = list(shared_roots)
        command["job_artifact_write_scopes"] = (
            [
                {"job_id": job_id, "allowed_write_roots": job_scopes[job_id]}
                for job_id in sorted(job_scopes)
            ]
            if is_coding_command
            else []
        )
        command["artifact_write_scope_mode"] = (
            "ONE_JOB_LEASE_REQUIRED"
            if is_coding_command and job_scopes
            else "SHARED_ONLY"
            if shared_roots
            else "NONE"
        )
        is_case_runner = command_id in {"LAB-RUN-CASE-PARTITION", "LAB-RUN-REGISTRY-CASE"}
        lease_eligible = is_coding_command or (
            workpack_id == CASE_EVIDENCE_WRITER_WORKPACK_ID
            and is_case_runner
        )
        command["job_artifact_read_scopes"] = (
            _job_artifact_scopes(
                artifact_read_roots, roots_field="allowed_read_roots"
            )
            if lease_eligible
            else []
        )
        command["artifact_read_scope_mode"] = (
            "ONE_JOB_LEASE_REQUIRED"
            if lease_eligible and command["job_artifact_read_scopes"]
            else "SHARED_ONLY"
            if shared_read_roots
            else "NONE"
        )
        lease_contract = (
            _expected_job_artifact_lease_contract(
                command_id=command_id,
                workpack_id=workpack_id,
                read_scopes=command["job_artifact_read_scopes"],
                write_scopes=command["job_artifact_write_scopes"],
                selection_cardinality=(
                    "EXACTLY_ONE_ACTIVE_JOB_LEASE_PER_REGISTRY_READ_PARTITION"
                    if command_id == "LAB-RUN-REGISTRY-CASE"
                    else "EXACTLY_ONE_ACTIVE_JOB_LEASE_PER_CASE_PARTITION"
                    if is_case_runner
                    else "EXACTLY_ONE_ACTIVE_JOB_LEASE_PER_INVOCATION"
                ),
            )
            if lease_eligible
            else None
        )
        command["job_artifact_lease_required"] = lease_contract is not None
        command["job_artifact_lease_contract"] = lease_contract
        command["active_job_artifact_lease_ref"] = None
        command["job_artifact_scope_activation_policy"] = (
            "NO_JOB_ARTIFACT_ROOT_IS_ACTIVE_WITHOUT_EXACTLY_ONE_CURRENT_LEASE"
            if lease_contract is not None
            else "NO_JOB_ARTIFACT_SCOPE"
        )
        if command_id == "MB-TEST":
            executable = str(
                command.get("executable_abs") or command.get("executable") or ""
            )
            execution_root = executable.split("/project_start_packages/", 1)[0]
            test_temp_root = (
                f"{execution_root}/evidence/project_workpacks/"
                f"MAIN_HARNESS_BUILD/{workpack_id}/pytest-tmp"
            )
            command["argv"] = [
                executable,
                "-B",
                "-m",
                "pytest",
                "-p",
                "no:cacheprovider",
                "--basetemp",
                test_temp_root,
                "tests",
            ]
            command["environment"] = {
                "PYTHONDONTWRITEBYTECODE": "1",
                "PYTEST_DISABLE_PLUGIN_AUTOLOAD": "1",
                "PYTHONHASHSEED": "0",
            }
            command["allowed_write_roots"] = [test_temp_root]
            command["test_repository_write_policy"] = (
                "FORBIDDEN_VERIFY_SNAPSHOT_BEFORE_AFTER"
            )
        if command.get("executor_role") == "INDEPENDENT_PROJECT_VERIFIER":
            command["allowed_write_roots"] = []
            command["shared_artifact_write_roots"] = []
            command["artifact_write_scope_mode"] = "NONE"
        command["command_sha256"] = _hash_without_field(
            command, "command_sha256"
        )
        commands.append(command)
    return commands


def _job_artifact_lease_contract_is_valid(
    command: Mapping[str, Any], *, workpack_id: str
) -> bool:
    read_scopes = command.get("job_artifact_read_scopes")
    write_scopes = command.get("job_artifact_write_scopes")
    if not isinstance(read_scopes, list) or not isinstance(write_scopes, list):
        return False
    job_ids = sorted(
        {
            str(scope.get("job_id"))
            for scope in [*read_scopes, *write_scopes]
            if isinstance(scope, Mapping) and scope.get("job_id")
        }
    )
    is_coding = str(command.get("command_id") or "").endswith("CODEX-CODING")
    is_lab_case_runner = (
        workpack_id == CASE_EVIDENCE_WRITER_WORKPACK_ID
        and str(command.get("command_id") or "")
        in {"LAB-RUN-CASE-PARTITION", "LAB-RUN-REGISTRY-CASE"}
    )
    required = (is_coding or is_lab_case_runner) and bool(job_ids)
    if command.get("job_artifact_lease_required") is not required:
        return False
    if command.get("active_job_artifact_lease_ref") is not None:
        return False
    expected_policy = (
        "NO_JOB_ARTIFACT_ROOT_IS_ACTIVE_WITHOUT_EXACTLY_ONE_CURRENT_LEASE"
        if required
        else "NO_JOB_ARTIFACT_SCOPE"
    )
    if command.get("job_artifact_scope_activation_policy") != expected_policy:
        return False
    contract = command.get("job_artifact_lease_contract")
    if not required:
        return contract is None
    if not isinstance(contract, Mapping):
        return False
    bindings = contract.get("job_scope_bindings")
    receipt_schema = contract.get("receipt_schema")
    expected_selection_cardinality = (
        "EXACTLY_ONE_ACTIVE_JOB_LEASE_PER_REGISTRY_READ_PARTITION"
        if command.get("command_id") == "LAB-RUN-REGISTRY-CASE"
        else "EXACTLY_ONE_ACTIVE_JOB_LEASE_PER_CASE_PARTITION"
        if is_lab_case_runner
        else "EXACTLY_ONE_ACTIVE_JOB_LEASE_PER_INVOCATION"
    )
    if (
        contract.get("selection_cardinality")
        != expected_selection_cardinality
        or not isinstance(bindings, list)
        or len(bindings) != len(job_ids)
        or not isinstance(receipt_schema, Mapping)
    ):
        return False
    read_by_job = {
        str(scope["job_id"]): sorted(scope.get("allowed_read_roots", []))
        for scope in read_scopes
        if isinstance(scope, Mapping) and scope.get("job_id")
    }
    write_by_job = {
        str(scope["job_id"]): sorted(scope.get("allowed_write_roots", []))
        for scope in write_scopes
        if isinstance(scope, Mapping) and scope.get("job_id")
    }
    binding_ids: list[str] = []
    for binding in bindings:
        if not isinstance(binding, Mapping) or not binding.get("job_id"):
            return False
        job_id = str(binding["job_id"])
        binding_ids.append(job_id)
        read_roots = read_by_job.get(job_id, [])
        write_roots = write_by_job.get(job_id, [])
        scope_document = {
            "job_id": job_id,
            "allowed_read_roots": read_roots,
            "allowed_write_roots": write_roots,
        }
        if (
            binding.get("allowed_read_roots") != read_roots
            or binding.get("allowed_write_roots") != write_roots
            or binding.get("allowed_read_roots_sha256") != _json_hash(read_roots)
            or binding.get("allowed_write_roots_sha256") != _json_hash(write_roots)
            or binding.get("scope_sha256") != _json_hash(scope_document)
            or binding.get("lease_receipt_ref")
            != (
                f"{LOGICAL_EXECUTION_ROOT}/evidence/job_artifact_leases/"
                f"{workpack_id}/{command.get('command_id')}/{job_id}.lease.json"
            )
        ):
            return False
    required_receipt_fields = {
        "lease_id",
        "program_id",
        "project_id",
        "workpack_id",
        "command_id",
        "job_id",
        "lease_receipt_ref",
        "allowed_read_roots",
        "allowed_read_roots_sha256",
        "allowed_write_roots",
        "allowed_write_roots_sha256",
        "scope_sha256",
        "holder_id",
        "fencing_token",
        "issued_at",
        "expires_at",
        "lease_state_sha256",
        "consumed",
        "status",
    }
    properties = receipt_schema.get("properties")
    expected_selection_branches = [
        {
            "properties": {
                "job_id": {"const": binding["job_id"]},
                "lease_receipt_ref": {
                    "const": binding["lease_receipt_ref"]
                },
                "allowed_read_roots": {
                    "const": binding["allowed_read_roots"]
                },
                "allowed_read_roots_sha256": {
                    "const": binding["allowed_read_roots_sha256"]
                },
                "allowed_write_roots": {
                    "const": binding["allowed_write_roots"]
                },
                "allowed_write_roots_sha256": {
                    "const": binding["allowed_write_roots_sha256"]
                },
                "scope_sha256": {"const": binding["scope_sha256"]},
            }
        }
        for binding in bindings
    ]
    return bool(
        sorted(binding_ids) == job_ids
        and len(set(binding_ids)) == len(binding_ids)
        and receipt_schema.get("type") == "object"
        and receipt_schema.get("additionalProperties") is False
        and required_receipt_fields.issubset(set(receipt_schema.get("required", [])))
        and isinstance(properties, Mapping)
        and properties.get("workpack_id", {}).get("const") == workpack_id
        and properties.get("command_id", {}).get("const")
        == command.get("command_id")
        and properties.get("job_id", {}).get("enum") == job_ids
        and receipt_schema.get("oneOf") == expected_selection_branches
        and properties.get("consumed", {}).get("const") is False
        and properties.get("status", {}).get("const") == "ACTIVE"
        and len(receipt_schema.get("x-invariants", [])) >= 7
        and {
            "JOB_ARTIFACT_LEASE_MISSING",
            "JOB_ARTIFACT_LEASE_CARDINALITY_INVALID",
            "JOB_ARTIFACT_LEASE_SCOPE_MISMATCH",
            "JOB_ARTIFACT_LEASE_FENCING_TOKEN_INVALID",
            "JOB_ARTIFACT_LEASE_EXPIRED",
            "JOB_ARTIFACT_LEASE_REPLAYED",
        }.issubset(set(contract.get("failure_codes", [])))
    )


def _is_nonexecutable_negative_fixture(case: Any) -> bool:
    atom_ids = case.get("atom_ids") if isinstance(case, Mapping) else None
    return bool(
        isinstance(case, Mapping)
        and isinstance(case.get("case_id"), str)
        and case["case_id"].startswith("NEG-")
        and isinstance(atom_ids, list)
        and atom_ids
        and all(isinstance(atom_id, str) and atom_id for atom_id in atom_ids)
        and isinstance(case.get("description"), str)
        and bool(case["description"].strip())
        and isinstance(case.get("expected_failure"), str)
        and bool(case["expected_failure"].strip())
        and case.get("fixture_kind") == "NON_EXECUTABLE_JSON"
        and isinstance(case.get("input_fixture"), Mapping)
        and bool(case["input_fixture"])
        and isinstance(case.get("origin"), str)
        and bool(case["origin"].strip())
    )


def _structured_negative_mutation(value: Any, expected_failure: Any) -> bool:
    allowed_operations = {
        "SET_FIELD",
        "REMOVE_REQUIRED_FIELD",
        "REMOVE_CONDITIONALLY_REQUIRED_FIELD",
        "REPLACE_HASH",
        "SET_OUT_OF_RANGE_VALUE",
        "SET_ORDER",
        "ADD_ACTIVE_LEASE",
        "REPLAY_ATTESTATION",
        "SUBSTITUTE_OUTPUT",
        "REPLACE_EXECUTOR",
        "OMIT_STAGE_RECEIPT",
        "CHANGE_LOCKED_HASH",
        "REMOVE_AUTHORIZATION",
        "DUPLICATE_SIDE_EFFECT",
        "INVALIDATE_UPSTREAM",
        "REQUEST_FORBIDDEN_ACTION",
    }
    return bool(
        isinstance(value, Mapping)
        and isinstance(value.get("operation"), str)
        and value["operation"] in allowed_operations
        and isinstance(value.get("target_ref"), str)
        and value["target_ref"].strip()
        and not value["target_ref"].startswith("validation-input://")
        and "invalid_value" in value
        and isinstance(value.get("violated_constraint"), Mapping)
        and bool(value["violated_constraint"])
        and isinstance(value.get("target_binding"), Mapping)
        and not (
            isinstance(value.get("invalid_value"), Mapping)
            and set(value["invalid_value"]) == {"declared_violation"}
        )
        and value.get("expected_failure") == expected_failure
    )


def _schema_pointer_resolves(schema: Any, pointer: str) -> bool:
    if not isinstance(schema, Mapping) or not pointer.startswith("/"):
        return False
    current: Any = schema
    for raw_token in pointer[1:].split("/"):
        token = raw_token.replace("~1", "/").replace("~0", "~")
        if token.isdigit():
            current = current.get("items") if isinstance(current, Mapping) else None
        else:
            properties = (
                current.get("properties")
                if isinstance(current, Mapping)
                else None
            )
            current = properties.get(token) if isinstance(properties, Mapping) else None
        if not isinstance(current, Mapping):
            return False
    return True


def _resolvable_negative_target_binding(
    value: Any,
    *,
    artifact_index: Mapping[str, Any],
    fixture_jobs: list[Any],
) -> bool:
    if not isinstance(value, Mapping):
        return False
    resolver = value.get("resolver")
    pointers = value.get("json_pointers")
    if (
        not isinstance(pointers, list)
        or not pointers
        or any(
            not isinstance(pointer, str) or not pointer.startswith("/")
            for pointer in pointers
        )
    ):
        return False
    if resolver == "ARTIFACT_MANIFEST_SCHEMA_POINTER_V1":
        artifact_kind = value.get("artifact_kind")
        artifact_ids = value.get("artifact_ids")
        artifact_refs = value.get("artifact_refs")
        if (
            value.get("resource_kind") != "DECLARED_ARTIFACT_SET"
            or value.get("application_cardinality")
            != "EVERY_MATCHED_ARTIFACT"
            or not isinstance(artifact_kind, str)
            or not isinstance(artifact_ids, list)
            or not artifact_ids
            or len(artifact_ids) != len(set(artifact_ids))
            or not isinstance(artifact_refs, list)
            or len(artifact_refs) != len(artifact_ids)
        ):
            return False
        for artifact_id, artifact_ref in zip(
            artifact_ids, artifact_refs, strict=True
        ):
            artifact = artifact_index.get(artifact_id)
            if (
                not isinstance(artifact_id, str)
                or not isinstance(artifact_ref, str)
                or not isinstance(artifact, Mapping)
                or artifact.get("artifact_kind") != artifact_kind
                or artifact.get("artifact_ref") != artifact_ref
                or any(
                    not _schema_pointer_resolves(
                        artifact.get("schema"), pointer
                    )
                    for pointer in pointers
                )
            ):
                return False
        return True
    if resolver == "FIXTURE_INPUT_JSON_POINTER_V1":
        selector = value.get("instance_selector")
        declared_job_ids = sorted(
            str(item["job_id"])
            for item in fixture_jobs
            if isinstance(item, Mapping) and item.get("job_id")
        )
        return bool(
            value.get("resource_kind") == "FIXTURE_JOB_SET"
            and isinstance(value.get("base_input_ref"), str)
            and value["base_input_ref"].startswith(
                "harness-resource://candidate/validation/case_fixtures/"
            )
            and isinstance(selector, Mapping)
            and selector.get("match_field") == "job_id"
            and selector.get("cardinality") == "EXACT_DECLARED_JOB_SET"
            and selector.get("match_values") == declared_job_ids
            and bool(declared_job_ids)
        )
    if resolver == "EXECUTION_INPUT_JSON_POINTER_V1":
        return bool(
            value.get("resource_kind")
            == "DECLARED_EXECUTION_VALIDATION_INPUT"
            and isinstance(value.get("base_input_ref"), str)
            and value["base_input_ref"].startswith(
                "harness-resource://execution/validation-inputs/"
            )
            and value.get("materialization_requirement")
            == "MUST_EXIST_BEFORE_MUTATION_APPLICATION"
        )
    return False


def _concrete_negative_input(
    value: Any,
    expected_failure: Any,
    *,
    artifacts_declared: bool,
    artifact_index: Mapping[str, Any] | None = None,
) -> bool:
    if not isinstance(value, Mapping) or not value:
        return False
    if "mutation" in value:
        resolved_artifact_index = (
            artifact_index if isinstance(artifact_index, Mapping) else {}
        )
        fixture_jobs = (
            value.get("fixture_jobs")
            if isinstance(value.get("fixture_jobs"), list)
            else []
        )
        if not _structured_negative_mutation(
            value.get("mutation"), expected_failure
        ) or not _resolvable_negative_target_binding(
            value["mutation"].get("target_binding"),
            artifact_index=resolved_artifact_index,
            fixture_jobs=fixture_jobs,
        ):
            return False
        variants = value.get("mutation_variants")
        mutation_manifest = value.get("mutation_manifest")
        fixture_id = str(value.get("fixture_id") or "")
        expected_variants_by_fixture = {
            "FIXTURE-NEG-MULTI-SKILL-OR-DURATION-DRIFT": {
                "MULTI-SKILL",
                "DURATION-DRIFT",
                "WRONG-CANVAS-OR-FPS",
                "FORCED-NARRATION-SPEED",
            },
            "FIXTURE-NEG-UNSUPPORTED-EFFECT-OR-FAKE-DEMO": {
                "UNSUPPORTED-EFFECT",
                "ILLUSTRATION-LABELED-ACTUAL",
            },
            "FIXTURE-NEG-CLOUD-TTS-OR-APPROXIMATE-SYNC": {
                "CLOUD-TTS",
                "MISSING-FORCED-ALIGNMENT",
                "SCENE-ONLY-APPROXIMATE-TIMING",
                "INCOMPLETE-OBJECT-SET",
                "TIMING-TOLERANCE-EXCEEDED",
            },
            "FIXTURE-NEG-UNROUTED-ASSET-OR-EXTERNAL-ANIMATION": {
                "OBJECT-WITHOUT-PROVENANCE",
                "UNAUTHORIZED-CODEX-IMAGEGEN",
                "EXTERNAL-TEXT-TO-VIDEO",
                "UNPINNED-SHOTCRAFT",
            },
            "FIXTURE-NEG-UNAUTHORIZED-TARGET-EXECUTION-OR-FALSE-RESUME": {
                "DENIED-GATE-SIDE-EFFECT",
                "PROGRAM-WIDE-AUTHORIZATION-SUBSTITUTION",
                "STALE-AUTHORIZATION-OR-INPUT-HASH",
                "CONSUMED-AUTHORIZATION-REPLAY",
                "FALSE-RESUME-SIDE-EFFECT-REPLAY",
            },
            "FIXTURE-NEG-FIXTURE-NARRATIVE-PASS-OR-AUTHORING-EXECUTION": {
                "MISSING-FIXTURE-EVIDENCE",
                "NARRATIVE-PASS",
                "DEPENDENCY-INSTALL",
                "MODEL-DOWNLOAD",
                "MEDIA-RENDER",
                "WORKPACK-START",
                "DRIVER-START",
                "EXECUTION-ROOT-CREATE",
            },
        }
        actual_variant_ids = {
            str(item.get("variant_id"))
            for item in variants or []
            if isinstance(item, Mapping)
        }
        expected_variant_ids = expected_variants_by_fixture.get(fixture_id)
        artifact_expectations = value.get("artifact_expectations")
        expected_dependency_mode = (
            "DECLARED_PRODUCTION_ARTIFACTS"
            if artifacts_declared
            else "NO_DECLARED_PRODUCTION_ARTIFACTS"
        )
        return bool(
            isinstance(variants, list)
            and variants
            and len(actual_variant_ids) == len(variants)
            and (
                expected_variant_ids is None
                or actual_variant_ids == expected_variant_ids
            )
            and all(
                isinstance(item, Mapping)
                and isinstance(item.get("variant_id"), str)
                and item["variant_id"]
                and _structured_negative_mutation(
                    item.get("mutation"), expected_failure
                )
                and _resolvable_negative_target_binding(
                    item["mutation"].get("target_binding"),
                    artifact_index=resolved_artifact_index,
                    fixture_jobs=fixture_jobs,
                )
                for item in variants
            )
            and mutation_manifest == variants
            and value.get("mutation_manifest_sha256")
            == _json_hash(mutation_manifest)
            and isinstance(artifact_expectations, list)
            and bool(artifact_expectations) is artifacts_declared
            and value.get("artifact_dependency_mode")
            == expected_dependency_mode
            and isinstance(value.get("fixture_jobs"), list)
        )
    return bool(
        set(value)
        - {
            "fixture_id",
            "atom_ids",
            "description",
        }
    )


def _strict_case_result_schema(schema: Any) -> bool:
    if not isinstance(schema, Mapping):
        return False
    schema_properties = schema.get("properties")
    if not isinstance(schema_properties, Mapping):
        return False
    assertion_results = schema_properties.get("assertion_results")
    items = (
        assertion_results.get("items")
        if isinstance(assertion_results, Mapping)
        else None
    )
    required = set(items.get("required", [])) if isinstance(items, Mapping) else set()
    properties = items.get("properties") if isinstance(items, Mapping) else None
    artifact_checks = schema_properties.get("artifact_checks")
    artifact_items = (
        artifact_checks.get("items")
        if isinstance(artifact_checks, Mapping)
        else None
    )
    artifact_required = (
        set(artifact_items.get("required", []))
        if isinstance(artifact_items, Mapping)
        else set()
    )
    source_jobs = schema_properties.get("source_job_bindings")
    source_job_items = (
        source_jobs.get("items") if isinstance(source_jobs, Mapping) else None
    )
    mutation_results = schema_properties.get("mutation_variant_results")
    mutation_items = (
        mutation_results.get("items")
        if isinstance(mutation_results, Mapping)
        else None
    )
    mutation_required = (
        set(mutation_items.get("required", []))
        if isinstance(mutation_items, Mapping)
        else set()
    )
    partition_results = schema_properties.get("job_partition_results")
    partition_items = (
        partition_results.get("items")
        if isinstance(partition_results, Mapping)
        else None
    )
    partition_required = (
        set(partition_items.get("required", []))
        if isinstance(partition_items, Mapping)
        else set()
    )
    all_of = schema.get("allOf")
    serialized_conditions = json.dumps(all_of, sort_keys=True, default=str)
    expected_ref_bindings = [
        {
            "ref_pointer": "/command_receipt_ref",
            "sha256_pointer": "/command_receipt_sha256",
            "pairing": "SINGLE",
        },
        {
            "ref_pointer": "/job_partition_results/*/lease_receipt_ref",
            "sha256_pointer": (
                "/job_partition_results/*/lease_receipt_sha256"
            ),
            "pairing": "SAME_ARRAY_ITEM",
        },
        {
            "ref_pointer": "/job_partition_results/*/result_fragment_ref",
            "sha256_pointer": (
                "/job_partition_results/*/result_fragment_sha256"
            ),
            "pairing": "SAME_ARRAY_ITEM",
        },
        {
            "ref_pointer": (
                "/job_partition_results/*/fragment_artifact_manifest_ref"
            ),
            "sha256_pointer": (
                "/job_partition_results/*/fragment_artifact_manifest_sha256"
            ),
            "pairing": "SAME_ARRAY_ITEM",
        },
        {
            "ref_pointer": "/aggregation_receipt_ref",
            "sha256_pointer": "/aggregation_receipt_sha256",
            "pairing": "SINGLE",
        },
    ]
    expected_lineage_evaluator = {
        "evaluator_id": "CASE_RESULT_REF_SHA256_LINEAGE_V1",
        "implementation_entrypoint": (
            "external_lab.oracle:verify_ref_sha256_bindings_v1"
        ),
        "algorithm_version": "1.0",
        "hash_algorithm": "SHA-256",
        "byte_mode": "EXACT_REFERENCED_BYTES_NO_REENCODING",
        "unknown_or_unresolved_ref_disposition": "FAIL_CLOSED",
        "failure_code": "CASE_RESULT_BYTE_LINEAGE_MISMATCH",
    }
    return bool(
        schema.get("type") == "object"
        and schema.get("additionalProperties") is False
        and {
            "case_id",
            "case_kind",
            "fixture_sha256",
            "assertion_manifest_sha256",
            "command_receipt_ref",
            "command_receipt_sha256",
            "job_partition_results",
            "job_partition_manifest_sha256",
            "aggregation_receipt_ref",
            "aggregation_receipt_sha256",
            "assertion_results",
            "oracle_decision",
            "status",
        }.issubset(set(schema.get("required", [])))
        and schema_properties.get("case_kind", {}).get("enum")
        == ["ACCEPTANCE", "NEGATIVE"]
        and isinstance(assertion_results, Mapping)
        and assertion_results.get("type") == "array"
        and assertion_results.get("uniqueItems") is True
        and isinstance(items, Mapping)
        and items.get("type") == "object"
        and {
            "assertion_id",
            "operator",
            "passed",
            "actual",
            "expected",
            "evidence_refs",
        }.issubset(required)
        and isinstance(properties, Mapping)
        and isinstance(properties.get("operator", {}).get("enum"), list)
        and {
            "VALIDATED_RECEIPT_EXISTS",
            "SET_EQUALS",
            "ALL_ARTIFACTS_SCHEMA_HASH_AND_ORACLE_PASS",
            "EXACT_SOURCE_JOBS_MATCH",
            "EQUALS",
        }.issubset(set(properties["operator"]["enum"]))
        and properties.get("passed", {}).get("type") == "boolean"
        and properties.get("evidence_refs", {}).get("minItems", 0) >= 1
        and isinstance(partition_results, Mapping)
        and partition_results.get("type") == "array"
        and partition_results.get("uniqueItems") is True
        and isinstance(partition_items, Mapping)
        and partition_items.get("additionalProperties") is False
        and {
            "job_id",
            "lease_receipt_ref",
            "lease_receipt_sha256",
            "result_fragment_ref",
            "result_fragment_sha256",
            "fragment_artifact_manifest_ref",
            "fragment_artifact_manifest_sha256",
        }.issubset(partition_required)
        and schema_properties.get("job_partition_manifest_sha256", {}).get(
            "pattern"
        )
        == "^[0-9a-f]{64}$"
        and schema_properties.get("aggregation_receipt_ref", {}).get(
            "minLength"
        )
        == 1
        and schema_properties.get("aggregation_receipt_sha256", {}).get(
            "pattern"
        )
        == "^[0-9a-f]{64}$"
        and schema.get("x-ref-sha256-bindings") == expected_ref_bindings
        and schema.get("x-byte-lineage-evaluator")
        == expected_lineage_evaluator
        and isinstance(artifact_checks, Mapping)
        and artifact_checks.get("type") == "array"
        and artifact_checks.get("minItems", 0) >= 1
        and artifact_checks.get("uniqueItems") is True
        and isinstance(artifact_items, Mapping)
        and artifact_items.get("additionalProperties") is False
        and {
            "artifact_id",
            "job_id",
            "source_id",
            "artifact_ref",
            "schema_sha256",
            "oracle_pass",
            "evidence_refs",
        }.issubset(artifact_required)
        and isinstance(source_jobs, Mapping)
        and source_jobs.get("type") == "array"
        and source_jobs.get("minItems", 0) >= 1
        and source_jobs.get("uniqueItems") is True
        and isinstance(source_job_items, Mapping)
        and source_job_items.get("additionalProperties") is False
        and {
            "job_id",
            "source_id",
            "repository_url",
            "commit_sha",
        }.issubset(set(source_job_items.get("required", [])))
        and {
            "observed_failure_code",
            "expected_failure_observed",
            "mutation_manifest_sha256",
            "mutation_variant_results",
            "side_effect_receipt_ref",
            "side_effect_receipt_sha256",
            "side_effects_started",
        }.issubset(set(schema_properties))
        and isinstance(mutation_results, Mapping)
        and mutation_results.get("type") == "array"
        and mutation_results.get("minItems", 0) >= 1
        and mutation_results.get("uniqueItems") is True
        and isinstance(mutation_items, Mapping)
        and mutation_items.get("additionalProperties") is False
        and {
            "variant_id",
            "base_input_ref",
            "base_input_sha256",
            "mutated_input_ref",
            "mutated_input_sha256",
            "mutation_receipt_ref",
            "mutation_receipt_sha256",
            "command_receipt_ref",
            "command_receipt_sha256",
            "validator_finding_ref",
            "validator_finding_sha256",
            "side_effect_receipt_ref",
            "side_effect_receipt_sha256",
            "observed_failure_code",
            "expected_failure_observed",
            "side_effects_started",
            "status",
        }.issubset(mutation_required)
        and isinstance(all_of, list)
        and len(all_of) >= 4
        and '"case_kind": {"const": "ACCEPTANCE"}' in serialized_conditions
        and '"case_kind": {"const": "NEGATIVE"}' in serialized_conditions
        and '"passed": {"const": false}' in serialized_conditions
    )


def _strict_case_specific_result_schema(
    schema: Any,
    fixture: Any,
    *,
    negative: bool,
    job_read_partitions: Sequence[Mapping[str, Any]],
) -> bool:
    if not isinstance(schema, Mapping) or not isinstance(fixture, Mapping):
        return False
    properties = schema.get("properties")
    bindings = fixture.get("oracle_bindings")
    assertions = fixture.get("assertions")
    if (
        not isinstance(properties, Mapping)
        or not isinstance(bindings, Mapping)
        or not isinstance(assertions, list)
    ):
        return False
    assertion_results = properties.get("assertion_results")
    assertion_constraints = (
        assertion_results.get("allOf")
        if isinstance(assertion_results, Mapping)
        else None
    )
    required = set(schema.get("required", []))
    partition_results = properties.get("job_partition_results")
    partition_constraints = (
        partition_results.get("allOf")
        if isinstance(partition_results, Mapping)
        else None
    )
    serialized_partitions = json.dumps(
        partition_constraints, ensure_ascii=False, sort_keys=True
    )
    if not (
        properties.get("case_id", {}).get("const") == fixture.get("case_id")
        and properties.get("case_kind", {}).get("const")
        == fixture.get("case_kind")
        and properties.get("assertion_manifest_sha256", {}).get("const")
        == bindings.get("assertion_manifest_sha256")
        and isinstance(assertion_results, Mapping)
        and assertion_results.get("uniqueItems") is True
        and assertion_results.get("minItems") == len(assertions)
        and assertion_results.get("maxItems") == len(assertions)
        and isinstance(assertion_constraints, list)
        and len(assertion_constraints) == len(assertions)
        and {
            "job_partition_results",
            "job_partition_manifest_sha256",
            "aggregation_receipt_ref",
            "aggregation_receipt_sha256",
        }.issubset(required)
        and properties.get("job_partition_manifest_sha256", {}).get("const")
        == _json_hash([dict(item) for item in job_read_partitions])
        and properties.get("aggregation_receipt_ref", {}).get("const")
        == (
            f"{CASE_EXECUTION_RESULT_ROOT_REF}/aggregation/"
            f"{str(fixture.get('case_kind')).lower()}-"
            f"{_slug(str(fixture.get('case_id'))).lower()}.receipt.json"
        )
        and isinstance(partition_results, Mapping)
        and partition_results.get("uniqueItems") is True
        and partition_results.get("minItems") == len(job_read_partitions)
        and partition_results.get("maxItems") == len(job_read_partitions)
        and isinstance(partition_constraints, list)
        and len(partition_constraints) == len(job_read_partitions)
        and all(
            json.dumps(str(item.get("job_id") or ""))
            in serialized_partitions
            and json.dumps(str(item.get("lease_receipt_ref") or ""))
            in serialized_partitions
            and json.dumps(str(item.get("result_fragment_ref") or ""))
            in serialized_partitions
            and json.dumps(
                str(item.get("fragment_artifact_manifest_ref") or "")
            )
            in serialized_partitions
            for item in job_read_partitions
        )
    ):
        return False
    serialized_assertions = json.dumps(
        assertion_constraints, ensure_ascii=False, sort_keys=True
    )
    if any(
        json.dumps(str(item.get("assertion_id") or ""))
        not in serialized_assertions
        for item in assertions
        if isinstance(item, Mapping)
    ):
        return False
    if negative:
        expected_failure = str(
            fixture.get("expected_failure") or "EXPECTED_REJECTION"
        )
        fixture_input = fixture.get("input")
        mutation_manifest = (
            fixture_input.get("mutation_manifest")
            if isinstance(fixture_input, Mapping)
            else None
        )
        bindings = fixture.get("oracle_bindings")
        mutation_results = properties.get("mutation_variant_results")
        mutation_constraints = (
            mutation_results.get("allOf")
            if isinstance(mutation_results, Mapping)
            else None
        )
        serialized_mutations = json.dumps(
            mutation_constraints, ensure_ascii=False, sort_keys=True
        )
        return bool(
            {
                "observed_failure_code",
                "expected_failure_observed",
                "artifact_manifest_sha256",
                "source_job_manifest_sha256",
                "mutation_manifest_sha256",
                "mutation_variant_results",
                "side_effect_receipt_ref",
                "side_effect_receipt_sha256",
                "side_effects_started",
            }.issubset(required)
            and properties.get("observed_failure_code", {}).get("const")
            == expected_failure
            and properties.get("expected_failure_observed", {}).get("const")
            is True
            and properties.get("side_effects_started", {}).get("const") is False
            and isinstance(bindings, Mapping)
            and isinstance(mutation_manifest, list)
            and bool(mutation_manifest)
            and bindings.get("mutation_manifest") == mutation_manifest
            and bindings.get("mutation_manifest_sha256")
            == _json_hash(mutation_manifest)
            and properties.get("mutation_manifest_sha256", {}).get("const")
            == bindings.get("mutation_manifest_sha256")
            and properties.get("artifact_manifest_sha256", {}).get("const")
            == bindings.get("artifact_manifest_sha256")
            and properties.get("source_job_manifest_sha256", {}).get("const")
            == bindings.get("source_job_manifest_sha256")
            and isinstance(mutation_results, Mapping)
            and mutation_results.get("uniqueItems") is True
            and mutation_results.get("minItems") == len(mutation_manifest)
            and mutation_results.get("maxItems") == len(mutation_manifest)
            and isinstance(mutation_constraints, list)
            and len(mutation_constraints) == len(mutation_manifest)
            and all(
                json.dumps(str(item.get("variant_id") or ""))
                in serialized_mutations
                for item in mutation_manifest
                if isinstance(item, Mapping)
            )
        )
    artifact_manifest = bindings.get("artifact_manifest")
    source_manifest = bindings.get("source_job_manifest")
    artifact_checks = properties.get("artifact_checks")
    source_jobs = properties.get("source_job_bindings")
    return bool(
        {
            "artifact_checks",
            "artifact_manifest_sha256",
            "source_job_bindings",
            "source_job_manifest_sha256",
        }.issubset(required)
        and isinstance(artifact_manifest, list)
        and isinstance(source_manifest, list)
        and properties.get("artifact_manifest_sha256", {}).get("const")
        == bindings.get("artifact_manifest_sha256")
        and properties.get("source_job_manifest_sha256", {}).get("const")
        == bindings.get("source_job_manifest_sha256")
        and isinstance(artifact_checks, Mapping)
        and artifact_checks.get("uniqueItems") is True
        and artifact_checks.get("minItems") == len(artifact_manifest)
        and artifact_checks.get("maxItems") == len(artifact_manifest)
        and len(artifact_checks.get("allOf", [])) == len(artifact_manifest)
        and isinstance(source_jobs, Mapping)
        and source_jobs.get("uniqueItems") is True
        and source_jobs.get("minItems") == len(source_manifest)
        and source_jobs.get("maxItems") == len(source_manifest)
        and len(source_jobs.get("allOf", [])) == len(source_manifest)
    )


def _strict_case_aggregation_receipt_schema(
    schema: Any,
    *,
    case_id: str,
    case_kind: str,
    fragment_manifest_ref: str,
    fragment_refs: Sequence[str],
    result_ref: str,
) -> bool:
    if not isinstance(schema, Mapping):
        return False
    properties = schema.get("properties")
    if not isinstance(properties, Mapping):
        return False
    expected_bindings = [
        {
            "ref_pointer": "/fragment_manifest_ref",
            "sha256_pointer": "/fragment_manifest_sha256",
            "pairing": "SINGLE",
        },
        {
            "ref_pointer": "/fragment_refs/*",
            "sha256_pointer": "/fragment_sha256s/*",
            "pairing": "SAME_INDEX_EXACT_CARDINALITY",
        },
        {
            "ref_pointer": "/aggregation_command_receipt_ref",
            "sha256_pointer": "/aggregation_command_receipt_sha256",
            "pairing": "SINGLE",
        },
    ]
    expected_evaluator = {
        "evaluator_id": "CASE_AGGREGATION_REF_SHA256_LINEAGE_V1",
        "implementation_entrypoint": (
            "external_lab.oracle:verify_ref_sha256_bindings_v1"
        ),
        "algorithm_version": "1.0",
        "hash_algorithm": "SHA-256",
        "byte_mode": "EXACT_REFERENCED_BYTES_NO_REENCODING",
        "unknown_or_unresolved_ref_disposition": "FAIL_CLOSED",
        "failure_code": "CASE_AGGREGATION_BYTE_LINEAGE_MISMATCH",
    }
    return bool(
        schema.get("type") == "object"
        and schema.get("additionalProperties") is False
        and properties.get("case_id", {}).get("const") == case_id
        and properties.get("case_kind", {}).get("const") == case_kind
        and properties.get("fragment_manifest_ref", {}).get("const")
        == fragment_manifest_ref
        and properties.get("fragment_refs", {}).get("const")
        == list(fragment_refs)
        and properties.get("fragment_sha256s", {}).get("minItems")
        == len(fragment_refs)
        and properties.get("fragment_sha256s", {}).get("maxItems")
        == len(fragment_refs)
        and properties.get("result_ref", {}).get("const") == result_ref
        and schema.get("x-ref-sha256-bindings") == expected_bindings
        and schema.get("x-byte-lineage-evaluator") == expected_evaluator
        and schema.get("x-invariants")
        == [
            "FRAGMENT_REFS_AND_SHA256S_HAVE_EQUAL_CARDINALITY",
            "EVERY_FRAGMENT_SHA256_MATCHES_REFERENCED_BYTES",
            "FRAGMENT_MANIFEST_SHA256_MATCHES_REFERENCED_BYTES",
            "AGGREGATION_COMMAND_RECEIPT_SHA256_MATCHES_REFERENCED_BYTES",
        ]
    )


def _concrete_acceptance_fixture(
    fixture: Any,
    artifact_index: Mapping[str, Any],
    repository_pins: list[dict[str, str]],
) -> bool:
    if not isinstance(fixture, Mapping):
        return False
    payload = fixture.get("input")
    assertions = fixture.get("assertions")
    oracle_bindings = fixture.get("oracle_bindings")
    if (
        not isinstance(payload, Mapping)
        or not isinstance(assertions, list)
        or not isinstance(oracle_bindings, Mapping)
    ):
        return False
    declared_inputs = payload.get("declared_inputs")
    expectations = payload.get("artifact_expectations")
    jobs = payload.get("fixture_jobs")
    required_artifact_kinds = payload.get("required_artifact_kinds")
    if (
        not isinstance(declared_inputs, list)
        or not declared_inputs
        or not isinstance(expectations, list)
        or (bool(artifact_index) and not expectations)
        or not isinstance(jobs, list)
        or not isinstance(required_artifact_kinds, list)
        or payload.get("one_skill_per_job") is not True
    ):
        return False
    assertion_manifest = [
        {
            "assertion_id": str(item.get("assertion_id") or ""),
            "operator": str(item.get("operator") or ""),
            "expected": item.get("expected"),
        }
        for item in assertions
        if isinstance(item, Mapping)
    ]
    if (
        len(assertion_manifest) != len(assertions)
        or oracle_bindings.get("evaluator_id") != "EXACT_CASE_SET_ORACLE_V1"
        or oracle_bindings.get("evaluator_registry_ref")
        != ORACLE_EVALUATOR_REGISTRY_REF
        or oracle_bindings.get("set_equality_required") is not True
        or oracle_bindings.get("assertion_manifest") != assertion_manifest
        or oracle_bindings.get("assertion_manifest_sha256")
        != _json_hash(assertion_manifest)
        or oracle_bindings.get("artifact_manifest") != expectations
        or oracle_bindings.get("artifact_manifest_sha256")
        != _json_hash(expectations)
    ):
        return False
    seen_expectations: set[str] = set()
    observed_artifact_kinds: set[str] = set()
    for expectation in expectations:
        if not isinstance(expectation, Mapping):
            return False
        artifact_id = expectation.get("artifact_id")
        artifact = artifact_index.get(str(artifact_id))
        if (
            not isinstance(artifact, Mapping)
            or expectation.get("artifact_ref") != artifact.get("artifact_ref")
            or expectation.get("artifact_kind") != artifact.get("artifact_kind")
            or expectation.get("schema_sha256")
            != _json_hash(artifact.get("schema"))
            or expectation.get("job_id") != artifact.get("job_id")
            or expectation.get("source_id") != artifact.get("source_id")
            or str(artifact_id) in seen_expectations
        ):
            return False
        seen_expectations.add(str(artifact_id))
        observed_artifact_kinds.add(str(expectation.get("artifact_kind") or ""))
    if not set(required_artifact_kinds).issubset(observed_artifact_kinds):
        return False
    if payload.get("evidence_closure_policy") == (
        "ALL_CASE_BOUND_ARTIFACT_KINDS_REQUIRED"
    ) and set(required_artifact_kinds) != observed_artifact_kinds:
        return False
    if payload.get("evidence_closure_policy") == (
        "ALL_DECLARED_TIMING_THRESHOLDS_INCLUDE_TERMINAL_MEDIA_ACCEPTANCE"
    ) and "MEDIA_ACCEPTANCE_RECEIPT" not in observed_artifact_kinds:
        return False
    expected_jobs = {
        (
            item["job_id"],
            item["source_id"],
            item["repository_url"],
            item["commit_sha"],
        )
        for item in repository_pins
    }
    actual_jobs = {
        (
            str(item.get("job_id")),
            str(item.get("source_id")),
            str(item.get("repository_url")),
            str(item.get("commit_sha")),
        )
        for item in jobs
        if isinstance(item, Mapping)
        and item.get("input_skill_count") == 1
        and item.get("expected_output_count") == 1
        and re.fullmatch(r"[0-9a-f]{40}", str(item.get("commit_sha") or ""))
        and re.fullmatch(r"[0-9a-f]{40}", str(item.get("git_tree_oid") or ""))
        and re.fullmatch(r"[0-9a-f]{64}", str(item.get("tree_sha256") or ""))
        and all(
            isinstance(item.get(field), str) and bool(item.get(field))
            for field in (
                "expected_function",
                "expected_scenario",
                "expected_effect",
                "demo_contract_ref",
            )
        )
    }
    source_job_manifest = [
        {
            field: item[field]
            for field in ("job_id", "source_id", "repository_url", "commit_sha")
        }
        for item in jobs
        if isinstance(item, Mapping)
    ]
    if (
        actual_jobs != expected_jobs
        or len(actual_jobs) != len(jobs)
        or oracle_bindings.get("source_job_manifest") != source_job_manifest
        or oracle_bindings.get("source_job_manifest_sha256")
        != _json_hash(source_job_manifest)
    ):
        return False
    return any(
        isinstance(assertion, Mapping)
        and assertion.get("operator")
        == "ALL_ARTIFACTS_SCHEMA_HASH_AND_ORACLE_PASS"
        and assertion.get("expected") is True
        for assertion in assertions
    )


def _nonexecutable_negative_fixture_payload_ids(document: Any) -> set[int]:
    if not isinstance(document, Mapping):
        return set()
    cases = document.get("cases")
    if not isinstance(cases, list):
        return set()
    return {
        id(case["input_fixture"])
        for case in cases
        if _is_nonexecutable_negative_fixture(case)
    }


def _check_nonexecutable_negative_fixture_schema(
    root: Path,
) -> list[dict[str, Any]]:
    findings: list[dict[str, Any]] = []
    path = root / "validation/NEGATIVE_CASES.json"
    if not path.is_file():
        return findings
    document = _read_json(path, findings)
    if not isinstance(document, Mapping):
        return findings
    cases = document.get("cases")
    if not isinstance(cases, list):
        return [
            _finding(
                "NONEXECUTABLE_NEGATIVE_FIXTURE_SCHEMA_INVALID",
                "validation/NEGATIVE_CASES.json.cases must be an array",
            )
        ]
    seen: set[str] = set()
    artifact_manifest_path = (
        root / "canonical_sources/ARTIFACT_OBLIGATION_MANIFEST.json"
    )
    artifact_manifest = (
        _read_json(artifact_manifest_path, findings)
        if artifact_manifest_path.is_file()
        else {}
    )
    artifact_index = (
        artifact_manifest.get("artifact_index", {})
        if isinstance(artifact_manifest, Mapping)
        else {}
    )
    artifacts_declared = bool(artifact_index)
    for index, case in enumerate(cases):
        if not isinstance(case, Mapping) or "fixture_kind" not in case:
            continue
        case_id = case.get("case_id")
        if (
            not _is_nonexecutable_negative_fixture(case)
            or not _concrete_negative_input(
                case.get("input_fixture"),
                case.get("expected_failure"),
                artifacts_declared=artifacts_declared,
                artifact_index=artifact_index,
            )
            or str(case_id) in seen
        ):
            findings.append(
                _finding(
                    "NONEXECUTABLE_NEGATIVE_FIXTURE_SCHEMA_INVALID",
                    f"validation/NEGATIVE_CASES.json.cases[{index}]",
                )
            )
        if isinstance(case_id, str):
            seen.add(case_id)
    return findings


def _public_entrypoint_pattern_is_complete(pattern: Any) -> bool:
    if not isinstance(pattern, str):
        return False
    try:
        return all(re.fullmatch(pattern, path) is not None for path in (
            "SKILL.md", "skills/example/SKILL.md", "skills/.system/example/SKILL.md",
        )) and all(re.fullmatch(pattern, path) is None for path in (
            "/SKILL.md", "../SKILL.md", "skills/../SKILL.md", "README.md",
        ))
    except re.error:
        return False


def _public_skill_job_interface_is_valid(
    interface: Any, frozen_ir: Mapping[str, Any]
) -> bool:
    """Independently validate the public URL boundary and resolved identity."""

    if not isinstance(interface, Mapping):
        return False
    request_schema = interface.get("job_request_schema")
    specialization = interface.get("dynamic_specialization_contract")
    vector = interface.get("metamorphic_acceptance_vector")
    frozen_fixtures = interface.get("frozen_certification_fixtures")
    if not all(
        isinstance(value, Mapping)
        for value in (request_schema, specialization, vector)
    ) or not isinstance(frozen_fixtures, list):
        return False
    # A JSON pointer locates the embedded schema, but cannot be its canonical
    # $id in 2020-12. Do not accept the old non-empty fragment identifier.
    if (request_schema.get("$id") != "urn:harness-foundry:public-skill-job-request:v1"
            or request_schema.get("$schema") != "https://json-schema.org/draft/2020-12/schema"):
        return False
    schema_properties = request_schema.get("properties")
    input_value = vector.get("input")
    resolution = vector.get("resolution_contract")
    expected = vector.get("expected")
    if not all(
        isinstance(value, Mapping)
        for value in (schema_properties, input_value, resolution, expected)
    ):
        return False
    resolution_schema = resolution.get("resolution_receipt_schema")
    if not isinstance(resolution_schema, Mapping):
        return False
    resolution_properties = resolution_schema.get("properties")
    resolution_required = set(resolution_schema.get("required", []))
    if not isinstance(resolution_properties, Mapping):
        return False
    skill_url_schema = schema_properties.get("skill_url")
    skill_url = str(input_value.get("skill_url") or "")
    normalized_url = skill_url.removesuffix(".git").rstrip("/")
    frozen_urls = {
        str(item.get("repository_url") or "")
        for item in frozen_fixtures
        if isinstance(item, Mapping)
    }
    identity_fields = [
        "request_id",
        "normalized_skill_url",
        "skill_entrypoint_ref",
        "resolved_commit_sha",
        "resolved_git_tree_oid",
        "resolved_tree_sha256",
        "resolved_skill_entrypoint_sha256",
    ]
    expected_resolution_required = {
        "request_id",
        "skill_url",
        "requested_revision",
        "skill_entrypoint_ref",
        "normalized_skill_url",
        "resolved_commit_sha",
        "resolved_git_tree_oid",
        "resolved_tree_ref",
        "resolved_tree_sha256",
        "resolved_skill_entrypoint_ref",
        "resolved_skill_entrypoint_sha256",
        "resolution_command_receipt_ref",
        "resolution_command_receipt_sha256",
        "repository_readable",
        "status",
    }
    expected_resolution_bindings = [
        {
            "ref_pointer": "/resolved_tree_ref",
            "sha256_pointer": "/resolved_tree_sha256",
        },
        {
            "ref_pointer": "/resolved_skill_entrypoint_ref",
            "sha256_pointer": "/resolved_skill_entrypoint_sha256",
        },
        {
            "ref_pointer": "/resolution_command_receipt_ref",
            "sha256_pointer": "/resolution_command_receipt_sha256",
        },
    ]
    catalog = frozen_ir.get("target", {}).get("artifact_schema_catalog", {})
    expected_templates = sorted(
        [
            {
                "atom_id": str(atom_id),
                "artifact_kind": str(profile.get("artifact_kind") or ""),
            }
            for atom_id, profile in (
                catalog.items() if isinstance(catalog, Mapping) else []
            )
            if isinstance(profile, Mapping)
            and isinstance(profile.get("schema"), Mapping)
        ],
        key=lambda item: (item["atom_id"], item["artifact_kind"]),
    )
    return bool(
        interface.get("schema_version") == "1.0"
        and interface.get("interface_id")
        == "PUBLIC-SKILL-URL-TO-VIDEO-JOB-V1"
        and interface.get("status") == "DECLARE_ONLY_NOT_RUN"
        and interface.get("execution_started") is False
        and request_schema.get("type") == "object"
        and request_schema.get("additionalProperties") is False
        and isinstance(skill_url_schema, Mapping)
        and "const" not in skill_url_schema
        and "enum" not in skill_url_schema
        and isinstance(skill_url_schema.get("pattern"), str)
        and re.fullmatch(skill_url_schema["pattern"], skill_url) is not None
        and skill_url == PUBLIC_SKILL_METAMORPHIC_REPOSITORY_URL
        and input_value.get("skill_entrypoint_ref")
        == PUBLIC_SKILL_METAMORPHIC_ENTRYPOINT_REF
        and request_schema.get("required", []).count("skill_entrypoint_ref")
        == 1
        and _public_entrypoint_pattern_is_complete(
            schema_properties.get("skill_entrypoint_ref", {}).get("pattern"))
        and frozen_fixtures == _independent_repository_job_bindings(frozen_ir)
        and skill_url not in frozen_urls
        and vector.get("case_id") == PUBLIC_SKILL_METAMORPHIC_CASE_ID
        and "resolved_source" not in vector
        and resolution.get("status")
        == "RUNTIME_RESOLUTION_REQUIRED_NOT_RUN"
        and resolution.get("resolution_receipt_ref")
        == PUBLIC_SKILL_METAMORPHIC_RESOLUTION_RECEIPT_REF
        and resolution.get("network_access_mode")
        == "READ_ONLY_HTTPS_FOR_DECLARED_PUBLIC_SKILL_URL"
        and resolution.get("allowed_hosts") == ["github.com"]
        and resolution.get("simulated_resolution_values_forbidden") is True
        and resolution_schema.get("type") == "object"
        and resolution_schema.get("additionalProperties") is False
        and expected_resolution_required.issubset(resolution_required)
        and resolution_properties.get("request_id", {}).get("const")
        == input_value.get("request_id")
        and resolution_properties.get("skill_url", {}).get("const")
        == skill_url
        and resolution_properties.get("requested_revision", {}).get("const")
        == input_value.get("requested_revision")
        and resolution_properties.get("skill_entrypoint_ref", {}).get("const")
        == input_value.get("skill_entrypoint_ref")
        and resolution_properties.get("normalized_skill_url", {}).get(
            "const"
        )
        == normalized_url
        and resolution_properties.get("resolved_commit_sha", {}).get(
            "pattern"
        )
        == "^[0-9a-f]{40}$"
        and resolution_properties.get("resolved_git_tree_oid", {}).get(
            "pattern"
        )
        == "^[0-9a-f]{40}$"
        and resolution_properties.get("resolved_tree_sha256", {}).get(
            "pattern"
        )
        == "^[0-9a-f]{64}$"
        and resolution_properties.get(
            "resolved_skill_entrypoint_ref", {}
        ).get("const")
        == input_value.get("skill_entrypoint_ref")
        and resolution_properties.get(
            "resolved_skill_entrypoint_sha256", {}
        ).get("pattern")
        == "^[0-9a-f]{64}$"
        and resolution_schema.get("x-ref-sha256-bindings")
        == expected_resolution_bindings
        and specialization.get("job_id_derivation")
        == "SHA256_CANONICAL_RESOLVED_JOB_IDENTITY_PREFIX_16"
        and specialization.get("job_identity_derivation_stage")
        == "AFTER_EXACT_SOURCE_RESOLUTION"
        and specialization.get("job_identity_fields")
        == identity_fields
        and specialization.get(
            "mutable_request_fields_excluded_from_final_identity"
        )
        == ["requested_revision"]
        and specialization.get("source_resolution_entrypoint")
        == "external_lab.sources:resolve_public_skill_source_v1"
        and specialization.get("source_resolution_receipt_required") is True
        and specialization.get(
            "source_resolution_receipt_bytes_must_hash_match"
        )
        is True
        and specialization.get("resolved_tree_bytes_must_hash_match") is True
        and specialization.get("schema_template_bindings")
        == expected_templates
        and specialization.get("template_binding_role")
        == "INPUT_CATALOG_NOT_COMPLETE_OUTPUT_ARTIFACT_SET"
        and specialization.get("job_pipeline_entrypoint")
        == PUBLIC_SKILL_JOB_PIPELINE_ENTRYPOINT
        and specialization.get("artifact_derivation_contract") == {
            "algorithm": "RECOMPILE_FROZEN_CATALOG_WITH_SINGLE_RESOLVED_JOB_V1",
            "input": "HASH_VERIFIED_SOURCE_RESOLUTION_AND_DERIVED_JOB_ID",
            "supplemental_artifacts": {
                "LOCAL_TTS_RECEIPT": ["NARRATION_SCRIPT"],
                "OBJECT_MOTION_IR": ["ASSET_BINDING_RECEIPT"],
            },
            "stage_order": list(RESUMABLE_STAGE_ORDER),
            "dependency_rule": "REUSE_COMPLETE_ARTIFACT_DEPENDENCY_COMPILER_FOR_ONE_JOB",
            "renderer_binding": "PRESERVE_FROZEN_RENDERER_SEPARATE_FROM_DYNAMIC_CONTENT_SOURCE",
            "write_root_rule": "EXECUTION_JOBS_DERIVED_JOB_ID_ONLY",
            "execution_enabled": False,
        }
        and specialization.get("schema_catalog_ref")
        == (
            "harness-resource://candidate/canonical_sources/"
            "FROZEN_REQUIREMENT_IR.json#/target/artifact_schema_catalog"
        )
        and expected.get("job_id_derivation")
        == specialization.get("job_id_derivation")
        and "expected_job_id" not in expected
        and expected.get("expected_job_id_source")
        == "HASH_VERIFIED_RUNTIME_RESOLUTION_RECEIPT_FIELDS"
        and expected.get("input_skill_count") == 1
        and expected.get("output_video_count") == 1
        and expected.get("source_is_frozen_before_analysis") is True
        and expected.get("source_resolution_receipt_required") is True
        and expected.get("skill_entrypoint_identity_required") is True
        and expected.get("video_artifact_descriptor_required") is True
        and expected.get("media_acceptance_artifact_descriptor_required")
        is True
        and expected.get("job_artifact_lease_descriptor_required") is True
        and expected.get("target_skill_execution_enabled") is False
        and vector.get("oracle", {}).get("algorithm_id")
        == "PUBLIC-SKILL-JOB-METAMORPHIC-ORACLE-V2"
        and vector.get("oracle", {}).get("implementation_entrypoint")
        == "external_lab.oracle:evaluate_public_skill_job_v2"
        and vector.get("status") == "PLANNED_NOT_RUN"
        and interface.get("interface_sha256")
        == _hash_without_field(interface, "interface_sha256")
    )


def _independent_repository_job_bindings(
    requirement_ir: Mapping[str, Any],
) -> list[dict[str, str]]:
    """Reconstruct fixed repository jobs without invoking Producer helpers."""

    jobs: list[dict[str, str]] = []
    for source in requirement_ir.get("sources", []):
        if not isinstance(source, Mapping) or not source.get("repository_url"):
            continue
        source_id = str(source.get("source_id") or "")
        safe_source_id = "".join(
            character if character.isalnum() else "-"
            for character in source_id.upper()
        ).strip("-")
        jobs.append(
            {
                "job_id": f"FIXTURE-JOB-{safe_source_id}",
                "source_id": source_id,
                "repository_url": str(source["repository_url"]),
                "revision": str(source.get("revision") or ""),
                "commit_sha": str(source.get("commit_sha") or ""),
                "git_tree_oid": str(source.get("git_tree_oid") or ""),
                "tree_sha256": str(
                    source.get("tree_sha256") or source.get("sha256") or ""
                ),
                "license_spdx": str(source.get("license_spdx") or ""),
            }
        )
    return jobs


def _oracle_registry_is_independently_consistent(
    registry: Any,
    artifact_index: Mapping[str, Any],
) -> bool:
    """Validate registry coverage from emitted artifact contracts, not Producer output."""

    if not isinstance(registry, Mapping):
        return False
    if (
        registry.get("schema_version") != "1.0"
        or registry.get("status") != "DECLARE_ONLY_NOT_IMPLEMENTED_NOT_RUN"
        or registry.get("execution_started") is not False
        or registry.get("registry_sha256")
        != _hash_without_field(registry, "registry_sha256")
    ):
        return False
    evaluators = registry.get("evaluators")
    invariant_matrix = registry.get("invariant_negative_case_matrix")
    schema_matrix = registry.get("schema_native_negative_case_matrix")
    if (
        not isinstance(evaluators, Mapping)
        or not isinstance(invariant_matrix, list)
        or not isinstance(schema_matrix, list)
    ):
        return False
    schemas_by_kind: dict[str, list[Mapping[str, Any]]] = {}
    for artifact in artifact_index.values():
        if not isinstance(artifact, Mapping):
            return False
        artifact_kind = str(artifact.get("artifact_kind") or "")
        schema = artifact.get("schema")
        if not artifact_kind or not isinstance(schema, Mapping):
            return False
        schemas_by_kind.setdefault(artifact_kind, []).append(schema)
    evaluator_kinds = {
        str(evaluator.get("artifact_kind") or "")
        for evaluator in evaluators.values()
        if isinstance(evaluator, Mapping)
    }
    if not set(schemas_by_kind).issubset(evaluator_kinds):
        return False
    expected_pairs: dict[tuple[str, str], tuple[Mapping[str, Any], list[str], str]] = {}
    for evaluator_id, evaluator in evaluators.items():
        if not isinstance(evaluator, Mapping):
            return False
        artifact_kind = str(evaluator.get("artifact_kind") or "")
        contracts = evaluator.get("invariant_contracts")
        if contracts is None:
            if (
                not isinstance(evaluator.get("implementation_entrypoint"), str)
                or not evaluator.get("implementation_entrypoint")
                or not isinstance(evaluator.get("required_inputs"), list)
            ):
                return False
            continue
        if not isinstance(contracts, Mapping):
            return False
        schema_contract_sets = [
            schema.get("x-invariant-contracts", {})
            for schema in schemas_by_kind.get(artifact_kind, [])
        ]
        if schema_contract_sets and any(
            not isinstance(item, Mapping) or item != contracts
            for item in schema_contract_sets
        ):
            return False
        if (
            evaluator.get("declared_invariant_count") != len(contracts)
            or evaluator.get("invariant_contracts_sha256")
            != _json_hash(contracts)
        ):
            return False
        schema_hashes = sorted(
            {
                _json_hash(schema)
                for schema in schemas_by_kind.get(artifact_kind, [])
            }
        )
        for invariant_id, contract in contracts.items():
            expected_pairs[(artifact_kind, str(invariant_id))] = (
                contract,
                schema_hashes,
                str(evaluator_id),
            )
    observed_pairs: set[tuple[str, str]] = set()
    for case in invariant_matrix:
        if not isinstance(case, Mapping):
            return False
        pair = (
            str(case.get("artifact_kind") or ""),
            str(case.get("invariant_id") or ""),
        )
        expected = expected_pairs.get(pair)
        if expected is None or pair in observed_pairs:
            return False
        contract, schema_hashes, evaluator_id = expected
        applicable_schema_hashes = case.get("applicable_schema_sha256s")
        mutation = case.get("mutation", {})
        recipe = mutation.get("derivation_recipe", {})
        selector = contract.get("branch_selector", {})
        if selector.get("mode") == "REQUIRE_DISCRIMINATOR_CONST" and (
            recipe.get("required_base_branch") != selector.get("const")
            or case.get("base_precondition", {}).get("required_branch") != selector.get("const")
        ):
            return False
        if selector.get("mode") == "REQUIRE_DISCRIMINATOR_IN" and recipe.get("required_base_subject_branch") != {
            "discriminator_ref": selector["discriminator_ref"].replace("/*", "/0"),
            "values": selector["values"],
        }:
            return False
        # Independent projection from schema-defined derivations, not from the
        # Producer recipe. Only non-target canonical parents may be rebuilt.
        expected_recomputations = []
        peer_contracts = schemas_by_kind[pair[0]][0].get("x-invariant-contracts", {})
        expected_failure_set, pending = set(), [pair[1]]
        while pending:
            current = pending.pop()
            if current not in expected_failure_set:
                expected_failure_set.add(current)
                pending.extend(MUTATION_FAILURE_DEPENDENCIES.get(current, ()))
                pending.extend(MUTATION_FAILURE_DEPENDENCIES_BY_KIND.get(pair[0], {}).get(current, ()))
        if not expected_failure_set.issubset(peer_contracts):
            return False
        expected_failures = sorted(expected_failure_set)
        if (recipe.get("mutation_class") != ("DEPENDENCY_CLOSURE" if len(expected_failures) > 1 else "INDEPENDENT_INVARIANT")
                or recipe.get("acceptance_predicate") != {
                    "full_artifact_json_schema": "PASS", "required_failed_invariant_ids": [pair[1]],
                    "allowed_failed_invariant_ids": expected_failures, "outside_allowed_failure_set": "PASS"}):
            return False
        for peer in peer_contracts.values():
            source = peer.get("parameters", {}).get("canonical_value_ref")
            target = peer.get("target_ref")
            if (peer.get("algorithm") == "CANONICAL_JSON_VALUE_HASH_V1"
                    and isinstance(source, str) and isinstance(target, str)
                    and str(contract.get("target_ref", "")).startswith(source.rstrip("/") + "/")
                    and target != contract.get("target_ref")):
                expected_recomputations.append({"algorithm": "CANONICAL_JSON_VALUE_HASH_V1",
                    "source_ref": source, "target_ref": target})
        if contract.get("algorithm") == "RENDER_INPUT_ASSET_SET_EQUALITY_V1" and (
            recipe.get("strategy") != "MUTATE_REFERENCED_ASSET_DIGEST_AND_REBIND_MANIFEST"
            or recipe.get("referenced_document_mutation") != {
                "ref_pointer": "/render_input_manifest_ref",
                "sha256_pointer": "/render_input_manifest_sha256",
                "value_pointer": "/assets/0/asset_sha256",
                "replacement_rule": "DIFFERENT_VALID_SHA256",
            }
        ):
            return False
        if contract.get("algorithm") == "REFERENCED_JSON_FIELD_EQUALITY_V1" and (
            recipe.get("strategy") != "MUTATE_REFERENCED_FFPROBE_INPUT_AND_REBIND_RECEIPT"
            or recipe.get("target_ref_role") != "RELATION_ANCHOR_NOT_MUTATED"
            or recipe.get("preserved_top_level_refs") != ["/video_sha256"]
            or recipe.get("referenced_document_mutation") != {
                "ref_pointer": "/ffprobe_receipt_ref",
                "sha256_pointer": "/ffprobe_receipt_sha256",
                "value_pointer": "/input_sha256",
                "replacement_rule": "DIFFERENT_VALID_SHA256",
            }
        ):
            return False
        if (recipe.get("derived_field_recomputations") != sorted(expected_recomputations, key=lambda item: item["target_ref"])
                or recipe.get("result_classification") != {
                    "success": "SCHEMA_PASS_AND_DECLARED_FAILURE_SET",
                    "timeout_or_runner_error": "INCONCLUSIVE",
                    "schema_rejection": "NOT_INVARIANT_EVIDENCE",
                    "missing_counterexample": "INCONCLUSIVE_NOT_PASS",
                    "recomputation_order": "AFTER_MUTATION_BEFORE_SCHEMA_AND_ALL_ORACLES",
                }
                or mutation.get("post_mutation_required_failed_invariant_ids") != [pair[1]]
                or mutation.get("post_mutation_allowed_failed_invariant_ids") != expected_failures
                or mutation.get("outside_allowed_failure_set_expected") != "PASS"):
            return False
        if (
            case.get("evaluator_id") != evaluator_id
            or case.get("invariant_contract") != contract
            or case.get("invariant_contract_sha256") != _json_hash(contract)
            or not isinstance(applicable_schema_hashes, list)
            or not applicable_schema_hashes
            or not all(
                isinstance(value, str) and SHA256_RE.fullmatch(value)
                for value in applicable_schema_hashes
            )
            or (schema_hashes and applicable_schema_hashes != schema_hashes)
            or case.get("apply_to_every_schema_instance") is not True
        ):
            return False
        observed_pairs.add(pair)
    return observed_pairs == set(expected_pairs)


def _strict_public_metamorphic_result_schema(
    schema: Any, vector: Mapping[str, Any]
) -> bool:
    if not isinstance(schema, Mapping):
        return False
    properties = schema.get("properties")
    if not isinstance(properties, Mapping):
        return False
    required = {
        "case_id",
        "case_kind",
        "request_sha256",
        "request_id",
        "normalized_skill_url",
        "requested_revision",
        "skill_entrypoint_ref",
        "resolution_receipt_ref",
        "resolution_receipt_sha256",
        "resolved_commit_sha",
        "resolved_git_tree_oid",
        "resolved_tree_ref",
        "resolved_tree_sha256",
        "resolved_skill_entrypoint_sha256",
        "derived_job_id",
        "output_video_count",
        "source_is_frozen_before_analysis",
        "target_skill_execution_enabled",
        "command_receipt_ref",
        "command_receipt_sha256",
        "side_effects_started",
        "artifacts",
        "oracle_decision",
        "status",
    }
    resolution = vector.get("resolution_contract")
    input_value = vector.get("input")
    if not isinstance(resolution, Mapping) or not isinstance(
        input_value, Mapping
    ):
        return False
    ref_bindings = [
        {
            "ref_pointer": "/resolution_receipt_ref",
            "sha256_pointer": "/resolution_receipt_sha256",
        },
        {
            "ref_pointer": "/resolved_tree_ref",
            "sha256_pointer": "/resolved_tree_sha256",
        },
        {
            "ref_pointer": "/skill_entrypoint_ref",
            "sha256_pointer": "/resolved_skill_entrypoint_sha256",
        },
        {
            "ref_pointer": "/command_receipt_ref",
            "sha256_pointer": "/command_receipt_sha256",
        },
    ]
    identity_contract = {
        "algorithm": "SHA256_CANONICAL_RESOLVED_JOB_IDENTITY_PREFIX_16",
        "canonicalization": (
            "UTF8_JSON_SORT_KEYS_COMPACT_SEPARATORS_PRESERVE_ARRAY_ORDER_V1"
        ),
        "identity_field_pointers": [
            "/request_id",
            "/normalized_skill_url",
            "/skill_entrypoint_ref",
            "/resolved_commit_sha",
            "/resolved_git_tree_oid",
            "/resolved_tree_sha256",
            "/resolved_skill_entrypoint_sha256",
        ],
        "output_pointer": "/derived_job_id",
        "output_format": "JOB-UPPERCASE-FIRST-16-SHA256-HEX",
        "resolution_receipt_field_equality_required": True,
    }
    return bool(
        schema.get("type") == "object"
        and schema.get("additionalProperties") is False
        and required.issubset(set(schema.get("required", [])))
        and properties.get("case_id", {}).get("const")
        == vector.get("case_id")
        and properties.get("case_kind", {}).get("const") == "METAMORPHIC"
        and properties.get("request_sha256", {}).get("const")
        == _json_hash(input_value)
        and properties.get("request_id", {}).get("const")
        == input_value.get("request_id")
        and properties.get("normalized_skill_url", {}).get("const")
        == str(input_value.get("skill_url") or "")
        .removesuffix(".git")
        .rstrip("/")
        and properties.get("requested_revision", {}).get("const")
        == input_value.get("requested_revision")
        and properties.get("skill_entrypoint_ref", {}).get("const")
        == input_value.get("skill_entrypoint_ref")
        and properties.get("resolution_receipt_ref", {}).get("const")
        == resolution.get("resolution_receipt_ref")
        and properties.get("resolution_receipt_sha256", {}).get("pattern")
        == "^[0-9a-f]{64}$"
        and properties.get("resolved_commit_sha", {}).get("pattern")
        == "^[0-9a-f]{40}$"
        and properties.get("resolved_git_tree_oid", {}).get("pattern")
        == "^[0-9a-f]{40}$"
        and properties.get("resolved_tree_sha256", {}).get("pattern")
        == "^[0-9a-f]{64}$"
        and properties.get("resolved_skill_entrypoint_sha256", {}).get(
            "pattern"
        )
        == "^[0-9a-f]{64}$"
        and properties.get("derived_job_id", {}).get("pattern")
        == "^JOB-[0-9A-F]{16}$"
        and properties.get("output_video_count", {}).get("const") == 1
        and properties.get("source_is_frozen_before_analysis", {}).get(
            "const"
        )
        is True
        and properties.get("target_skill_execution_enabled", {}).get("const")
        is False
        and properties.get("side_effects_started", {}).get("type")
        == "boolean"
        and properties.get("artifacts")
        == {
            "type": "object",
            "additionalProperties": False,
            "required": [
                "video",
                "media_acceptance_receipt",
                "job_artifact_lease",
            ],
            "properties": {
                "video": JOB_ARTIFACT_DESCRIPTOR_SCHEMA,
                "media_acceptance_receipt": JOB_ARTIFACT_DESCRIPTOR_SCHEMA,
                "job_artifact_lease": JOB_ARTIFACT_DESCRIPTOR_SCHEMA,
            },
        }
        and schema.get("x-ref-sha256-bindings") == ref_bindings
        and schema.get("x-job-artifact-binding") == {
            "job_id_pointer": "/derived_job_id",
            "descriptor_names": ["video", "media_acceptance_receipt", "job_artifact_lease"],
            "descriptor_job_field": "producer_job_id",
            "verify_exact_bytes_and_size": True,
            "media_video_fields": ["video_ref", "video_sha256"],
            "receipt_job_field": "job_id",
            "lease_scope_field": "allowed_write_roots",
            "implementation_entrypoint": "external_lab.oracle:verify_job_artifact_descriptors_v1",
        }
        and schema.get("x-job-identity-derivation") == identity_contract
        and schema.get("x-invariants")
        == [
            "RESOLUTION_RECEIPT_SHA256_MATCHES_REFERENCED_BYTES",
            "RESOLVED_TREE_SHA256_MATCHES_REFERENCED_BYTES",
            "RESULT_RESOLVED_FIELDS_EQUAL_HASH_VERIFIED_RESOLUTION_RECEIPT",
            "RESOLVED_SKILL_ENTRYPOINT_SHA256_MATCHES_TREE_MEMBER_BYTES",
            "DERIVED_JOB_ID_EQUALS_CANONICAL_RESOLVED_IDENTITY_HASH",
            "PASS_RESULT_HAS_VIDEO_MEDIA_ACCEPTANCE_AND_JOB_LEASE_DESCRIPTORS",
        ]
        and schema.get("allOf")
        == [
            {
                "if": {
                    "properties": {"status": {"const": "PASS"}},
                    "required": ["status"],
                },
                "then": {
                    "properties": {
                        "oracle_decision": {"const": "PASS"},
                        "side_effects_started": {"const": True},
                    }
                },
            }
        ]
    )


def _check_executable_acceptance_and_oracles(
    root: Path,
) -> list[dict[str, Any]]:
    """Reject prose-only cases that cannot drive a later independent oracle."""

    findings: list[dict[str, Any]] = []
    manifest_path = root / "validation/CASE_EXECUTION_MANIFEST.json"
    manifest = _read_json(manifest_path, findings)
    result_schema_path = root / "validation/schemas/CASE_RESULT.schema.json"
    result_schema = _read_json(result_schema_path, findings)
    for ref, definition in ((RESULT_SCHEMA_REF, REGISTRY_CASE_RESULT_SCHEMA),
                            (RECEIPT_SCHEMA_REF, REGISTRY_CASE_EXECUTION_RECEIPT_SCHEMA)):
        relative = ref.removeprefix("harness-resource://candidate/")
        if _read_json(root / relative, findings) != definition:
            findings.append(_finding("REGISTRY_EXECUTION_EVIDENCE_SCHEMA_INVALID", relative))
    registry_path = root / "validation/ORACLE_EVALUATOR_REGISTRY.json"
    registry = _read_json(registry_path, findings)
    artifact_manifest_path = (
        root / "canonical_sources/ARTIFACT_OBLIGATION_MANIFEST.json"
    )
    artifact_manifest = (
        _read_json(artifact_manifest_path, findings)
        if artifact_manifest_path.is_file()
        else {}
    )
    source_manifest = _read_json(
        root / "canonical_sources/SOURCE_MANIFEST.json", findings
    )
    frozen_ir = _read_json(
        root / "canonical_sources/FROZEN_REQUIREMENT_IR.json", findings
    )
    public_job_interface_path = (
        root / "validation/PUBLIC_SKILL_JOB_INTERFACE.json"
    )
    public_job_interface = (
        _read_json(public_job_interface_path, findings)
        if public_job_interface_path.is_file()
        else None
    )
    if (
        not isinstance(frozen_ir, Mapping)
        or not _public_skill_job_interface_is_valid(
            public_job_interface, frozen_ir
        )
    ):
        findings.append(
            _finding(
                "PUBLIC_SKILL_JOB_INTERFACE_INVALID",
                "validation/PUBLIC_SKILL_JOB_INTERFACE.json",
            )
        )
        findings.append(
            _finding(
                "PUBLIC_SKILL_JOB_IDENTITY_NOT_IMMUTABLY_RESOLVED",
                "validation/PUBLIC_SKILL_JOB_INTERFACE.json",
            )
        )
    artifact_index = (
        artifact_manifest.get("artifact_index", {})
        if isinstance(artifact_manifest, Mapping)
        else {}
    )
    registry_is_consistent = _oracle_registry_is_independently_consistent(
        registry,
        artifact_index if isinstance(artifact_index, Mapping) else {},
    )
    repository_pins = _independent_repository_job_bindings(
        source_manifest if isinstance(source_manifest, Mapping) else {}
    )
    commands = {
        str(item.get("command_id")): item
        for item in (
            manifest.get("commands", []) if isinstance(manifest, Mapping) else []
        )
        if isinstance(item, Mapping) and item.get("command_id")
    }
    external_command_manifest = _read_json(
        root / "project_start_packages/external_lab/COMMAND_MANIFEST.json",
        findings,
    )
    certification_commands = _read_json(
        root
        / "project_start_packages/external_lab/commands/"
        "LAB-CERTIFICATION.commands.json",
        findings,
    )
    registered_commands = {
        str(item.get("command_id")): item
        for item in (
            external_command_manifest.get("commands", [])
            if isinstance(external_command_manifest, Mapping)
            else []
        )
        if isinstance(item, Mapping) and item.get("command_id")
    }
    owned_certification_commands = {
        str(item.get("command_id")): item
        for item in (
            certification_commands.get("commands", [])
            if isinstance(certification_commands, Mapping)
            else []
        )
        if isinstance(item, Mapping) and item.get("command_id")
    }
    expected_case_command_ids = {
        "LAB-RUN-ACCEPTANCE-CASE",
        "LAB-RUN-NEGATIVE-CASE",
        "LAB-RUN-REGISTRY-CASE",
        "LAB-RUN-CASE-PARTITION",
        "LAB-AGGREGATE-CASE-PARTITIONS",
        "LAB-RUN-METAMORPHIC-CASE",
        "LAB-EVALUATE-CASE-ORACLE",
    }
    expected_registry_invocations = []
    registry_read_plans = _independent_registry_read_plans(artifact_index)
    seen_registry_result_refs: set[str] = set()
    for matrix_field, case_kind in (
        ("invariant_negative_case_matrix", "INVARIANT"),
        ("schema_native_negative_case_matrix", "SCHEMA_NATIVE"),
    ):
        for case_index, case in enumerate(
            registry.get(matrix_field, [])
            if isinstance(registry, Mapping)
            else []
        ):
            if not isinstance(case, Mapping) or not case.get("case_id"):
                continue
            for schema_sha256 in case.get("applicable_schema_sha256s", []):
                fixture_ref = (
                    f"{ORACLE_EVALUATOR_REGISTRY_REF}#/"
                    f"{matrix_field}/{case_index}"
                )
                result_ref = registry_case_result_ref(
                    case_kind,
                    str(case["case_id"]),
                    str(schema_sha256),
                )
                if result_ref in seen_registry_result_refs:
                    continue
                seen_registry_result_refs.add(result_ref)
                read_plan_ref = (f"{LOGICAL_CANDIDATE_ROOT}/validation/CASE_EXECUTION_MANIFEST.json"
                                 f"#/registry_case_invocations/{len(expected_registry_invocations)}/read_plan")
                expected_registry_invocations.append(
                    {
                        "case_id": str(case["case_id"]),
                        "case_kind": case_kind,
                        "schema_sha256": str(schema_sha256),
                        "owner_workpack_id": CASE_EVIDENCE_WRITER_WORKPACK_ID,
                        "executor_command_id": "LAB-RUN-REGISTRY-CASE",
                        "fixture_ref": fixture_ref,
                        "result_ref": result_ref,
                        "baseline_root_ref": result_ref.removesuffix(".result.json") + "/inputs",
                        "result_schema_ref": RESULT_SCHEMA_REF,
                        "command_receipt_ref": result_ref.removesuffix(".result.json") + ".command.json",
                        "command_receipt_schema_ref": RECEIPT_SCHEMA_REF,
                        "read_plan_ref": read_plan_ref,
                        "read_plan": registry_read_plans.get((str(case["artifact_kind"]), str(schema_sha256))),
                        "executor_argv": [
                            f"{LOGICAL_EXECUTION_ROOT}/project_start_packages/"
                            "external_lab/.venv/bin/python",
                            "-m",
                            "external_lab",
                            "run-registry-case",
                            "--fixture-ref",
                            fixture_ref,
                            "--result-ref",
                            result_ref,
                            "--read-plan-ref",
                            read_plan_ref,
                        ],
                    }
                )
    if isinstance(manifest, Mapping):
        emitted_invocations = manifest.get("registry_case_invocations", [])
        if (len(emitted_invocations) != len(expected_registry_invocations)
                or any(not isinstance(actual, Mapping) or any(actual.get(field) != expected.get(field)
                    for field in ("read_plan", "read_plan_ref", "baseline_root_ref", "executor_argv",
                                  "result_schema_ref", "command_receipt_ref", "command_receipt_schema_ref"))
                    for actual, expected in zip(emitted_invocations, expected_registry_invocations))):
            findings.append(_finding("REGISTRY_CASE_READ_PLAN_INCOMPLETE",
                                     "validation/CASE_EXECUTION_MANIFEST.json"))
    public_vector = (
        public_job_interface.get("metamorphic_acceptance_vector", {})
        if isinstance(public_job_interface, Mapping)
        else {}
    )
    public_case_id = str(public_vector.get("case_id") or "")
    public_result_ref = case_result_ref("METAMORPHIC", public_case_id)
    public_schema_relative = (
        "validation/schemas/cases/"
        f"metamorphic-{_slug(public_case_id).lower()}.result.schema.json"
    )
    public_schema_path = root / public_schema_relative
    public_schema_ref = f"{LOGICAL_CANDIDATE_ROOT}/{public_schema_relative}"
    public_schema = (
        _read_json(public_schema_path, findings)
        if public_schema_path.is_file()
        else None
    )
    public_fixture_ref = (
        f"{PUBLIC_SKILL_JOB_INTERFACE_REF}#/metamorphic_acceptance_vector"
    )
    expected_metamorphic_invocations = [
        {
            "case_id": public_case_id,
            "case_kind": "METAMORPHIC",
            "owner_workpack_id": CASE_EVIDENCE_WRITER_WORKPACK_ID,
            "executor_command_id": "LAB-RUN-METAMORPHIC-CASE",
            "source_resolution_entrypoint": (
                PUBLIC_SKILL_SOURCE_RESOLUTION_ENTRYPOINT
            ),
            "fixture_ref": public_fixture_ref,
            "fixture_fragment_sha256": _json_hash(public_vector),
            "result_ref": public_result_ref,
            "result_schema_ref": public_schema_ref,
            "result_schema_sha256": (
                _file_hash(public_schema_path)
                if public_schema_path.is_file()
                else None
            ),
            "executor_argv": [
                f"{LOGICAL_EXECUTION_ROOT}/project_start_packages/"
                "external_lab/.venv/bin/python",
                "-m",
                "external_lab",
                "run-metamorphic-case",
                "--fixture-ref",
                public_fixture_ref,
                "--resolution-receipt-ref",
                public_vector.get("resolution_contract", {}).get(
                    "resolution_receipt_ref"
                ),
                "--result-ref",
                public_result_ref,
            ],
            "oracle_contract": {
                **deepcopy(
                    public_vector.get("oracle", {})
                    if isinstance(public_vector, Mapping)
                    else {}
                ),
                "executor_command_id": "LAB-EVALUATE-CASE-ORACLE",
                "result_schema_ref": public_schema_ref,
                "result_schema_sha256": (
                    _file_hash(public_schema_path)
                    if public_schema_path.is_file()
                    else None
                ),
            },
        }
    ]
    metamorphic_closure_valid = bool(
        public_case_id == PUBLIC_SKILL_METAMORPHIC_CASE_ID
        and manifest.get("metamorphic_case_invocations")
        == expected_metamorphic_invocations
        and _strict_public_metamorphic_result_schema(
            public_schema, public_vector
        )
    ) if isinstance(manifest, Mapping) else False
    if not metamorphic_closure_valid:
        findings.append(
            _finding(
                "PUBLIC_SKILL_JOB_CASE_CLOSURE_INCOMPLETE",
                "validation/CASE_EXECUTION_MANIFEST.json",
            )
        )
    acceptance_document_for_refs = _read_json(
        root / "validation/ACCEPTANCE_CASES.json", findings
    )
    negative_document_for_refs = _read_json(
        root / "validation/NEGATIVE_CASES.json", findings
    )
    acceptance_cases_for_refs = (
        acceptance_document_for_refs.get("cases", [])
        if isinstance(acceptance_document_for_refs, Mapping)
        else []
    )
    negative_cases_for_refs = (
        negative_document_for_refs.get("cases", [])
        if isinstance(negative_document_for_refs, Mapping)
        else []
    )
    expected_result_refs = sorted(
        [
            *[
                case_result_ref("ACCEPTANCE", str(case.get("case_id")))
                for case in acceptance_cases_for_refs
                if isinstance(case, Mapping) and case.get("case_id")
            ],
            *[
                case_result_ref("NEGATIVE", str(case.get("case_id")))
                for case in negative_cases_for_refs
                if isinstance(case, Mapping) and case.get("case_id")
            ],
            *[
                str(item["result_ref"])
                for item in expected_registry_invocations
            ],
            public_result_ref,
        ]
    )
    command_ownership_valid = all(
        command_id in registered_commands
        and command_id in owned_certification_commands
        and commands.get(command_id, {}).get("owner_workpack_id")
        == CASE_EVIDENCE_WRITER_WORKPACK_ID
        and registered_commands[command_id].get("owner_workpack_id")
        == CASE_EVIDENCE_WRITER_WORKPACK_ID
        and owned_certification_commands[command_id].get("owner_workpack_id")
        == CASE_EVIDENCE_WRITER_WORKPACK_ID
        and commands.get(command_id, {}).get("argv")
        == registered_commands[command_id].get("argv")
        and list(commands.get(command_id, {}).get("argv") or [])
        == list(owned_certification_commands[command_id].get("argv") or [])[:4]
        and commands.get(command_id, {}).get("result_writer_contract", {}).get(
            "result_root_ref"
        )
        == CASE_EXECUTION_RESULT_ROOT_REF
        for command_id in expected_case_command_ids
    )
    expected_parameter_flags = {
        "LAB-RUN-ACCEPTANCE-CASE": ["--fixture-ref", "--result-ref"],
        "LAB-RUN-NEGATIVE-CASE": ["--fixture-ref", "--result-ref"],
        "LAB-RUN-REGISTRY-CASE": ["--fixture-ref", "--result-ref", "--read-plan-ref"],
        "LAB-RUN-CASE-PARTITION": [
            "--fixture-ref",
            "--job-id",
            "--lease-receipt-ref",
            "--result-fragment-ref",
            "--fragment-artifact-manifest-ref",
        ],
        "LAB-AGGREGATE-CASE-PARTITIONS": [
            "--fixture-ref",
            "--fragment-manifest-ref",
            "--aggregation-receipt-ref",
            "--aggregation-receipt-schema-ref",
            "--result-ref",
        ],
        "LAB-RUN-METAMORPHIC-CASE": [
            "--fixture-ref",
            "--resolution-receipt-ref",
            "--result-ref",
        ],
        "LAB-EVALUATE-CASE-ORACLE": ["--fixture-ref", "--result-ref"],
    }
    command_parameter_contracts_valid = all(
        commands.get(command_id, {}).get("parameter_contract", {}).get(
            "required_flags"
        )
        == flags
        for command_id, flags in expected_parameter_flags.items()
    ) and (
        commands.get("LAB-RUN-REGISTRY-CASE", {}).get("registry_read_protocol") == REGISTRY_READ_PROTOCOL
        and commands.get("LAB-RUN-CASE-PARTITION", {}).get("allowed_read_roots")
        == [LOGICAL_CANDIDATE_ROOT]
        and commands.get("LAB-RUN-METAMORPHIC-CASE", {}).get(
            "allowed_read_roots"
        )
        == [LOGICAL_CANDIDATE_ROOT]
        and commands.get("LAB-RUN-METAMORPHIC-CASE", {}).get(
            "implementation_entrypoint"
        )
        == PUBLIC_SKILL_JOB_PIPELINE_ENTRYPOINT
        and commands.get("LAB-RUN-METAMORPHIC-CASE", {}).get("job_pipeline_contract") == {
            "source_resolution_entrypoint": PUBLIC_SKILL_SOURCE_RESOLUTION_ENTRYPOINT,
            "specialization_ref": f"{PUBLIC_SKILL_JOB_INTERFACE_REF}#/dynamic_specialization_contract",
            "sequence": ["RESOLVE_AND_VERIFY_SOURCE", "DERIVE_JOB_ID", "SPECIALIZE_ARTIFACT_GRAPH",
                         "ACQUIRE_ONE_JOB_LEASE", "RUN_DECLARED_STAGES", "VERIFY_JOB_DESCRIPTORS"],
            "lease_authority": "EXISTING_EXECUTION_AUTHORIZATION_ONLY",
            "lease_job_id_pointer": "/derived_job_id",
            "leased_read_scope": "TRANSITIVE_ARTIFACT_INPUTS_AND_DECLARED_RUNTIME_PROVIDERS_FOR_ONE_JOB",
            "leased_write_root": {"root_ref": "harness-resource://execution/jobs", "child_from_pointer": "/derived_job_id"},
            "caller_write_scope": "CASE_RECEIPTS_ONLY",
            "descriptor_consumer": "external_lab.oracle:verify_job_artifact_descriptors_v1",
            "authoring_execution_forbidden": True,
        }
        and commands.get("LAB-RUN-METAMORPHIC-CASE", {}).get(
            "parameter_contract", {}
        ).get("source_resolution_entrypoint")
        == PUBLIC_SKILL_SOURCE_RESOLUTION_ENTRYPOINT
        and commands.get("LAB-RUN-METAMORPHIC-CASE", {}).get(
            "network_access_contract"
        )
        == {
            "mode": "READ_ONLY_HTTPS_FOR_DECLARED_PUBLIC_SKILL_URL",
            "allowed_hosts": ["github.com"],
            "request_url_pointer": "/input/skill_url",
            "resolution_receipt_required": True,
            "resolved_tree_bytes_required": True,
            "target_skill_execution_forbidden": True,
        }
        and commands.get("LAB-AGGREGATE-CASE-PARTITIONS", {}).get(
            "allowed_read_roots"
        )
        == [LOGICAL_CANDIDATE_ROOT, CASE_EXECUTION_RESULT_ROOT_REF]
    )
    lab_cli_bundle_path = (
        root
        / "project_start_packages/external_lab/task_bundles/"
        "LAB-CLI.task_bundle.json"
    )
    semantic_lab_bundle_required = bool(
        isinstance(frozen_ir, Mapping)
        and explicit_production_enabled(frozen_ir)
    )
    lab_cli_bundle = (
        _read_json(lab_cli_bundle_path, findings)
        if semantic_lab_bundle_required or lab_cli_bundle_path.is_file()
        else None
    )
    lab_cli_case_contract = (
        lab_cli_bundle.get("lab_case_execution_contract", {})
        if isinstance(lab_cli_bundle, Mapping)
        else {}
    )
    resolver_obligation = (
        "Implement and invoke "
        f"{PUBLIC_SKILL_SOURCE_RESOLUTION_ENTRYPOINT} from "
        "run-metamorphic-case before content analysis."
    )
    metamorphic_invocations = (
        manifest.get("metamorphic_case_invocations", [])
        if isinstance(manifest, Mapping)
        else []
    )
    metamorphic_invocation = (
        metamorphic_invocations[0]
        if len(metamorphic_invocations) == 1
        and isinstance(metamorphic_invocations[0], Mapping)
        else {}
    )
    metamorphic_command = commands.get("LAB-RUN-METAMORPHIC-CASE", {})
    resolver_bindings = [
        (
            public_job_interface.get("dynamic_specialization_contract", {})
            .get("source_resolution_entrypoint")
            if isinstance(public_job_interface, Mapping)
            else None
        ),
        metamorphic_invocation.get("source_resolution_entrypoint"),
        metamorphic_command.get("job_pipeline_contract", {}).get("source_resolution_entrypoint"),
        metamorphic_command.get("parameter_contract", {}).get(
            "source_resolution_entrypoint"
        ),
    ]
    if semantic_lab_bundle_required or lab_cli_bundle_path.is_file():
        resolver_bindings.append(
            lab_cli_case_contract.get("required_source_resolution_entrypoint")
        )
    resolver_missing = any(value is None for value in resolver_bindings)
    if semantic_lab_bundle_required or lab_cli_bundle_path.is_file():
        resolver_missing = resolver_missing or (
            resolver_obligation
            not in lab_cli_case_contract.get("implementation_obligations", [])
        )
        if lab_cli_case_contract.get("required_job_pipeline_entrypoint") != PUBLIC_SKILL_JOB_PIPELINE_ENTRYPOINT:
            findings.append(_finding("PUBLIC_SKILL_JOB_PIPELINE_BINDING_MISMATCH", "LAB-CLI"))
    resolver_mismatch = any(
        value is not None
        and value != PUBLIC_SKILL_SOURCE_RESOLUTION_ENTRYPOINT
        for value in resolver_bindings
    )
    if resolver_missing:
        findings.append(
            _finding(
                "PUBLIC_SKILL_SOURCE_RESOLVER_UNREACHABLE",
                "LAB-RUN-METAMORPHIC-CASE",
            )
        )
    if resolver_mismatch:
        findings.append(
            _finding(
                "PUBLIC_SKILL_SOURCE_RESOLVER_BINDING_MISMATCH",
                "LAB-RUN-METAMORPHIC-CASE",
            )
        )
    fixture_acceptance_artifacts = [
        artifact
        for artifact in (
            artifact_index.values()
            if isinstance(artifact_index, Mapping)
            else []
        )
        if isinstance(artifact, Mapping)
        and artifact.get("artifact_kind") == "FIXTURE_ACCEPTANCE_RECEIPT"
    ]
    fixture_evidence_binding_valid = all(
        artifact.get("depends_on_evidence_refs") == expected_result_refs
        and artifact.get("case_evidence_ownership", {}).get(
            "writer_workpack_id"
        )
        == CASE_EVIDENCE_WRITER_WORKPACK_ID
        for artifact in fixture_acceptance_artifacts
    )
    if (
        not isinstance(manifest, Mapping)
        or manifest.get("status") != "DECLARE_ONLY"
        or manifest.get("execution_started") is not False
        or manifest.get("authorization_ref") is not None
        or manifest.get("owner_project_id") != "EXTERNAL_CONFORMANCE_LAB"
        or manifest.get("owner_workpack_id")
        != CASE_EVIDENCE_WRITER_WORKPACK_ID
        or manifest.get("result_root_ref") != CASE_EXECUTION_RESULT_ROOT_REF
        or manifest.get("result_writer_cardinality")
        != "EXACTLY_ONE_WORKPACK"
        or manifest.get("job_read_partition_policy")
        != (
            "EXACTLY_ONE_ACTIVE_JOB_LEASE_PER_CASE_PARTITION_THEN_"
            "HASH_BOUND_CASE_AGGREGATION"
        )
        or manifest.get("job_read_partition_policy_case_kinds") != ["ACCEPTANCE", "NEGATIVE"]
        or manifest.get("expected_case_result_refs") != expected_result_refs
        or manifest.get("registry_case_invocations")
        != expected_registry_invocations
        or manifest.get("metamorphic_case_invocations")
        != expected_metamorphic_invocations
        or public_case_id != PUBLIC_SKILL_METAMORPHIC_CASE_ID
        or not _strict_public_metamorphic_result_schema(
            public_schema, public_vector
        )
        or not registry_is_consistent
        or manifest.get("oracle_evaluator_registry_ref")
        != ORACLE_EVALUATOR_REGISTRY_REF
        or manifest.get("oracle_evaluator_registry_sha256")
        != _file_hash(registry_path)
        or manifest.get("public_skill_job_interface_ref")
        != PUBLIC_SKILL_JOB_INTERFACE_REF
        or not public_job_interface_path.is_file()
        or manifest.get("public_skill_job_interface_sha256")
        != (
            _file_hash(public_job_interface_path)
            if public_job_interface_path.is_file()
            else None
        )
        or manifest.get("assertion_operators")
        != [
            "VALIDATED_RECEIPT_EXISTS",
            "SET_EQUALS",
            "ALL_ARTIFACTS_SCHEMA_HASH_AND_ORACLE_PASS",
            "EXACT_SOURCE_JOBS_MATCH",
            "EQUALS",
        ]
        or manifest.get("manifest_sha256")
        != _hash_without_field(manifest, "manifest_sha256")
        or set(commands) != expected_case_command_ids
        or not command_ownership_valid
        or not command_parameter_contracts_valid
        or not fixture_evidence_binding_valid
        or any(
            command.get("command_sha256")
            != _hash_without_field(command, "command_sha256")
            for command in commands.values()
        )
        or not _strict_case_result_schema(result_schema)
        or not isinstance(artifact_index, Mapping)
    ):
        findings.append(
            _finding(
                "CASE_EXECUTION_MANIFEST_INVALID",
                "validation/CASE_EXECUTION_MANIFEST.json",
            )
        )
    for relative, negative in (
        ("validation/ACCEPTANCE_CASES.json", False),
        ("validation/NEGATIVE_CASES.json", True),
    ):
        document = _read_json(root / relative, findings)
        cases = document.get("cases") if isinstance(document, Mapping) else None
        if not isinstance(cases, list) or not cases:
            findings.append(
                _finding("EXECUTABLE_CASE_SET_MISSING", relative)
            )
            continue
        if negative:
            mutation_manifest_hashes = [
                str(case.get("mutation_manifest_sha256") or "")
                for case in cases
                if isinstance(case, Mapping)
            ]
            if (
                len(mutation_manifest_hashes) != len(cases)
                or any(not SHA256_RE.fullmatch(value) for value in mutation_manifest_hashes)
                or len(set(mutation_manifest_hashes)) != len(mutation_manifest_hashes)
            ):
                findings.append(
                    _finding(
                        "NEGATIVE_MUTATION_MANIFEST_SET_NOT_UNIQUE",
                        relative,
                    )
                )
        for index, case in enumerate(cases):
            label = f"{relative}.cases[{index}]"
            if not isinstance(case, Mapping):
                findings.append(_finding("EXECUTABLE_CASE_INVALID", label))
                continue
            required_arrays = (
                ("preconditions", True),
                ("steps", True),
                ("assertions", True),
            )
            if not negative:
                required_arrays = (("inputs", True), *required_arrays)
            invalid_arrays = [
                field
                for field, require_nonempty in required_arrays
                if not isinstance(case.get(field), list)
                or (require_nonempty and not case.get(field))
            ]
            steps = case.get("steps") or []
            assertions = case.get("assertions") or []
            oracle = case.get("oracle_contract")
            fixture_path = _candidate_uri_path(root, case.get("fixture_ref"))
            fixture_document = (
                _read_json(fixture_path, findings)
                if fixture_path is not None and fixture_path.is_file()
                else None
            )
            case_schema_path = _candidate_uri_path(
                root, case.get("result_schema_ref")
            )
            case_schema = (
                _read_json(case_schema_path, findings)
                if case_schema_path is not None and case_schema_path.is_file()
                else None
            )
            case_command_id = case.get("executor_command_id")
            case_command = commands.get(str(case_command_id))
            case_argv = case.get("executor_argv")
            oracle_command_id = (
                oracle.get("executor_command_id")
                if isinstance(oracle, Mapping)
                else None
            )
            oracle_command = commands.get(str(oracle_command_id))
            oracle_argv = (
                oracle.get("executor_argv")
                if isinstance(oracle, Mapping)
                else None
            )
            result_ref = case.get("result_ref")
            expected_command_id = (
                "LAB-RUN-NEGATIVE-CASE"
                if negative
                else "LAB-RUN-ACCEPTANCE-CASE"
            )
            fixture_input = (
                fixture_document.get("input")
                if isinstance(fixture_document, Mapping)
                else None
            )
            expected_partition_job_ids = sorted(
                {
                    str(expectation["job_id"])
                    for expectation in (
                        fixture_input.get("artifact_expectations", [])
                        if isinstance(fixture_input, Mapping)
                        else []
                    )
                    if isinstance(expectation, Mapping)
                    and expectation.get("job_id")
                }
            )
            expected_partitions = [
                {
                    "job_id": job_id,
                    "lease_receipt_ref": (
                        f"{LOGICAL_EXECUTION_ROOT}/evidence/"
                        "job_artifact_leases/LAB-CERTIFICATION/"
                        f"LAB-RUN-CASE-PARTITION/{job_id}.lease.json"
                    ),
                    "result_fragment_ref": (
                        f"{CASE_EXECUTION_RESULT_ROOT_REF}/fragments/"
                        f"{'negative' if negative else 'acceptance'}-"
                        f"{_slug(str(case.get('case_id'))).lower()}/"
                        f"{_slug(job_id).lower()}.result.json"
                    ),
                    "fragment_artifact_manifest_ref": (
                        f"{CASE_EXECUTION_RESULT_ROOT_REF}/fragments/"
                        f"{'negative' if negative else 'acceptance'}-"
                        f"{_slug(str(case.get('case_id'))).lower()}/"
                        f"{_slug(job_id).lower()}.artifact-manifest.json"
                    ),
                }
                for job_id in expected_partition_job_ids
            ]
            expected_fragment_manifest_ref = (
                f"{CASE_EXECUTION_RESULT_ROOT_REF}/fragments/"
                f"{'negative' if negative else 'acceptance'}-"
                f"{_slug(str(case.get('case_id'))).lower()}/manifest.json"
            )
            expected_aggregation_receipt_ref = (
                f"{CASE_EXECUTION_RESULT_ROOT_REF}/aggregation/"
                f"{'negative' if negative else 'acceptance'}-"
                f"{_slug(str(case.get('case_id'))).lower()}.receipt.json"
            )
            expected_aggregation_schema_relative = (
                "validation/schemas/cases/"
                f"{'negative' if negative else 'acceptance'}-"
                f"{_slug(str(case.get('case_id'))).lower()}."
                "aggregation-receipt.schema.json"
            )
            expected_aggregation_schema_ref = (
                f"{LOGICAL_CANDIDATE_ROOT}/"
                f"{expected_aggregation_schema_relative}"
            )
            aggregation_schema_path = root / expected_aggregation_schema_relative
            aggregation_schema = (
                _read_json(aggregation_schema_path, findings)
                if aggregation_schema_path.is_file()
                else None
            )
            aggregation_schema_sha256 = (
                _file_hash(aggregation_schema_path)
                if aggregation_schema_path.is_file()
                else None
            )
            expected_partition_argvs = [
                [
                    f"{LOGICAL_EXECUTION_ROOT}/project_start_packages/"
                    "external_lab/.venv/bin/python",
                    "-m",
                    "external_lab",
                    "run-case-partition",
                    "--fixture-ref",
                    case.get("fixture_ref"),
                    "--job-id",
                    partition["job_id"],
                    "--lease-receipt-ref",
                    partition["lease_receipt_ref"],
                    "--result-fragment-ref",
                    partition["result_fragment_ref"],
                    "--fragment-artifact-manifest-ref",
                    partition["fragment_artifact_manifest_ref"],
                ]
                for partition in expected_partitions
            ]
            expected_aggregation_argv = [
                f"{LOGICAL_EXECUTION_ROOT}/project_start_packages/"
                "external_lab/.venv/bin/python",
                "-m",
                "external_lab",
                "aggregate-case-partitions",
                "--fixture-ref",
                case.get("fixture_ref"),
                "--fragment-manifest-ref",
                expected_fragment_manifest_ref,
                "--aggregation-receipt-ref",
                expected_aggregation_receipt_ref,
                "--aggregation-receipt-schema-ref",
                expected_aggregation_schema_ref,
                "--result-ref",
                result_ref,
            ]
            partition_command = commands.get("LAB-RUN-CASE-PARTITION")
            aggregation_command = commands.get(
                "LAB-AGGREGATE-CASE-PARTITIONS"
            )
            partition_contract_invalid = bool(
                case.get("job_read_partitions") != expected_partitions
                or case.get("job_partition_manifest_sha256")
                != _json_hash(expected_partitions)
                or case.get("partition_executor_command_id")
                != "LAB-RUN-CASE-PARTITION"
                or not isinstance(partition_command, Mapping)
                or case.get("partition_executor_argvs")
                != expected_partition_argvs
                or case.get("fragment_manifest_ref")
                != expected_fragment_manifest_ref
                or case.get("aggregation_executor_command_id")
                != "LAB-AGGREGATE-CASE-PARTITIONS"
                or not isinstance(aggregation_command, Mapping)
                or case.get("aggregation_executor_argv")
                != expected_aggregation_argv
                or case.get("aggregation_receipt_ref")
                != expected_aggregation_receipt_ref
                or case.get("aggregation_receipt_schema_ref")
                != expected_aggregation_schema_ref
                or case.get("aggregation_receipt_schema_sha256")
                != aggregation_schema_sha256
                or not _strict_case_aggregation_receipt_schema(
                    aggregation_schema,
                    case_id=str(case.get("case_id")),
                    case_kind="NEGATIVE" if negative else "ACCEPTANCE",
                    fragment_manifest_ref=expected_fragment_manifest_ref,
                    fragment_refs=[
                        item["result_fragment_ref"]
                        for item in expected_partitions
                    ],
                    result_ref=str(result_ref),
                )
            )
            if partition_contract_invalid:
                findings.append(
                    _finding(
                        "CASE_PARTITION_AGGREGATION_CONTRACT_INCOMPLETE",
                        label,
                    )
                )
            executable_binding_invalid = bool(
                fixture_path is None
                or not fixture_path.is_file()
                or _file_hash(fixture_path) != case.get("fixture_sha256")
                or case_command_id != expected_command_id
                or not isinstance(case_command, Mapping)
                or case.get("executor_command_manifest_ref")
                != f"{LOGICAL_CANDIDATE_ROOT}/validation/CASE_EXECUTION_MANIFEST.json"
                or not isinstance(case_argv, list)
                or len(case_argv) < 8
                or case_argv[:4]
                != list(case_command.get("argv", []))[:4]
                or case.get("fixture_ref") not in case_argv
                or result_ref not in case_argv
                or not isinstance(result_ref, str)
                or not result_ref.startswith(f"{LOGICAL_EXECUTION_ROOT}/")
                or case_schema_path is None
                or not case_schema_path.is_file()
                or not isinstance(case_schema, Mapping)
                or case_schema.get("$id") != case.get("result_schema_ref")
                or case_schema.get("properties", {})
                .get("fixture_sha256", {})
                .get("const")
                != case.get("fixture_sha256")
                or case.get("result_schema_sha256")
                != _file_hash(case_schema_path)
                or case.get("job_read_partition_policy")
                != (
                    "EXACTLY_ONE_ACTIVE_JOB_LEASE_PER_CASE_PARTITION_"
                    "THEN_HASH_BOUND_CASE_AGGREGATION"
                )
                or case.get("job_read_partitions") != expected_partitions
                or case.get("job_partition_manifest_sha256")
                != _json_hash(expected_partitions)
                or case.get("partition_executor_command_id")
                != "LAB-RUN-CASE-PARTITION"
                or not isinstance(partition_command, Mapping)
                or case.get("partition_executor_argvs")
                != expected_partition_argvs
                or case.get("fragment_manifest_ref")
                != expected_fragment_manifest_ref
                or case.get("aggregation_executor_command_id")
                != "LAB-AGGREGATE-CASE-PARTITIONS"
                or not isinstance(aggregation_command, Mapping)
                or case.get("aggregation_executor_argv")
                != expected_aggregation_argv
                or case.get("aggregation_receipt_ref")
                != expected_aggregation_receipt_ref
                or case.get("aggregation_receipt_schema_ref")
                != expected_aggregation_schema_ref
                or case.get("aggregation_receipt_schema_sha256")
                != aggregation_schema_sha256
                or case_schema.get("x-aggregation-receipt-schema")
                != {
                    "ref": expected_aggregation_schema_ref,
                    "sha256": aggregation_schema_sha256,
                }
                or not _strict_case_aggregation_receipt_schema(
                    aggregation_schema,
                    case_id=str(case.get("case_id")),
                    case_kind="NEGATIVE" if negative else "ACCEPTANCE",
                    fragment_manifest_ref=expected_fragment_manifest_ref,
                    fragment_refs=[
                        item["result_fragment_ref"]
                        for item in expected_partitions
                    ],
                    result_ref=str(result_ref),
                )
                or not _strict_case_specific_result_schema(
                    case_schema,
                    fixture_document,
                    negative=negative,
                    job_read_partitions=expected_partitions,
                )
                or oracle_command_id != "LAB-EVALUATE-CASE-ORACLE"
                or not isinstance(oracle_command, Mapping)
                or not isinstance(oracle_argv, list)
                or len(oracle_argv) < 8
                or oracle_argv[:4]
                != list(oracle_command.get("argv", []))[:4]
                or case.get("fixture_ref") not in oracle_argv
                or result_ref not in oracle_argv
                or oracle.get("result_schema_ref")
                != case.get("result_schema_ref")
                or oracle.get("result_schema_sha256")
                != case.get("result_schema_sha256")
                or (
                    not negative
                    and not _concrete_acceptance_fixture(
                        fixture_document,
                        artifact_index,
                        repository_pins,
                    )
                )
                or (
                    negative
                    and (
                        not isinstance(fixture_document, Mapping)
                        or not isinstance(fixture_document.get("input"), Mapping)
                        or case.get("mutation_manifest_ref")
                        != f"{case.get('fixture_ref')}#/input/mutation_manifest"
                        or case.get("mutation_manifest_sha256")
                        != fixture_document["input"].get(
                            "mutation_manifest_sha256"
                        )
                        or not _concrete_negative_input(
                            fixture_document["input"],
                            case.get("expected_failure"),
                            artifacts_declared=bool(artifact_index),
                            artifact_index=artifact_index,
                        )
                    )
                )
                or any(
                    not isinstance(step, Mapping)
                    or step.get("command_id") != expected_command_id
                    or step.get("fixture_ref") != case.get("fixture_ref")
                    or step.get("result_ref") != result_ref
                    for step in steps
                )
            )
            if (
                invalid_arrays
                or executable_binding_invalid
                or any(
                    not isinstance(step, Mapping)
                    or not step.get("step_id")
                    or not step.get("action")
                    for step in steps
                )
                or any(
                    not isinstance(assertion, Mapping)
                    or not assertion.get("assertion_id")
                    or not assertion.get("operator")
                    or "expected" not in assertion
                    or (
                        assertion.get("operator") == "VALIDATED_RECEIPT_EXISTS"
                        and assertion.get("actual_ref") != result_ref
                    )
                    for assertion in assertions
                )
                or not isinstance(oracle, Mapping)
                or any(
                    not oracle.get(field)
                    for field in ("oracle_id", "owner", "decision_rule")
                )
                or not isinstance(oracle.get("evidence_required"), list)
                or not oracle.get("evidence_required")
                or not isinstance(oracle.get("common_mode_exclusions"), list)
                or not oracle.get("common_mode_exclusions")
                or oracle.get("evaluator_id") != "EXACT_CASE_SET_ORACLE_V1"
                or oracle.get("evaluator_registry_ref")
                != ORACLE_EVALUATOR_REGISTRY_REF
                or not isinstance(fixture_document, Mapping)
                or not isinstance(
                    fixture_document.get("oracle_bindings"), Mapping
                )
                or any(
                    oracle.get(field)
                    != fixture_document["oracle_bindings"].get(field)
                    for field in (
                        "assertion_manifest_sha256",
                        "artifact_manifest_sha256",
                        "source_job_manifest_sha256",
                        "mutation_manifest_sha256",
                    )
                )
            ):
                findings.append(
                    _finding(
                        "EXECUTABLE_CASE_ORACLE_INCOMPLETE",
                        f"{label}:{','.join(invalid_arrays)}",
                    )
                )
    return findings


def _check_package_lifecycle_identity(root: Path) -> list[dict[str, Any]]:
    findings: list[dict[str, Any]] = []
    package = _read_json(root / "PACKAGE_MANIFEST.json", findings)
    context = _read_json(root / "START_CONTEXT.json", findings)
    provenance = _read_json(root / "FACTORY_PROVENANCE.json", findings)
    if not all(isinstance(value, Mapping) for value in (package, context, provenance)):
        return findings
    epochs = {
        package.get("requirement_epoch"),
        context.get("requirement_epoch"),
        provenance.get("requirement_epoch"),
    }
    package_version = package.get("version")
    if (
        len(epochs) != 1
        or any(isinstance(value, bool) or not isinstance(value, int) for value in epochs)
        or context.get("package_version") != package_version
        or package_version in (None, "", "0.1.0-draft")
    ):
        findings.append(
            _finding(
                "PACKAGE_LIFECYCLE_IDENTITY_MISMATCH",
                "Requirement epoch and package version must be identical across provenance, manifest, and Start Context",
            )
        )
    return findings


def _check_candidate_execution_separation(root: Path) -> list[dict[str, Any]]:
    findings: list[dict[str, Any]] = []
    candidate_root, execution_root, context = _context_roots(root, findings)
    if not context:
        return findings
    immutable = (
        context.get("candidate_root_access")
        == "READ_ONLY_AFTER_ATOMIC_PUBLICATION"
    )
    if not immutable:
        findings.append(
            _finding(
                "CANDIDATE_IMMUTABILITY_VIOLATION",
                "Candidate root must become read-only after atomic publication",
            )
        )
    portable = _portable_context(context)
    expected_candidate_value = (
        LOGICAL_CANDIDATE_ROOT if portable else str(candidate_root)
    )
    expected_execution_value = (
        LOGICAL_EXECUTION_ROOT if portable else str(execution_root)
    )
    if (
        context.get("target_root") != expected_candidate_value
        or context.get("candidate_root") != expected_candidate_value
        or context.get("execution_root") != expected_execution_value
        or context.get("execution_root_status") != "PLANNED_NOT_CREATED"
        or context.get("candidate_execution_root_overlap") is not False
        or candidate_root == execution_root
        or candidate_root.is_relative_to(execution_root)
        or execution_root.is_relative_to(candidate_root)
    ):
        findings.append(
            _finding(
                "CANDIDATE_IMMUTABILITY_VIOLATION",
                "START_CONTEXT candidate and execution roots are not disjoint",
            )
        )

    read_list_keys = {"allowed_read_paths"}
    write_list_keys = {
        "allowed_write_paths",
        "allowed_write_roots",
        "success_output_refs",
    }
    execution_scalar_keys = {
        "workspace_root_abs",
        "cwd_abs",
        "cwd_absolute",
        "executable",
        "executable_abs",
        "driver_entrypoint_abs",
        "root_abs",
        "repository_root_abs",
        "self_validation_ref",
        "final_runtime_entrypoint_abs",
        "build_program_driver_entrypoint_abs",
    }

    def check_path(value: Any, *, expected_root: Path, label: str) -> None:
        path = Path(str(value)).expanduser()
        valid = (
            _logical_path_within(value, expected_root)
            if portable
            else path.is_absolute()
            and path.resolve().is_relative_to(expected_root)
        )
        if not valid:
            findings.append(
                _finding(
                    "CANDIDATE_IMMUTABILITY_VIOLATION",
                    f"{label} escapes {expected_root}: {value}",
                )
            )

    def check_read_path(value: Any, *, label: str) -> None:
        path = Path(str(value)).expanduser()
        valid = (
            (
                _logical_path_within(value, candidate_root)
                or _logical_path_within(value, execution_root)
            )
            if portable
            else path.is_absolute()
            and (
                path.resolve().is_relative_to(candidate_root)
                or path.resolve().is_relative_to(execution_root)
            )
        )
        if not valid:
            findings.append(
                _finding(
                    "CANDIDATE_IMMUTABILITY_VIOLATION",
                    (
                        f"{label} escapes candidate and planned execution "
                        f"read domains: {value}"
                    ),
                )
            )

    nonexecutable_fixture_payload_ids: set[int] = set()

    def visit(value: Any, location: str) -> None:
        if id(value) in nonexecutable_fixture_payload_ids:
            return
        if isinstance(value, dict):
            for key, item in value.items():
                label = f"{location}.{key}"
                if key in read_list_keys and isinstance(item, list):
                    for entry in item:
                        check_read_path(entry, label=label)
                elif key in write_list_keys and isinstance(item, list):
                    for entry in item:
                        check_path(
                            entry, expected_root=execution_root, label=label
                        )
                elif key in execution_scalar_keys and item not in (None, ""):
                    check_path(item, expected_root=execution_root, label=label)
                visit(item, label)
        elif isinstance(value, list):
            for index, item in enumerate(value):
                visit(item, f"{location}[{index}]")

    for path in sorted(root.rglob("*.json")):
        document = _read_json(path, findings)
        if isinstance(document, (dict, list)):
            relative = path.relative_to(root).as_posix()
            if relative == "validation/NEGATIVE_CASES.json":
                nonexecutable_fixture_payload_ids = (
                    _nonexecutable_negative_fixture_payload_ids(document)
                )
            elif (
                relative.startswith("validation/case_fixtures/negative-")
                and isinstance(document, Mapping)
                and document.get("case_kind") == "NEGATIVE"
            ):
                nonexecutable_fixture_payload_ids = {id(document.get("input"))}
            else:
                nonexecutable_fixture_payload_ids = set()
            visit(document, relative)

    capsule = _read_json(root / "CAPSULE.json", findings)
    forbidden = capsule.get("forbidden_write_paths", []) if isinstance(capsule, dict) else []
    forbidden_candidate_value = (
        LOGICAL_CANDIDATE_ROOT if portable else str(candidate_root)
    )
    if forbidden_candidate_value not in forbidden:
        findings.append(
            _finding(
                "CANDIDATE_IMMUTABILITY_VIOLATION",
                "CAPSULE.json must forbid the entire candidate root",
            )
        )
    return findings


def _check_physical_candidate_read_only(root: Path) -> list[dict[str, Any]]:
    findings: list[dict[str, Any]] = []
    for path in (root, *sorted(root.rglob("*"))):
        try:
            mode = path.lstat().st_mode
        except OSError as exc:
            findings.append(
                _finding("CANDIDATE_PERMISSION_INSPECTION_FAILED", str(exc))
            )
            continue
        if mode & 0o222:
            findings.append(
                _finding(
                    "CANDIDATE_PHYSICALLY_WRITABLE",
                    path.relative_to(root).as_posix() if path != root else ".",
                )
            )
    return findings


def _permission_drift_is_nonblocking(
    requirement_ir: Mapping[str, Any] | None,
) -> bool:
    """Recognize the explicit personal-local best-effort permission policy."""

    if not isinstance(requirement_ir, Mapping):
        return False
    target = requirement_ir.get("target")
    if not isinstance(target, Mapping):
        return False
    policy = target.get("start_package_immutability_policy")
    return bool(
        isinstance(policy, Mapping)
        and policy.get("candidate_root_read_only_after_atomic_publication")
        is True
        and policy.get("physical_permission_enforcement")
        == "BEST_EFFORT_PERSONAL_LOCAL"
        and policy.get("permission_drift_disposition")
        == "NON_BLOCKING_DIAGNOSTIC"
        and policy.get("candidate_write_after_publication") == "FORBIDDEN"
        and policy.get("candidate_execution_roots_must_not_overlap") is True
    )


def _check_portability(root: Path) -> list[dict[str, Any]]:
    findings: list[dict[str, Any]] = []
    portable_inventory: set[str] | None = None
    manifest_path = root / "validation/PORTABILITY_MANIFEST.json"
    if not manifest_path.is_file():
        return [
            _finding(
                "PORTABILITY_MANIFEST_MISSING",
                "every versioned Candidate must export logical Resource roots",
            )
        ]
    manifest = _read_json(manifest_path, findings)
    context = _read_json(root / "START_CONTEXT.json", findings)
    if not isinstance(manifest, dict) or not isinstance(context, dict):
        return findings
    expected_roots = {
        "candidate": LOGICAL_CANDIDATE_ROOT,
        "execution": LOGICAL_EXECUTION_ROOT,
    }
    expected_self_check = {
        "command": "python3 tools/self_check.py",
        "python_version_constraint": ">=3.11,<4",
        "standard_library_only": False,
        "network_required": False,
        "external_packages": ["cryptography>=45,<49"],
        "receiver_authority_preflight_mode": "PROFILE_AWARE",
    }
    frozen_ir = _read_json(
        root / "canonical_sources/FROZEN_REQUIREMENT_IR.json", findings
    )
    frozen_target = frozen_ir.get("target") if isinstance(frozen_ir, Mapping) else None
    local_authority_na = _local_profile_external_authority_not_applicable(
        root, frozen_target
    )
    external_authority_required = _external_receiver_authority_required(
        root, frozen_target
    )
    if external_authority_required:
        expected_self_check.update(
            {
                "external_receiver_authority_required": True,
                "external_receiver_authority_disposition": (
                    "REQUIRED_FOR_EXTERNAL_CERTIFICATION"
                ),
                "required_receiver_environment": [
                    "HF_SOURCE_AUTHORITY_POLICY_LOCK",
                    "HF_SOURCE_AUTHORITY_TRUST_ANCHOR",
                    "HF_SOURCE_AUTHORITY_TRUST_ANCHOR_SHA256",
                ],
                "receiver_policy_must_be_external_to_candidate": True,
                "receiver_trust_anchor_must_be_external_to_candidate": True,
                "receiver_trust_anchor_hash_must_be_pinned_outside_candidate": True,
            }
        )
    elif local_authority_na:
        profile = _read_json(
            root / "EPOCH38_GENERATION_PROFILE.json", findings
        )
        expected_self_check.update(
            {
                "external_receiver_authority_required": False,
                "external_receiver_authority_disposition": (
                    "NOT_APPLICABLE_SELF_USE_LOCAL_TRUSTED_OPERATOR"
                ),
                "external_certification_claimed": False,
                "optional_security_hardening": profile.get(
                    "optional_security_hardening"
                )
                if isinstance(profile, Mapping)
                else None,
            }
        )
    else:
        expected_self_check.update(
            {
                "external_receiver_authority_required": False,
                "external_receiver_authority_disposition": (
                    "NOT_APPLICABLE_NO_EXTERNAL_CERTIFICATION_PROFILE"
                ),
            }
        )
    if (
        manifest.get("portability_mode") != PORTABLE_MODE
        or manifest.get("local_binding_policy") != "LOCAL_ONLY_NON_EXPORTABLE"
        or manifest.get("logical_roots") != expected_roots
        or manifest.get("resolved_paths_persisted") is not False
        or manifest.get("external_symlinks_allowed") is not False
        or context.get("candidate_root") != LOGICAL_CANDIDATE_ROOT
        or context.get("target_root") != LOGICAL_CANDIDATE_ROOT
        or context.get("execution_root") != LOGICAL_EXECUTION_ROOT
        or not isinstance(manifest.get("release_requirements"), dict)
        or not manifest.get("release_requirements", {}).get("primary_runtime")
        or not isinstance(
            manifest.get("release_requirements", {}).get("required_tools"), list
        )
        or not isinstance(
            manifest.get("release_requirements", {}).get("required_plugins"), list
        )
        or not isinstance(
            manifest.get("release_requirements", {}).get("required_mcp_servers"),
            list,
        )
        or manifest.get("release_requirements", {}).get("self_check")
        != expected_self_check
    ):
        findings.append(
            _finding(
                "PORTABILITY_MANIFEST_INVALID",
                "logical roots or local-binding policy are inconsistent",
            )
        )
    self_check_path = root / "tools/self_check.py"
    portable_file_manifest_path = root / "validation/PORTABLE_FILE_MANIFEST.json"
    readme_path = root / "README.md"
    if not self_check_path.is_file():
        findings.append(
            _finding(
                "PORTABLE_SELF_CHECK_MISSING",
                "tools/self_check.py must travel with the Candidate",
            )
        )
    if not portable_file_manifest_path.is_file():
        findings.append(
            _finding(
                "PORTABLE_FILE_MANIFEST_MISSING",
                "validation/PORTABLE_FILE_MANIFEST.json is required",
            )
        )
    if not readme_path.is_file() or "python3 tools/self_check.py" not in readme_path.read_text(
        encoding="utf-8"
    ):
        findings.append(
            _finding(
                "PORTABLE_SELF_CHECK_UNDOCUMENTED",
                "README.md must document the exact offline self-check command",
            )
        )
    findings.extend(_check_runtime_binding_support(root, manifest))
    if local_authority_na:
        profile = _read_json(
            root / "EPOCH38_GENERATION_PROFILE.json", findings
        )
        if (
            isinstance(profile, Mapping)
            and isinstance(profile.get("active_requirement_epoch"), int)
            and profile["active_requirement_epoch"] >= 51
        ):
            negative = _read_json(
                root / "validation/NEGATIVE_CASES.json", findings
            )
            negative_cases = (
                negative.get("cases", [])
                if isinstance(negative, Mapping)
                else []
            )
            case_ids = {
                str(case.get("case_id"))
                for case in negative_cases
                if isinstance(case, Mapping)
            }
            required_case_ids = {
                "NEG-V29-E51-LOCAL-RUNTIME-AUTHORITY-CLAIM-DRIFT",
                "NEG-V29-E51-OPTIONAL-HARDENING-AUTHORITY-OMISSION",
            }
            if not required_case_ids.issubset(case_ids):
                findings.append(
                    _finding(
                        "LOCAL_RUNTIME_AUTHORITY_NEGATIVE_FIXTURES_MISSING",
                        ",".join(sorted(required_case_ids - case_ids)),
                    )
                )
    findings.extend(_check_toolchain_manifest(root, manifest))
    findings.extend(_check_portable_source_index(root))
    if portable_file_manifest_path.is_file():
        file_manifest = _read_json(portable_file_manifest_path, findings)
        if not isinstance(file_manifest, dict):
            findings.append(
                _finding(
                    "PORTABLE_FILE_MANIFEST_INVALID",
                    "portable file manifest must be a JSON object",
                )
            )
        else:
            excluded = set(file_manifest.get("excluded_files") or [])
            expected_excluded = {
                "validation/PORTABLE_FILE_MANIFEST.json",
                "validation/START_PACKAGE_VALIDATION_REPORT.json",
            }
            declared_files = file_manifest.get("files")
            actual_files = {
                path.relative_to(root).as_posix(): path
                for path in root.rglob("*")
                if path.is_file()
                and path.relative_to(root).as_posix() not in excluded
            }
            if (
                excluded != expected_excluded
                or file_manifest.get("hash_algorithm") != "sha256"
                or not isinstance(declared_files, dict)
                or file_manifest.get("file_count") != len(actual_files)
                or set(declared_files or {}) != set(actual_files)
            ):
                findings.append(
                    _finding(
                        "PORTABLE_INVENTORY_MISMATCH",
                        "portable file manifest does not exactly cover the Candidate",
                    )
                )
            if isinstance(declared_files, dict):
                portable_inventory = set(declared_files) | excluded
                for relative, expected_hash in declared_files.items():
                    path = actual_files.get(relative)
                    if path is None or _file_hash(path) != expected_hash:
                        findings.append(
                            _finding(
                                "PORTABLE_FILE_HASH_MISMATCH",
                                str(relative),
                            )
                        )
    if portable_inventory is not None:
        findings.extend(
            _check_candidate_resource_uri_closure(root, portable_inventory)
        )
        findings.extend(
            _check_portable_runtime_dependency_closure(root, portable_inventory)
        )
    for path in sorted(root.rglob("*")):
        relative = path.relative_to(root).as_posix()
        if path.is_symlink():
            findings.append(_finding("EXTERNAL_SYMLINK_FORBIDDEN", relative))
            continue
        if not path.is_file() or path.suffix not in PORTABLE_TEXT_SUFFIXES:
            continue
        text = path.read_text(encoding="utf-8")
        match = LOCAL_PATH_RE.search(text)
        if match:
            findings.append(
                _finding(
                    "LOCAL_PATH_BINDING",
                    f"{relative}: {match.group(0).strip()}",
                )
            )
    return findings


def _candidate_uri_path(root: Path, uri: Any) -> Path | None:
    if not isinstance(uri, str) or not uri.startswith(
        f"{LOGICAL_CANDIDATE_ROOT}/"
    ):
        return None
    suffix = uri.removeprefix(f"{LOGICAL_CANDIDATE_ROOT}/")
    parts = Path(suffix).parts
    if not suffix or any(part in {"", ".", ".."} for part in parts):
        return None
    path = (root / suffix).resolve()
    return path if path.is_relative_to(root.resolve()) else None


def _check_candidate_resource_uri_closure(
    root: Path, portable_inventory: set[str]
) -> list[dict[str, Any]]:
    findings: list[dict[str, Any]] = []
    seen: set[tuple[str, str]] = set()
    resolved_root = root.resolve()
    for source in sorted(root.rglob("*")):
        if not source.is_file() or source.suffix not in PORTABLE_TEXT_SUFFIXES:
            continue
        try:
            text = source.read_text(encoding="utf-8")
        except UnicodeError:
            continue
        for uri in RESOURCE_URI_RE.findall(text):
            if uri == LOGICAL_CANDIDATE_ROOT:
                continue
            if not uri.startswith(f"{LOGICAL_CANDIDATE_ROOT}/"):
                continue
            suffix = uri.removeprefix(f"{LOGICAL_CANDIDATE_ROOT}/")
            parts = Path(suffix).parts
            target = (root / suffix).resolve()
            if (
                not suffix
                or any(part in {"", ".", ".."} for part in parts)
                or not target.is_relative_to(resolved_root)
                or not target.is_file()
                or target.is_symlink()
            ):
                finding = ("CANDIDATE_RESOURCE_URI_DANGLING", uri)
            elif target.relative_to(root).as_posix() not in portable_inventory:
                finding = (
                    "CANDIDATE_RESOURCE_URI_OUTSIDE_PORTABLE_INVENTORY",
                    uri,
                )
            else:
                continue
            if finding not in seen:
                seen.add(finding)
                findings.append(_finding(*finding))
    return findings


def _check_portable_runtime_dependency_closure(
    root: Path, portable_inventory: set[str]
) -> list[dict[str, Any]]:
    findings: list[dict[str, Any]] = []
    runtime_root = root / "tools/harness_foundry_runtime"
    for source in sorted(runtime_root.glob("*.py")):
        try:
            tree = ast.parse(source.read_text(encoding="utf-8"))
        except (OSError, UnicodeError, SyntaxError) as exc:
            findings.append(
                _finding(
                    "PORTABLE_RUNTIME_MODULE_INVALID",
                    f"{source.name}: {exc}",
                )
            )
            continue
        for node in ast.walk(tree):
            if not isinstance(node, ast.ImportFrom) or node.level != 1:
                continue
            dependencies = (
                [node.module.split(".", 1)[0]]
                if node.module
                else [alias.name.split(".", 1)[0] for alias in node.names]
            )
            for dependency in dependencies:
                module = runtime_root / f"{dependency}.py"
                package = runtime_root / dependency / "__init__.py"
                target = module if module.is_file() else package
                if not target.is_file():
                    findings.append(
                        _finding(
                            "PORTABLE_RUNTIME_DEPENDENCY_MISSING",
                            f"{source.name}: .{dependency}",
                        )
                    )
                    continue
                relative = target.relative_to(root).as_posix()
                if relative not in portable_inventory:
                    findings.append(
                        _finding(
                            "PORTABLE_RUNTIME_DEPENDENCY_OUTSIDE_INVENTORY",
                            relative,
                        )
                    )
    return findings


def _check_runtime_binding_support(
    root: Path, portability: Mapping[str, Any]
) -> list[dict[str, Any]]:
    findings: list[dict[str, Any]] = []
    contract_path = root / "validation/RUNTIME_BINDING_CONTRACT.json"
    setup_path = root / "tools/setup_runtime.py"
    readme_path = root / "README.md"
    expected_command = (
        "python3 tools/setup_runtime.py --execution-root "
        "../Harness_Foundry_execution"
    )
    contract = _read_json(contract_path, findings)
    runtime_setup = portability.get("release_requirements", {}).get(
        "runtime_setup"
    )
    setup_sha256 = _file_hash(setup_path) if setup_path.is_file() else None
    frozen_ir = _read_json(
        root / "canonical_sources/FROZEN_REQUIREMENT_IR.json", findings
    )
    target = frozen_ir.get("target") if isinstance(frozen_ir, Mapping) else None
    local_authority_na = _local_profile_external_authority_not_applicable(
        root, target
    )
    external_authority_required = _external_receiver_authority_required(
        root, target
    )
    expected_authority_disposition = _external_receiver_authority_disposition(
        root, target
    )
    required_true = (
        "validation_before_first_execution_root_write",
        "portable_manifest_preflight_required",
        "candidate_uri_preflight_required",
        "runtime_dependency_closure_required",
        "receiver_authority_preflight_required",
        "fresh_root_atomic_publish_required",
        "failure_cleanup_keeps_fresh_root_absent",
        "existing_root_fail_closed_by_default",
        "idempotent_reentry_requires_explicit_flag",
        "idempotent_reentry_requires_exact_receipt",
        "receiver_raw_execution_path_identity_required",
        "final_component_lstat_before_resolution_required",
        "parent_directory_identity_pinned_through_publish",
        "fresh_root_atomic_noreplace_required",
        "existing_receipt_nofollow_read_required",
    )
    if (
        not setup_path.is_file()
        or not isinstance(contract, dict)
        or contract.get("binding_mode") != "LOCAL_ONLY_NON_EXPORTABLE"
        or contract.get("setup_command") != expected_command
        or contract.get("candidate_write_policy") != "FORBIDDEN"
        or contract.get("root_overlap_policy") != "REJECT"
        or contract.get("resolved_machine_paths_exported") is not False
        or contract.get("setup_ref")
        != "harness-resource://candidate/tools/setup_runtime.py"
        or contract.get("setup_sha256") != setup_sha256
        or contract.get("fresh_root_same_parent_staging_required") is not True
        or contract.get("human_gate_consumption_before_binding_success_allowed")
        is not False
        or contract.get("existing_binding_overwrite_allowed") is not False
        or contract.get("receiver_authority_preflight_mode") != "PROFILE_AWARE"
        or contract.get("external_receiver_authority_required")
        != external_authority_required
        or contract.get("external_receiver_authority_disposition")
        != expected_authority_disposition
        or any(contract.get(field) is not True for field in required_true)
        or not isinstance(runtime_setup, dict)
        or runtime_setup.get("command") != expected_command
        or runtime_setup.get("writes_candidate") is not False
        or runtime_setup.get("setup_ref") != contract.get("setup_ref")
        or runtime_setup.get("setup_sha256") != setup_sha256
        or any(runtime_setup.get(field) is not True for field in required_true)
        or runtime_setup.get("receiver_authority_preflight_mode")
        != "PROFILE_AWARE"
        or runtime_setup.get("external_receiver_authority_required")
        != external_authority_required
        or runtime_setup.get("external_receiver_authority_disposition")
        != expected_authority_disposition
        or runtime_setup.get("existing_binding_overwrite_allowed") is not False
        or contract.get("unsupported_noreplace_platform_behavior") != "FAIL_CLOSED"
        or runtime_setup.get("unsupported_noreplace_platform_behavior") != "FAIL_CLOSED"
    ):
        findings.append(
            _finding(
                "RUNTIME_BINDING_CONTRACT_INVALID",
                "portable Candidate must ship an explicit local-only runtime binder",
            )
        )
    readme = (
        readme_path.read_text(encoding="utf-8") if readme_path.is_file() else ""
    )
    if expected_command not in readme:
        findings.append(
            _finding(
                "RUNTIME_BINDING_SETUP_UNDOCUMENTED",
                "README.md must document the exact runtime binding command",
            )
        )
    return findings


def _epoch33_runtime_binding_review_is_complete(value: Any) -> bool:
    if not isinstance(value, Mapping):
        return False
    preflight = value.get("runtime_binder_preflight_contract")
    routing = value.get("adversarial_domain_contract")
    binding = value.get("setup_runtime_binding_contract")
    standalone = value.get("standalone_missing_authority_contract")
    return (
        value.get("status") == "REQUIRED_IN_REPLACEMENT_CANDIDATE"
        and value.get("active_epochs")
        == {
            "architecture_epoch": 2,
            "control_plane_epoch": 2,
            "requirement_epoch": 33,
        }
        and value.get("closure_receipt_required") is True
        and value.get("closure_receipt_status")
        == "CLOSURE_REQUIRED_IN_REPLACEMENT_CANDIDATE_STATIC_RECEIPT"
        and set(value.get("finding_ids") or ())
        == {
            "HR-V032-001-BINDER-PREFLIGHT-INCOMPLETE",
            "HR-V032-002-ADVERSARIAL-DOMAIN-MISROUTED",
            "HR-V032-003-BINDER-HASH-ATOMICITY-UNBOUND",
            "HR-V032-004-STANDALONE-CASCADE-FALSE-FINDING",
        }
        and isinstance(preflight, Mapping)
        and all(
            preflight.get(field) is True
            for field in (
                "portable_manifest_before_first_execution_root_write",
                "all_candidate_uri_closure_before_first_execution_root_write",
                "runtime_dependency_closure_before_first_execution_root_write",
                "necessary_receiver_authority_before_first_execution_root_write",
            )
        )
        and isinstance(routing, Mapping)
        and routing.get("epoch32_uri_binder_cases_owner") == "RUNTIME_BINDER"
        and routing.get("source_authority_domain_excludes_runtime_binder_cases")
        is True
        and set(routing.get("runtime_binder_required_adversarial_cases") or ())
        == {
            "DANGLING_CANDIDATE_RESOURCE_URI",
            "CANDIDATE_RESOURCE_URI_OUTSIDE_PORTABLE_INVENTORY",
            "MISSING_PACKAGED_RUNTIME_RELATIVE_IMPORT",
            "BINDER_FAILURE_LEAVES_FRESH_EXECUTION_ROOT_ABSENT",
        }
        and isinstance(binding, Mapping)
        and all(
            binding.get(field) is True
            for field in (
                "runtime_binding_contract_binds_setup_runtime_sha256",
                "closure_receipt_binds_setup_runtime_sha256",
                "validation_before_first_execution_root_write",
                "fresh_root_same_parent_staging_required",
                "fresh_root_atomic_publish_required",
                "failure_cleanup_keeps_fresh_root_absent",
            )
        )
        and isinstance(standalone, Mapping)
        and standalone.get("missing_external_authority_root_finding_preserved")
        is True
        and standalone.get("dependent_adversarial_false_findings_suppressed")
        is True
    )


def _epoch34_runtime_binding_review_is_complete(value: Any) -> bool:
    if not isinstance(value, Mapping):
        return False
    existing_root = value.get("existing_execution_root_contract")
    execution = value.get("required_regression_execution_contract")
    implementation = value.get("implementation_evidence")
    return (
        value.get("status") == "REQUIRED_IN_REPLACEMENT_CANDIDATE"
        and value.get("active_epochs")
        == {
            "architecture_epoch": 2,
            "control_plane_epoch": 2,
            "requirement_epoch": 34,
        }
        and value.get("closure_receipt_required") is True
        and value.get("closure_receipt_status")
        == CLOSURE_DECLARATION_STATUS
        and set(value.get("finding_ids") or ())
        == set(EPOCH34_REVIEW_FINDING_IDS)
        and tuple(value.get("required_regression_tests") or ())
        == EPOCH34_REQUIRED_REGRESSION_TESTS
        and isinstance(existing_root, Mapping)
        and existing_root.get("fail_closed_by_default") is True
        and existing_root.get("explicit_idempotent_reentry_allowed") is True
        and existing_root.get("exact_existing_receipt_required") is True
        and existing_root.get("receipt_overwrite_allowed") is False
        and isinstance(execution, Mapping)
        and execution.get("factory_validator_executes_exact_hash_bound_tests")
        is True
        and execution.get("candidate_publication_blocked_on_missing_test") is True
        and execution.get("candidate_publication_blocked_on_failed_test") is True
        and execution.get("closure_pass_requires_execution_receipt") is True
        and isinstance(implementation, Mapping)
        and implementation.get("regression_test_ref")
        == "tests/test_release_closure_candidate.py"
        and SHA256_RE.fullmatch(
            str(implementation.get("regression_test_sha256") or "")
        )
        is not None
    )


def _epoch35_runtime_binding_path_atomicity_is_complete(value: Any) -> bool:
    if not isinstance(value, Mapping):
        return False
    raw_path = value.get("receiver_raw_path_identity_contract")
    parent = value.get("parent_directory_identity_contract")
    publication = value.get("atomic_noreplace_publication_contract")
    receipt = value.get("idempotent_reentry_nofollow_contract")
    execution = value.get("required_regression_execution_contract")
    implementation = value.get("implementation_evidence")
    return (
        value.get("status") == "REQUIRED_IN_REPLACEMENT_CANDIDATE"
        and value.get("active_epochs")
        == {
            "architecture_epoch": 2,
            "control_plane_epoch": 2,
            "requirement_epoch": 35,
        }
        and value.get("closure_receipt_required") is True
        and value.get("closure_receipt_status") == CLOSURE_DECLARATION_STATUS
        and set(value.get("finding_ids") or ()) == set(EPOCH35_REVIEW_FINDING_IDS)
        and tuple(value.get("required_regression_tests") or ())
        == EPOCH35_REQUIRED_REGRESSION_TESTS
        and isinstance(raw_path, Mapping)
        and all(
            raw_path.get(field) is True
            for field in (
                "receiver_argument_preserved_before_resolution",
                "final_component_lstat_nofollow_required",
                "dangling_symlink_rejected",
                "existing_target_symlink_rejected",
            )
        )
        and isinstance(parent, Mapping)
        and all(
            parent.get(field) is True
            for field in (
                "opened_parent_directory_identity_pinned",
                "parent_identity_revalidated_before_publish",
                "publication_uses_pinned_parent_descriptor",
            )
        )
        and isinstance(publication, Mapping)
        and publication.get("destination_noreplace_required") is True
        and publication.get("macos_renameatx_np_rename_excl") is True
        and publication.get("linux_renameat2_rename_noreplace") is True
        and publication.get("unsafe_replace_fallback_allowed") is False
        and publication.get("unsupported_platform_behavior") == "FAIL_CLOSED"
        and isinstance(receipt, Mapping)
        and receipt.get("execution_root_identity_stable_for_reentry") is True
        and receipt.get("receipt_directory_nofollow") is True
        and receipt.get("receipt_file_nofollow") is True
        and receipt.get("receipt_overwrite_allowed") is False
        and isinstance(execution, Mapping)
        and execution.get("factory_validator_executes_exact_hash_bound_tests")
        is True
        and execution.get("candidate_publication_blocked_on_missing_test") is True
        and execution.get("candidate_publication_blocked_on_failed_test") is True
        and execution.get("closure_pass_requires_execution_receipt") is True
        and isinstance(implementation, Mapping)
        and implementation.get("compiler_ref")
        == "src/harness_foundry_factory/compiler.py"
        and implementation.get("factory_validator_ref")
        == "src/harness_foundry_factory/validator.py"
        and implementation.get("regression_test_ref")
        == "tests/test_release_closure_candidate.py"
        and all(
            SHA256_RE.fullmatch(str(implementation.get(field) or "")) is not None
            for field in (
                "compiler_sha256",
                "factory_validator_sha256",
                "regression_test_sha256",
            )
        )
    )


def _validator_command_provider(executable: str) -> str:
    if executable.endswith("/codex"):
        return "codex-cli"
    if executable.endswith("/program-driver"):
        return "program-driver"
    if executable.endswith("/linkage-review"):
        return "linkage-review-cli"
    if executable.endswith("/python") or executable.endswith("/python3"):
        return "python"
    return "UNDECLARED"


def _validator_python_module_provider(module: str) -> str:
    return {
        "unittest": "python",
        "pytest": "pytest",
        "build": "build",
        "linkage_review": "linkage-review-module",
        "external_lab": "external-lab-module",
    }.get(module, "UNDECLARED")


def _candidate_command_dependencies(root: Path) -> list[dict[str, str]]:
    dependencies: list[dict[str, str]] = []
    seen: set[tuple[str, str, str, str]] = set()
    for path in sorted(root.rglob("*.json")):
        try:
            document = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, UnicodeError, json.JSONDecodeError):
            continue
        if not isinstance(document, dict) or not isinstance(
            document.get("commands"), list
        ):
            continue
        relative = path.relative_to(root).as_posix()
        for index, command in enumerate(document["commands"]):
            if not isinstance(command, dict):
                continue
            executable = command.get("executable_abs") or command.get("executable")
            if not isinstance(executable, str) or not executable:
                continue
            command_id = str(command.get("command_id") or f"INDEX-{index}")
            items = [
                ("EXECUTABLE", executable, _validator_command_provider(executable))
            ]
            argv = command.get("argv")
            if (
                isinstance(argv, list)
                and len(argv) >= 3
                and argv[1] == "-m"
                and isinstance(argv[2], str)
            ):
                items.append(
                    (
                        "PYTHON_MODULE",
                        argv[2],
                        _validator_python_module_provider(argv[2]),
                    )
                )
            for kind, dependency_ref, provider in items:
                key = (relative, command_id, kind, dependency_ref)
                if key in seen:
                    continue
                seen.add(key)
                dependencies.append(
                    {
                        "command_file_ref": f"{LOGICAL_CANDIDATE_ROOT}/{relative}",
                        "command_id": command_id,
                        "dependency_kind": kind,
                        "dependency_ref": dependency_ref,
                        "provider_tool_id": provider,
                    }
                )
    return dependencies


def _check_toolchain_manifest(
    root: Path, portability: Mapping[str, Any]
) -> list[dict[str, Any]]:
    findings: list[dict[str, Any]] = []
    toolchain = _read_json(root / "validation/TOOLCHAIN_MANIFEST.json", findings)
    if not isinstance(toolchain, dict):
        return findings
    declared = toolchain.get("required_tools")
    release_declared = portability.get("release_requirements", {}).get(
        "required_tools"
    )
    ids = [
        item.get("tool_id")
        for item in declared or []
        if isinstance(item, dict)
    ]
    expected_dependencies = _candidate_command_dependencies(root)
    frozen = _read_json(
        root / "canonical_sources/FROZEN_REQUIREMENT_IR.json", findings
    )
    frozen_target = frozen.get("target") if isinstance(frozen, Mapping) else None
    frozen_required = (
        frozen_target.get("required_tools", [])
        if isinstance(frozen_target, Mapping)
        else []
    )
    if isinstance(frozen_required, (str, Mapping)):
        frozen_required = [frozen_required]
    frozen_labels = {
        str(item)
        for item in frozen_required
        if isinstance(item, str) and item.strip()
    }
    compiled_labels = {
        str(item.get("requirement_label"))
        for item in declared or []
        if isinstance(item, Mapping) and item.get("requirement_label")
    }
    frozen_ids = {
        str(item.get("tool_id"))
        for item in frozen_required
        if isinstance(item, Mapping) and item.get("tool_id")
    }
    if (
        not isinstance(declared, list)
        or declared != release_declared
        or not ids
        or len(ids) != len(set(ids))
        or any(not isinstance(item, str) or not item for item in ids)
        or toolchain.get("command_dependencies") != expected_dependencies
        or toolchain.get("command_dependency_count") != len(expected_dependencies)
        or not frozen_labels.issubset(compiled_labels)
        or not frozen_ids.issubset(set(ids))
    ):
        findings.append(
            _finding(
                "TOOLCHAIN_MANIFEST_MISMATCH",
                "declared tools must preserve every frozen target requirement and exactly cover the compiled command graph",
            )
        )
        return findings
    undeclared = sorted(
        {
            item["provider_tool_id"]
            for item in expected_dependencies
            if item["provider_tool_id"] not in set(ids)
        }
    )
    if (
        undeclared
        or toolchain.get("undeclared_provider_ids") != []
        or toolchain.get("coverage_status") != "PASS"
    ):
        findings.append(
            _finding(
                "TOOLCHAIN_DEPENDENCY_UNDECLARED",
                ", ".join(undeclared) or "toolchain declares false coverage",
            )
        )
    return findings


def _check_portable_source_index(root: Path) -> list[dict[str, Any]]:
    findings: list[dict[str, Any]] = []
    source_manifest = _read_json(
        root / "canonical_sources/SOURCE_MANIFEST.json", findings
    )
    index = _read_json(
        root / "canonical_sources/PORTABLE_SOURCE_INDEX.json", findings
    )
    if not isinstance(source_manifest, dict) or not isinstance(index, dict):
        return findings
    sources = {
        str(item.get("source_id")): item
        for item in source_manifest.get("sources", [])
        if isinstance(item, dict) and item.get("source_id")
    }
    entries = index.get("sources")
    top_fields = {
        "schema_version",
        "candidate_root",
        "source_count",
        "all_source_references_resolve_in_candidate",
        "all_copy_immutable_snapshots_embedded",
        "sources",
    }
    entry_fields = {
        "source_id",
        "source_sha256",
        "copy_policy",
        "repository_metadata",
        "receipt_ref",
        "receipt_sha256",
        "payload_ref",
        "payload_file_sha256",
        "payload_embedded",
    }
    expected_all_snapshots = all(
        source.get("payload_embedded") is True
        for source in sources.values()
        if source.get("copy_policy") == "COPY_IMMUTABLE_SNAPSHOT"
    )
    if (
        not isinstance(entries, list)
        or set(index) != top_fields
        or index.get("schema_version") != "1.0"
        or index.get("candidate_root") != LOGICAL_CANDIDATE_ROOT
        or index.get("source_count") != len(sources)
        or index.get("all_source_references_resolve_in_candidate") is not True
        or index.get("all_copy_immutable_snapshots_embedded")
        is not expected_all_snapshots
        or len(sources) != len(source_manifest.get("sources", []))
        or len(entries) != len(sources)
        or {item.get("source_id") for item in entries if isinstance(item, dict)}
        != set(sources)
    ):
        findings.append(
            _finding(
                "PORTABLE_SOURCE_INDEX_INVALID",
                "portable source index does not exactly cover SOURCE_MANIFEST",
            )
        )
        return findings
    for entry in entries:
        if not isinstance(entry, dict) or set(entry) != entry_fields:
            findings.append(_finding("PORTABLE_SOURCE_INDEX_INVALID", str(entry)))
            continue
        source_id = str(entry.get("source_id"))
        source = sources[source_id]
        receipt_path = _candidate_uri_path(root, entry.get("receipt_ref"))
        if (
            source.get("path_or_uri") != entry.get("receipt_ref")
            or source.get("portable_evidence_ref") != entry.get("receipt_ref")
            or source.get("sha256") != entry.get("source_sha256")
            or source.get("copy_policy") != entry.get("copy_policy")
            or entry.get("repository_metadata")
            != (
                {
                    field: source[field]
                    for field in (
                        "repository_url",
                        "revision",
                        "commit_sha",
                        "git_tree_oid",
                        "tree_sha256",
                        "license_spdx",
                        "license_ref",
                        "retrieved_at",
                    )
                    if source.get(field) not in (None, "")
                }
                or None
            )
            or receipt_path is None
            or not receipt_path.is_file()
            or _file_hash(receipt_path) != entry.get("receipt_sha256")
        ):
            findings.append(
                _finding("PORTABLE_SOURCE_RECEIPT_INVALID", source_id)
            )
            continue
        receipt = _read_json(receipt_path, findings)
        if (
            not isinstance(receipt, dict)
            or receipt.get("source_id") != source_id
            or receipt.get("source_sha256") != source.get("sha256")
            or receipt.get("copy_policy") != source.get("copy_policy")
            or receipt.get("repository_metadata")
            != entry.get("repository_metadata")
            or receipt.get("payload_embedded") is not entry.get("payload_embedded")
            or receipt.get("payload_ref") != entry.get("payload_ref")
        ):
            findings.append(
                _finding("PORTABLE_SOURCE_RECEIPT_INVALID", source_id)
            )
            continue
        if entry.get("payload_embedded") is True:
            payload_path = _candidate_uri_path(root, entry.get("payload_ref"))
            try:
                encoded = payload_path.read_text(encoding="ascii").strip()
                payload = base64.b64decode(encoded, validate=True)
            except (AttributeError, OSError, UnicodeError, ValueError):
                findings.append(
                    _finding("PORTABLE_SOURCE_PAYLOAD_INVALID", source_id)
                )
                continue
            if (
                payload_path is None
                or not payload_path.is_file()
                or _file_hash(payload_path) != entry.get("payload_file_sha256")
                or hashlib.sha256(payload).hexdigest() != source.get("sha256")
                or source.get("snapshot_path") != entry.get("payload_ref")
            ):
                findings.append(
                    _finding("PORTABLE_SOURCE_PAYLOAD_INVALID", source_id)
                )
        elif source.get("copy_policy") == "COPY_IMMUTABLE_SNAPSHOT":
            findings.append(
                _finding("PORTABLE_SOURCE_PAYLOAD_MISSING", source_id)
            )
        elif (
            entry.get("payload_ref") is not None
            or entry.get("payload_file_sha256") is not None
            or source.get("snapshot_path") != entry.get("receipt_ref")
        ):
            findings.append(
                _finding("PORTABLE_SOURCE_PAYLOAD_INVALID", source_id)
            )
    return findings


def _check_factory_implementation_provenance(
    root: Path, provenance: Mapping[str, Any]
) -> list[dict[str, Any]]:
    findings: list[dict[str, Any]] = []
    manifest_path = root / "FACTORY_IMPLEMENTATION_MANIFEST.json"
    manifest = _read_json(manifest_path, findings)
    if not isinstance(manifest, dict):
        return findings
    files = manifest.get("files")
    if not isinstance(files, dict) or not files:
        return [
            _finding(
                "FACTORY_IMPLEMENTATION_MANIFEST_INVALID",
                "selected implementation file hashes are missing",
            )
        ]
    invalid_entry = any(
        not isinstance(relative, str)
        or Path(relative).is_absolute()
        or ".." in Path(relative).parts
        or not isinstance(digest, str)
        or not SHA256_RE.fullmatch(digest)
        or len(set(digest)) == 1
        for relative, digest in files.items()
    )
    if (
        invalid_entry
        or manifest.get("factory_id") != FACTORY_ID
        or manifest.get("baseline_factory_id") != BASELINE_FACTORY_ID
        or manifest.get("implementation_tree_sha256") != _json_hash(files)
        or provenance.get("factory_implementation_manifest_ref")
        != "FACTORY_IMPLEMENTATION_MANIFEST.json"
        or provenance.get("factory_implementation_manifest_sha256")
        != _file_hash(manifest_path)
        or provenance.get("factory_implementation_tree_sha256")
        != manifest.get("implementation_tree_sha256")
        or provenance.get("compiler_implementation_sha256")
        != files.get("src/harness_foundry_factory/compiler.py")
        or provenance.get("validator_implementation_sha256")
        != files.get("src/harness_foundry_factory/validator.py")
        or provenance.get("semantic_contracts_implementation_sha256")
        != files.get("src/harness_foundry_factory/semantic_contracts.py")
    ):
        findings.append(
            _finding(
                "FACTORY_IMPLEMENTATION_PROVENANCE_MISMATCH",
                "Factory provenance does not close over the selected implementation tree",
            )
        )
    return findings


def _expected_dag_path_containment_matrix(
    dag_path: Path,
    dag: Mapping[str, Any],
) -> dict[str, Any]:
    root = dag_path.parent
    workpack_artifact_refs_by_node: dict[str, list[str]] = {}
    for _project_id, directory in PROJECTS:
        index_path = (
            root
            / "project_start_packages"
            / directory
            / "WORKPACK_INDEX.json"
        )
        try:
            index = json.loads(index_path.read_text(encoding="utf-8"))
        except (OSError, UnicodeError, json.JSONDecodeError):
            continue
        for raw_workpack in index.get("workpacks", []):
            workpack = raw_workpack if isinstance(raw_workpack, Mapping) else {}
            if workpack.get("program_control_surface") != "ENGINEERING_PROJECT_DAG":
                continue
            node_id = str(workpack.get("program_control_node_id") or "")
            if not node_id:
                continue
            refs = workpack_artifact_refs_by_node.setdefault(node_id, [])
            for artifact_ref in workpack.get("required_artifact_refs", []):
                if isinstance(artifact_ref, str) and artifact_ref not in refs:
                    refs.append(artifact_ref)
    rows: list[dict[str, Any]] = []
    for raw_node in dag.get("nodes", []):
        node = raw_node if isinstance(raw_node, Mapping) else {}
        node_id = str(node.get("node_id") or "")
        allowed = list(node.get("allowed_write_paths") or [])
        outputs = list(node.get("success_output_refs") or [])
        workpack_artifact_refs = workpack_artifact_refs_by_node.get(
            node_id, []
        )
        contained = [
            output
            for output in outputs
            if any(_contract_path_is_contained(output, root) for root in allowed)
        ]
        outside = [output for output in outputs if output not in contained]
        contained_workpack_artifact_refs = [
            artifact_ref
            for artifact_ref in workpack_artifact_refs
            if any(
                _contract_path_is_contained(artifact_ref, allowed_root)
                for allowed_root in allowed
            )
        ]
        outside_workpack_artifact_refs = [
            artifact_ref
            for artifact_ref in workpack_artifact_refs
            if artifact_ref not in contained_workpack_artifact_refs
        ]
        rows.append(
            {
                "node_id": node.get("node_id"),
                "allowed_write_paths": allowed,
                "success_output_refs": outputs,
                "contained_success_output_refs": contained,
                "outside_success_output_refs": outside,
                "workpack_artifact_refs": workpack_artifact_refs,
                "contained_workpack_artifact_refs": (
                    contained_workpack_artifact_refs
                ),
                "outside_workpack_artifact_refs": (
                    outside_workpack_artifact_refs
                ),
                "status": "PASS"
                if (
                    outputs
                    and len(contained) == len(outputs)
                    and not outside_workpack_artifact_refs
                )
                else "FAIL",
            }
        )
    pass_count = sum(row["status"] == "PASS" for row in rows)
    return {
        "schema_version": "1.0",
        "matrix_id": "DAG_PATH_CONTAINMENT_MATRIX",
        "dag_ref": "ENGINEERING_PROJECT_DAG.json",
        "dag_sha256": _file_hash(dag_path),
        "containment_contract": (
            "STRICT_RESOLVED_RESOURCE_IDENTITY_CONTAINMENT_NOT_STRING_PREFIX"
        ),
        "finding_code": (
            "ENGINEERING_DAG_SUCCESS_OUTPUT_OUTSIDE_ALLOWED_WRITE_PATHS"
        ),
        "workpack_artifact_finding_code": (
            "ENGINEERING_DAG_WORKPACK_ARTIFACT_OUTSIDE_ALLOWED_WRITE_PATHS"
        ),
        "node_count": len(rows),
        "pass_count": pass_count,
        "rows": rows,
        "status": "PASS" if rows and pass_count == len(rows) else "FAIL",
    }


def _expected_epoch_domain_contract(
    target: Mapping[str, Any],
) -> dict[str, Any]:
    architecture_epoch = target.get("architecture_epoch")
    architecture_control_plane_epoch = target.get("control_plane_epoch")
    requirement_architecture_epoch = architecture_epoch
    requirement_architecture_control_plane_epoch = (
        architecture_control_plane_epoch
    )
    unbound_zero_semantics = (
        architecture_epoch is None
        and architecture_control_plane_epoch is None
    )
    if architecture_epoch is None and architecture_control_plane_epoch is None:
        architecture_epoch = 0
        architecture_control_plane_epoch = 0
    return {
        "schema_version": "1.0",
        "architecture_epoch": architecture_epoch,
        "architecture_control_plane_epoch": (
            architecture_control_plane_epoch
        ),
        "execution_control_plane_epoch": 0,
        "legacy_control_plane_epoch_alias": "execution_control_plane_epoch",
        "requirement_architecture_epoch": requirement_architecture_epoch,
        "requirement_architecture_control_plane_epoch": (
            requirement_architecture_control_plane_epoch
        ),
        "projection_rule": (
            "NULL_REQUIREMENT_EPOCHS_TO_EXPLICIT_UNBOUND_ZERO_SENTINEL"
            if unbound_zero_semantics
            else "IDENTITY_REQUIREMENT_EPOCH_PROJECTION"
        ),
        "unbound_zero_semantics": unbound_zero_semantics,
    }


def _check_shared_control_baseline_executable_contract(
    root: Path,
) -> list[dict[str, Any]]:
    """Validate the portable v0.9 producer contract without executing it."""

    findings: list[dict[str, Any]] = []
    frozen = _read_json(
        root / "canonical_sources/FROZEN_REQUIREMENT_IR.json", findings
    )
    if not isinstance(frozen, dict):
        return findings
    target = frozen.get("target")
    if isinstance(target, Mapping) and target.get(
        "shared_control_baseline_fixture_role"
    ) == "HISTORICAL_GOLDEN_FIXTURE_ONLY_NO_SUCCESSOR_AUTHORITY":
        return findings
    execution_contract = (
        target.get("shared_control_baseline_execution_contract")
        if isinstance(target, Mapping)
        else None
    )
    if execution_contract is None:
        dag = _read_json(root / "ENGINEERING_PROJECT_DAG.json", findings)
        if not isinstance(dag, Mapping) or not any(
            node.get("node_id") == "SHARED_CONTROL_BASELINE_LOCK" for node in dag.get("nodes", [])
        ):
            return findings
        execution_contract = shared_control_default()["execution_contract"]
    if not isinstance(execution_contract, Mapping):
        return [*findings, _finding("SHARED_CONTROL_BASELINE_CONTRACT_INVALID", "execution contract must be an object")]
    expected_refs = {
        "implementation_ref": "tools/shared_control_baseline.py",
        "result_schema_ref": "contracts/SHARED_CONTROL_BASELINE_RESULT.schema.json",
        "action_contract_ref": "validation/SHARED_CONTROL_BASELINE_ACTION_CONTRACT.json",
    }
    if any(execution_contract.get(key) != value for key, value in expected_refs.items()):
        findings.append(
            _finding(
                "SHARED_CONTROL_BASELINE_CONTRACT_INVALID",
                "frozen portable artifact refs are not canonical",
            )
        )
        return findings
    implementation_path = root / expected_refs["implementation_ref"]
    schema_path = root / expected_refs["result_schema_ref"]
    contract_path = root / expected_refs["action_contract_ref"]
    for path in (implementation_path, schema_path, contract_path):
        if not path.is_file():
            findings.append(
                _finding(
                    "SHARED_CONTROL_BASELINE_EXECUTABLE_ARTIFACT_MISSING",
                    path.relative_to(root).as_posix(),
                )
            )
    if findings:
        return findings
    action_contract = _read_json(contract_path, findings)
    schema = _read_json(schema_path, findings)
    if not isinstance(action_contract, dict) or not isinstance(schema, dict):
        return findings
    required_result_fields = list(
        execution_contract.get("required_result_fields") or []
    )
    command_fields = action_contract.get("runtime_input_contract", {}).get(
        "command_manifest_required_fields"
    )
    authorization_fields = action_contract.get(
        "runtime_input_contract", {}
    ).get("authorization_required_fields")
    critical_command_fields = {
        "executor_implementation_sha256",
        "action_contract_sha256",
        "result_schema_sha256",
        "idempotency_key",
        "lease_id",
        "fencing_token",
        "expected_control_state_sha256",
    }
    critical_authorization_fields = {
        "command_manifest_sha256",
        "executor_implementation_sha256",
        "idempotency_key",
        "lease_id",
        "fencing_token",
        "expected_control_state_sha256",
        "not_before",
        "expires_at",
    }
    schema_properties = schema.get("properties")
    if (
        action_contract.get("contract_id")
        != execution_contract.get("contract_id")
        or action_contract.get("action_id")
        != execution_contract.get("action_id")
        or action_contract.get("node_id") != execution_contract.get("node_id")
        or action_contract.get("implementation_ref")
        != expected_refs["implementation_ref"]
        or action_contract.get("executor_implementation_sha256")
        != _file_hash(implementation_path)
        or action_contract.get("result_schema_ref")
        != expected_refs["result_schema_ref"]
        or action_contract.get("result_schema_sha256") != _file_hash(schema_path)
        or action_contract.get("execution_contract") != execution_contract
        or action_contract.get("contract_sha256")
        != _hash_without_field(action_contract, "contract_sha256")
        or not isinstance(command_fields, list)
        or not critical_command_fields.issubset(set(command_fields or []))
        or not isinstance(authorization_fields, list)
        or not critical_authorization_fields.issubset(
            set(authorization_fields or [])
        )
    ):
        findings.append(
            _finding(
                "SHARED_CONTROL_BASELINE_CONTRACT_INVALID",
                "action identity, executable hash, or runtime binding is invalid",
            )
        )
    if (
        schema.get("type") != "object"
        or schema.get("additionalProperties") is not False
        or schema.get("required") != required_result_fields
        or not isinstance(schema_properties, Mapping)
        or set(schema_properties or {}) != set(required_result_fields)
        or any(
            not isinstance(schema_properties.get(field), Mapping)
            for field in required_result_fields
        )
    ):
        findings.append(
            _finding(
                "SHARED_CONTROL_BASELINE_RESULT_SCHEMA_INVALID",
                "result schema does not exactly close over required_result_fields",
            )
        )
    try:
        tree = ast.parse(implementation_path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, SyntaxError) as exc:
        findings.append(
            _finding("SHARED_CONTROL_BASELINE_IMPLEMENTATION_INVALID", str(exc))
        )
        tree = None
    if tree is not None:
        function_names = {
            node.name for node in ast.walk(tree) if isinstance(node, ast.FunctionDef)
        }
        class_names = {
            node.name for node in ast.walk(tree) if isinstance(node, ast.ClassDef)
        }
        if not {
            "execute_action",
            "validate_static_contract",
            "validate_result_document",
            "atomic_json",
            "append_event",
        }.issubset(function_names) or not {
            "ContractError",
            "InjectedCrash",
        }.issubset(class_names):
            findings.append(
                _finding(
                    "SHARED_CONTROL_BASELINE_IMPLEMENTATION_INVALID",
                    "production, validation, atomic persistence, or crash boundary is missing",
                )
            )

    dag = _read_json(root / "ENGINEERING_PROJECT_DAG.json", findings)
    manifest = _read_json(root / "THREE_PROJECT_PROGRAM_MANIFEST.json", findings)
    if isinstance(dag, dict):
        node = next(
            (
                item
                for item in dag.get("nodes", [])
                if isinstance(item, Mapping)
                and item.get("node_id") == "SHARED_CONTROL_BASELINE_LOCK"
            ),
            None,
        )
        if (
            not isinstance(node, Mapping)
            or node.get("action_contract_sha256") != _file_hash(contract_path)
            or node.get("executor_implementation_sha256")
            != _file_hash(implementation_path)
            or node.get("result_schema_sha256") != _file_hash(schema_path)
            or node.get("transaction_protocol")
            != "JOURNALED_ATOMIC_RECONCILIATION_V1"
        ):
            findings.append(
                _finding(
                    "SHARED_CONTROL_BASELINE_DAG_BINDING_INVALID",
                    "DAG node does not bind the executable contract and result schema",
                )
            )
    if isinstance(manifest, dict):
        baseline = manifest.get("shared_control_baseline")
        epoch_domains = manifest.get("epoch_domains")
        expected_epoch_domains = (
            _expected_epoch_domain_contract(target)
            if isinstance(target, Mapping)
            else None
        )
        epoch_domain_binding_valid = (
            isinstance(epoch_domains, Mapping)
            and epoch_domains == expected_epoch_domains
            and manifest.get("control_plane_epoch")
            == epoch_domains.get("execution_control_plane_epoch")
            and action_contract.get("epoch_domain_contract")
            == expected_epoch_domains
        )
        if (
            not isinstance(baseline, Mapping)
            or baseline.get("action_contract_sha256") != _file_hash(contract_path)
            or baseline.get("executor_implementation_sha256")
            != _file_hash(implementation_path)
            or baseline.get("result_schema_sha256") != _file_hash(schema_path)
            or baseline.get("runtime_status") != "NOT_EXECUTED"
            or not epoch_domain_binding_valid
        ):
            findings.append(
                _finding(
                    "SHARED_CONTROL_BASELINE_MANIFEST_BINDING_INVALID",
                    "program manifest does not bind the executable contract",
                )
            )

    portable_manifest = _read_json(
        root / "validation/PORTABLE_FILE_MANIFEST.json", findings
    )
    if isinstance(portable_manifest, dict):
        files = portable_manifest.get("files")
        if (
            not isinstance(files, Mapping)
            or files.get(expected_refs["implementation_ref"])
            != _file_hash(implementation_path)
            or files.get(expected_refs["result_schema_ref"])
            != _file_hash(schema_path)
            or files.get(expected_refs["action_contract_ref"])
            != _file_hash(contract_path)
        ):
            findings.append(
                _finding(
                    "SHARED_CONTROL_BASELINE_PORTABLE_BINDING_INVALID",
                    "portable manifest does not bind all executable artifacts",
                )
            )
    closure_receipt = _read_json(
        root / "validation/HUMAN_REVIEW_CLOSURE_RECEIPT.json", findings
    )
    if isinstance(closure_receipt, dict) and isinstance(target, Mapping) and isinstance(
        target.get("human_review_v0_8_closure"), Mapping
    ):
        closure = next(
            (
                item
                for item in closure_receipt.get("closures", [])
                if isinstance(item, Mapping)
                and item.get("requirement_key") == "human_review_v0_8_closure"
            ),
            None,
        )
        required_evidence = set(expected_refs.values())
        if not isinstance(closure, Mapping) or not required_evidence.issubset(
            set(closure.get("evidence_refs") or [])
        ):
            findings.append(
                _finding(
                    "SHARED_CONTROL_BASELINE_CLOSURE_EVIDENCE_INVALID",
                    "v0.8 closure does not hash-bind contract, schema, and implementation",
                )
            )
    return findings


def _control_startup_profile_ref(root: Path, findings: list[dict[str, Any]]) -> str | None:
    legacy_ref = "EPOCH38_GENERATION_PROFILE.json"
    if (root / legacy_ref).is_file():
        return legacy_ref
    frozen = _read_json(root / "canonical_sources/FROZEN_REQUIREMENT_IR.json", findings)
    if not isinstance(frozen, Mapping):
        return None
    target = frozen.get("target", {})
    applicable = (
        target.get("architecture_epoch") in (None, 0)
        and target.get("control_plane_epoch") in (None, 0)
        and assurance_profile_for_start_package(frozen).profile_id == LOCAL_EXEC_UNTRUSTED_INPUT
    )
    ref = "validation/CONTROL_STARTUP_PROFILE.json"
    if not applicable:
        if (root / ref).exists():
            findings.append(_finding("CONTROL_STARTUP_PROFILE_INVALID", "local startup profile does not match frozen Requirement"))
        return None
    profile = _read_json(root / ref, findings)
    if profile != {
        "schema_version": "1.0",
        "start_package_assurance_profile": LOCAL_EXEC_UNTRUSTED_INPUT,
        "assurance_profile": "SELF_USE_LOCAL_TRUSTED_OPERATOR",
        "profile_source": "FROZEN_REQUIREMENT_ASSURANCE_RESOLUTION",
        "sqlite_controller_contract": {
            "mode": "START_PACKAGE_SQLITE_REGISTRATION",
            "authority_ref": "harness-resource://execution/.harness-foundry/control.sqlite3",
            "preparation_entrypoint": "prepare_action",
            "proposal_is_commit": False,
            "transaction_journal": "SQLITE_CONTROL_EVENTS",
            "legacy_transaction_protocol": "NOT_EXECUTED_BY_SQLITE_ROUTE",
            "compatibility_files_authoritative": False,
            "legacy_writer_when_sqlite_present": "REJECT",
            "driver_start_allowed": False,
            "workpack_execution_allowed": False,
        },
        "execution_authorized": False,
    }:
        findings.append(_finding("CONTROL_STARTUP_PROFILE_INVALID", "local startup profile is missing or differs from frozen Requirement"))
    for module in ("shared_control_baseline", "control_plane_registration", "program_driver_runtime_verification"):
        path = root / "tools" / (module + ".py")
        try:
            functions = {node.name for node in ast.parse(path.read_text(encoding="utf-8")).body if isinstance(node, ast.FunctionDef)}
        except (OSError, SyntaxError, UnicodeError):
            functions = set()
        if "prepare_action" not in functions:
            findings.append(_finding("CONTROL_ACTION_PREPARATION_MISSING", f"{module} lacks its read-only controller preparation API"))
    return ref


def _check_control_plane_registration_executable_closure(
    root: Path,
) -> list[dict[str, Any]]:
    """Require the declared local registration provider, including normal authoring."""

    findings: list[dict[str, Any]] = []
    profile_ref = _control_startup_profile_ref(root, findings)
    if profile_ref is None:
        return findings
    refs = {
        "implementation": "tools/control_plane_registration.py",
        "contract": "validation/CONTROL_PLANE_REGISTRATION_ACTION_CONTRACT.json",
        "schema": "contracts/CONTROL_PLANE_REGISTRATION_RESULT.schema.json",
    }
    paths = {name: root / ref for name, ref in refs.items()}
    runtime_refs = [
        "tools/harness_foundry_runtime/control_kernel.py",
        "tools/harness_foundry_runtime/local_runtime.py",
        "tools/harness_foundry_runtime/local_process.py",
        "tools/harness_foundry_runtime/startup_runtime.py",
        "tools/harness_foundry_runtime/store.py",
        "tools/harness_foundry_runtime/models.py",
        "tools/harness_foundry_runtime/constants.py",
    ]
    missing = [
        ref
        for ref, path in [
            *[(refs[name], path) for name, path in paths.items()],
            *[(ref, root / ref) for ref in runtime_refs],
        ]
        if not path.is_file()
    ]
    if missing:
        return [
            _finding(
                "CONTROL_PLANE_REGISTRATION_EXECUTABLE_ARTIFACT_MISSING",
                ", ".join(sorted(missing)),
            )
        ]
    contract = _read_json(paths["contract"], findings)
    schema = _read_json(paths["schema"], findings)
    if not isinstance(contract, dict) or not isinstance(schema, dict):
        return findings
    if contract.get("generation_profile_ref", "EPOCH38_GENERATION_PROFILE.json") != profile_ref:
        findings.append(_finding("CONTROL_PLANE_REGISTRATION_CONTRACT_INVALID", "profile source binding differs"))
    module_hashes = {ref: _file_hash(root / ref) for ref in runtime_refs}
    execution = contract.get("execution_contract")
    runtime_inputs = contract.get("runtime_input_contract")
    critical_command_fields = {
        "executor_implementation_sha256",
        "action_contract_sha256",
        "result_schema_sha256",
        "shared_control_baseline_result_sha256",
        "control_runtime_bundle_sha256",
        "expected_control_state_sha256",
        "idempotency_key",
        "lease_id",
        "fencing_token",
    }
    required_authorization_fields = {
        "schema_version",
        "authorization_id",
        "authorization_class",
        "status",
        "one_shot",
        "program_id",
        "issuer_role",
        "issued_at",
        "node_id",
        "allowed_action_id",
        "scope",
        "command_manifest_hashes",
        "command_manifest_sha256",
        "candidate_tree_sha256",
        "requirement_ir_sha256",
        "executor_implementation_sha256",
        "human_approval_receipt_sha256",
        "shared_control_baseline_result_sha256",
        "control_runtime_bundle_sha256",
        "expected_control_state_sha256",
        "idempotency_key",
        "lease_id",
        "fencing_token",
        "max_transitions",
        "delegation_allowed",
        "signature_policy",
        "signature",
        "not_before",
        "expires_at",
    }
    runtime_internal_write_refs = [
        "harness-resource://execution/.harness-foundry/control/PROGRAM_CONTROL_STATE.json",
        "harness-resource://execution/.harness-foundry/control/PROGRAM_CONTROL_EVENTS.jsonl",
        (
            "harness-resource://execution/.harness-foundry/control/transactions/"
            "CONTROL_PLANE_REGISTRATION.transaction.json"
        ),
        (
            "harness-resource://execution/.harness-foundry/control/leases/"
            "CONTROL_PLANE_REGISTRATION.lease.json"
        ),
        "harness-resource://execution/evidence/engineering_dag/CONTROL_PLANE_REGISTRATION/result.json",
        (
            "harness-resource://execution/evidence/engineering_dag/"
            "CONTROL_PLANE_REGISTRATION/recovery_receipt.json"
        ),
    ]
    authorization_profile = contract.get("authorization_profile")
    scope_contract = (
        authorization_profile.get("scope_contract")
        if isinstance(authorization_profile, Mapping)
        else None
    )
    persistence = contract.get("persistence_contract")
    persistence_refs = (
        {
            value
            for key, value in persistence.items()
            if str(key).endswith("_ref") and isinstance(value, str)
        }
        if isinstance(persistence, Mapping)
        else set()
    )
    manifest = _read_json(
        root / "THREE_PROJECT_PROGRAM_MANIFEST.json", findings
    )
    epoch_domains = (
        manifest.get("epoch_domains")
        if isinstance(manifest, Mapping)
        else None
    )
    if (
        contract.get("action_id")
        != "REGISTER-CONTROL-PLANE-EXECUTABLE-CLOSURE"
        or contract.get("node_id") != "CONTROL_PLANE_REGISTRATION"
        or contract.get("action_kind") != "REGISTRATION_ONLY"
        or contract.get("implementation_ref") != refs["implementation"]
        or contract.get("executor_implementation_sha256")
        != _file_hash(paths["implementation"])
        or contract.get("result_schema_ref") != refs["schema"]
        or contract.get("result_schema_sha256") != _file_hash(paths["schema"])
        or contract.get("runtime_module_refs") != runtime_refs
        or contract.get("runtime_module_sha256s") != module_hashes
        or contract.get("runtime_bundle_sha256") != _json_hash(module_hashes)
        or contract.get("contract_sha256")
        != _hash_without_field(contract, "contract_sha256")
        or not isinstance(execution, Mapping)
        or execution.get("required_predecessor_node_id")
        != "SHARED_CONTROL_BASELINE_LOCK"
        or execution.get("successor_node_id")
        != "PROGRAM_DRIVER_RUNTIME_VERIFIED"
        or execution.get("driver_start_allowed") is not False
        or execution.get("workpack_start_allowed") is not False
        or execution.get("automatic_successor_advance_allowed") is not False
        or execution.get("transaction_protocol")
        != "JOURNALED_ATOMIC_RECONCILIATION_V1"
        or not isinstance(runtime_inputs, Mapping)
        or not critical_command_fields.issubset(
            set(runtime_inputs.get("command_manifest_required_fields") or [])
        )
        or set(runtime_inputs.get("authorization_required_fields") or [])
        != required_authorization_fields
        or not isinstance(authorization_profile, Mapping)
        or authorization_profile.get("assurance_profile")
        != "SELF_USE_LOCAL_TRUSTED_OPERATOR"
        or authorization_profile.get("issuer_role") != "LOCAL_TRUSTED_OPERATOR"
        or authorization_profile.get("max_transitions") != 1
        or authorization_profile.get("delegation_allowed") is not False
        or authorization_profile.get("signature_policy")
        != "NOT_APPLICABLE_SELF_USE_LOCAL_TRUSTED_OPERATOR"
        or authorization_profile.get("signature_value") is not None
        or authorization_profile.get(
            "external_cryptographic_signature_required"
        )
        is not False
        or set(authorization_profile.get("required_fields") or [])
        != required_authorization_fields
        or not isinstance(scope_contract, Mapping)
        or scope_contract.get("runtime_internal_write_refs")
        != runtime_internal_write_refs
        or contract.get("runtime_internal_write_refs")
        != runtime_internal_write_refs
        or persistence_refs != set(runtime_internal_write_refs)
    ):
        findings.append(
            _finding(
                "CONTROL_PLANE_REGISTRATION_CONTRACT_INVALID",
                "executable, runtime bundle, predecessor, or one-shot binding is invalid",
            )
        )

    required = execution.get("required_result_fields") if isinstance(execution, Mapping) else None
    properties = schema.get("properties")
    if (
        not isinstance(required, list)
        or schema.get("type") != "object"
        or schema.get("additionalProperties") is not False
        or schema.get("required") != required
        or not isinstance(properties, Mapping)
        or set(properties) != set(required)
        or properties.get("driver_started", {}).get("const") is not False
        or properties.get("workpack_started", {}).get("const") is not False
    ):
        findings.append(
            _finding(
                "CONTROL_PLANE_REGISTRATION_RESULT_SCHEMA_INVALID",
                "result schema is not exact or permits a Driver/Workpack start claim",
            )
        )

    try:
        tree = ast.parse(paths["implementation"].read_text(encoding="utf-8"))
    except (OSError, UnicodeError, SyntaxError) as exc:
        findings.append(
            _finding("CONTROL_PLANE_REGISTRATION_IMPLEMENTATION_INVALID", str(exc))
        )
        tree = None
    if tree is not None:
        functions = {
            node.name for node in ast.walk(tree) if isinstance(node, ast.FunctionDef)
        }
        if not {
            "execute_action",
            "validate_static_contract",
            "validate_result_document",
            "_validate_runtime_inputs",
            "_commit_transaction",
        }.issubset(functions):
            findings.append(
                _finding(
                    "CONTROL_PLANE_REGISTRATION_IMPLEMENTATION_INVALID",
                    "real validation, transaction, event, or state-CAS implementation is missing",
                )
            )

    dag = _read_json(root / "ENGINEERING_PROJECT_DAG.json", findings)
    manifest = _read_json(root / "THREE_PROJECT_PROGRAM_MANIFEST.json", findings)
    driver = _read_json(root / "PROGRAM_DRIVER_CONTRACT.json", findings)
    policy = _read_json(root / "AUTHORIZATION_POLICY.json", findings)
    if isinstance(dag, dict):
        node = next(
            (
                item
                for item in dag.get("nodes", [])
                if isinstance(item, Mapping)
                and item.get("node_id") == "CONTROL_PLANE_REGISTRATION"
            ),
            None,
        )
        if (
            not isinstance(node, Mapping)
            or node.get("action_contract_sha256") != _file_hash(paths["contract"])
            or node.get("executor_implementation_sha256")
            != _file_hash(paths["implementation"])
            or node.get("result_schema_sha256") != _file_hash(paths["schema"])
            or node.get("runtime_bundle_sha256") != _json_hash(module_hashes)
            or node.get("transaction_protocol")
            != "JOURNALED_ATOMIC_RECONCILIATION_V1"
            or node.get("runtime_internal_write_refs")
            != runtime_internal_write_refs
        ):
            findings.append(
                _finding(
                    "CONTROL_PLANE_REGISTRATION_DAG_BINDING_INVALID",
                    "DAG node does not bind the executable closure",
                )
            )
    if isinstance(manifest, dict):
        registration = manifest.get("control_plane_registration")
        epoch_domains = manifest.get("epoch_domains")
        frozen = _read_json(
            root / "canonical_sources/FROZEN_REQUIREMENT_IR.json", findings
        )
        target = frozen.get("target") if isinstance(frozen, Mapping) else None
        expected_epoch_domains = (
            _expected_epoch_domain_contract(target)
            if isinstance(target, Mapping)
            else None
        )
        epoch_domain_binding_valid = (
            isinstance(epoch_domains, Mapping)
            and epoch_domains == expected_epoch_domains
            and manifest.get("control_plane_epoch")
            == epoch_domains.get("execution_control_plane_epoch")
            and contract.get("epoch_domain_contract")
            == expected_epoch_domains
        )
        if (
            not isinstance(registration, Mapping)
            or registration.get("action_contract_sha256")
            != _file_hash(paths["contract"])
            or registration.get("executor_implementation_sha256")
            != _file_hash(paths["implementation"])
            or registration.get("runtime_module_sha256s") != module_hashes
            or registration.get("runtime_bundle_sha256") != _json_hash(module_hashes)
            or registration.get("runtime_status") != "NOT_EXECUTED"
            or registration.get("driver_started") is not False
            or registration.get("workpack_started") is not False
            or not epoch_domain_binding_valid
        ):
            findings.append(
                _finding(
                    "CONTROL_PLANE_REGISTRATION_MANIFEST_BINDING_INVALID",
                    "program manifest does not bind the unexecuted closure",
                )
            )
    if isinstance(driver, dict):
        action = driver.get("registration_control_actions", {}).get(
            "CONTROL_PLANE_REGISTRATION"
        )
        if (
            not isinstance(action, Mapping)
            or action.get("action_contract_ref") != refs["contract"]
            or action.get("executor_implementation_ref") != refs["implementation"]
            or action.get("required_execution_mode") != "REGISTRATION_ONLY"
            or action.get("automatic_successor_advance_allowed") is not False
            or action.get("driver_start_allowed") is not False
            or action.get("workpack_start_allowed") is not False
        ):
            findings.append(
                _finding(
                    "CONTROL_PLANE_REGISTRATION_DRIVER_BINDING_INVALID",
                    "Program Driver contract does not expose the bounded registration action",
                )
            )
    if isinstance(policy, dict):
        token_fields = set(policy.get("required_token_fields") or [])
        rules = policy.get("validation_rules")
        profile_schemas = policy.get("profile_authorization_schemas")
        profile_authorizations = (
            profile_schemas.get("SELF_USE_LOCAL_TRUSTED_OPERATOR")
            if isinstance(profile_schemas, Mapping)
            else None
        )
        profile_schema = (
            profile_authorizations.get("REGISTRATION_AUTHORIZATION")
            if isinstance(profile_authorizations, Mapping)
            else None
        )
        if (
            not required_authorization_fields.issubset(token_fields)
            or profile_schema != authorization_profile
            or not isinstance(rules, Mapping)
            or any(
                rules.get(field) is not True
                for field in (
                    "registration_predecessor_hash_required",
                    "control_runtime_bundle_hash_required",
                    "registration_state_cas_required",
                    "registration_event_tip_required",
                    "registration_one_shot_idempotency_fencing_required",
                    "registration_profile_schema_exact_match_required",
                    "registration_runtime_internal_write_containment_required",
                )
            )
        ):
            findings.append(
                _finding(
                    "CONTROL_PLANE_REGISTRATION_AUTHORIZATION_POLICY_INVALID",
                    "authorization policy does not require the full registration binding",
                )
            )
    negatives = _read_json(root / "validation/NEGATIVE_CASES.json", findings)
    if isinstance(negatives, dict) and profile_ref == "EPOCH38_GENERATION_PROFILE.json":
        registration_cases = {
            str(case.get("case_id")): case
            for case in negatives.get("cases", [])
            if isinstance(case, Mapping)
            and str(case.get("case_id", "")).startswith("NEG-V29-E41-REGISTRATION-")
        }
        expected_case_ids = {
            "NEG-V29-E41-REGISTRATION-AUTHORITY-SCOPE",
            "NEG-V29-E41-REGISTRATION-HUMAN-SIGNATURE-PROFILE",
            "NEG-V29-E41-REGISTRATION-INTERNAL-WRITE-CONTAINMENT",
        }
        if (
            set(registration_cases) != expected_case_ids
            or any(
                case.get("fixture_kind") != "NON_EXECUTABLE_JSON"
                or not isinstance(case.get("input_fixture"), Mapping)
                for case in registration_cases.values()
            )
        ):
            findings.append(
                _finding(
                    "CONTROL_PLANE_REGISTRATION_NEGATIVE_FIXTURE_INVALID",
                    "profile authorization or write-containment JSON fixtures are incomplete",
                )
            )
    portable = _read_json(root / "validation/PORTABLE_FILE_MANIFEST.json", findings)
    if isinstance(portable, dict):
        files = portable.get("files")
        required_files = {
            **{ref: _file_hash(root / ref) for ref in refs.values()},
            **module_hashes,
        }
        if not isinstance(files, Mapping) or any(
            files.get(ref) != sha256 for ref, sha256 in required_files.items()
        ):
            findings.append(
                _finding(
                    "CONTROL_PLANE_REGISTRATION_PORTABLE_BINDING_INVALID",
                    "portable inventory does not bind the complete executable closure",
                )
            )
    return findings


def _check_program_driver_runtime_verification_executable_closure(
    root: Path,
) -> list[dict[str, Any]]:
    """Require a portable, local-profile, read-only Driver verifier."""

    findings: list[dict[str, Any]] = []
    profile_ref = _control_startup_profile_ref(root, findings)
    if profile_ref is None:
        return findings
    refs = {
        "implementation": "tools/program_driver_runtime_verification.py",
        "entrypoint": "tools/program_driver.py",
        "contract": (
            "validation/PROGRAM_DRIVER_RUNTIME_VERIFICATION_ACTION_CONTRACT.json"
        ),
        "schema": (
            "contracts/PROGRAM_DRIVER_RUNTIME_VERIFICATION_RESULT.schema.json"
        ),
    }
    paths = {name: root / ref for name, ref in refs.items()}
    missing = [ref for name, ref in refs.items() if not paths[name].is_file()]
    if missing:
        return [
            _finding(
                "PROGRAM_DRIVER_RUNTIME_VERIFICATION_ARTIFACT_MISSING",
                ", ".join(sorted(missing)),
            )
        ]
    contract = _read_json(paths["contract"], findings)
    schema = _read_json(paths["schema"], findings)
    if not isinstance(contract, dict) or not isinstance(schema, dict):
        return findings
    if contract.get("generation_profile_ref", "EPOCH38_GENERATION_PROFILE.json") != profile_ref:
        findings.append(_finding("PROGRAM_DRIVER_RUNTIME_VERIFICATION_CONTRACT_INVALID", "profile source binding differs"))
    dag = _read_json(root / "ENGINEERING_PROJECT_DAG.json", findings)
    driver_nodes = [node for node in (dag or {}).get("nodes", [])
                    if isinstance(node, Mapping) and node.get("node_id") == "PROGRAM_DRIVER_RUNTIME_VERIFIED"]
    successors = driver_nodes[0].get("allowed_next_nodes") if len(driver_nodes) == 1 else None
    if not isinstance(successors, list) or len(successors) != 1:
        return [*findings, _finding("PROGRAM_DRIVER_RUNTIME_VERIFICATION_DAG_BINDING_INVALID", "one explicit successor is required")]
    successor_node_id = successors[0]
    probe_commands = ["status", "plan-next", "validate-transition"]
    runtime_internal_write_refs = [
        "harness-resource://execution/.harness-foundry/control/PROGRAM_CONTROL_STATE.json",
        "harness-resource://execution/.harness-foundry/control/PROGRAM_CONTROL_EVENTS.jsonl",
        (
            "harness-resource://execution/.harness-foundry/control/transactions/"
            "PROGRAM_DRIVER_RUNTIME_VERIFIED.transaction.json"
        ),
        (
            "harness-resource://execution/.harness-foundry/control/leases/"
            "PROGRAM_DRIVER_RUNTIME_VERIFIED.lease.json"
        ),
        (
            "harness-resource://execution/evidence/engineering_dag/"
            "PROGRAM_DRIVER_RUNTIME_VERIFIED/result.json"
        ),
    ]
    required_authorization_fields = {
        "schema_version",
        "authorization_id",
        "authorization_class",
        "status",
        "one_shot",
        "program_id",
        "issuer_role",
        "issued_at",
        "node_id",
        "allowed_action_id",
        "scope",
        "command_manifest_hashes",
        "command_manifest_sha256",
        "candidate_tree_sha256",
        "requirement_ir_sha256",
        "executor_implementation_sha256",
        "driver_entrypoint_sha256",
        "human_approval_receipt_sha256",
        "control_plane_registration_result_sha256",
        "expected_control_state_sha256",
        "expected_event_tip",
        "read_only_probe_commands",
        "forbidden_actions",
        "idempotency_key",
        "lease_id",
        "fencing_token",
        "max_transitions",
        "delegation_allowed",
        "signature_policy",
        "signature",
        "not_before",
        "expires_at",
    }
    execution = contract.get("execution_contract")
    runtime_inputs = contract.get("runtime_input_contract")
    authorization_profile = contract.get("authorization_profile")
    scope_contract = (
        authorization_profile.get("scope_contract")
        if isinstance(authorization_profile, Mapping)
        else None
    )
    persistence = contract.get("persistence_contract")
    persistence_refs = (
        {
            value
            for key, value in persistence.items()
            if str(key).endswith("_ref") and isinstance(value, str)
        }
        if isinstance(persistence, Mapping)
        else set()
    )
    manifest = _read_json(
        root / "THREE_PROJECT_PROGRAM_MANIFEST.json", findings
    )
    epoch_domains = (
        manifest.get("epoch_domains")
        if isinstance(manifest, Mapping)
        else None
    )
    if (
        contract.get("action_id")
        != "VERIFY-PORTABLE-PROGRAM-DRIVER-RUNTIME"
        or contract.get("node_id") != "PROGRAM_DRIVER_RUNTIME_VERIFIED"
        or contract.get("action_kind") != "PROJECT_VALIDATION"
        or contract.get("implementation_ref") != refs["implementation"]
        or contract.get("executor_implementation_sha256")
        != _file_hash(paths["implementation"])
        or contract.get("driver_entrypoint_ref") != refs["entrypoint"]
        or contract.get("driver_entrypoint_sha256")
        != _file_hash(paths["entrypoint"])
        or contract.get("result_schema_ref") != refs["schema"]
        or contract.get("result_schema_sha256")
        != _file_hash(paths["schema"])
        or contract.get("read_only_probe_commands") != probe_commands
        or not isinstance(epoch_domains, Mapping)
        or contract.get("epoch_domain_contract") != epoch_domains
        or contract.get("runtime_internal_write_refs")
        != runtime_internal_write_refs
        or contract.get("contract_sha256")
        != _hash_without_field(contract, "contract_sha256")
        or not isinstance(execution, Mapping)
        or execution.get("required_predecessor_node_id")
        != "CONTROL_PLANE_REGISTRATION"
        or execution.get("successor_node_id")
        != successor_node_id
        or execution.get("read_only_probe_commands") != probe_commands
        or execution.get("driver_start_allowed") is not False
        or execution.get("workpack_start_allowed") is not False
        or execution.get("automatic_successor_advance_allowed") is not False
        or execution.get("transaction_protocol")
        != "JOURNALED_ONE_SHOT_STATE_CAS_V1"
        or execution.get("unknown_commit_state_policy")
        != "FAIL_CLOSED_NO_REPLAY"
        or not isinstance(runtime_inputs, Mapping)
        or set(runtime_inputs.get("authorization_required_fields") or [])
        != required_authorization_fields
        or not isinstance(authorization_profile, Mapping)
        or authorization_profile.get("assurance_profile")
        != "SELF_USE_LOCAL_TRUSTED_OPERATOR"
        or authorization_profile.get("authorization_class")
        != "PROJECT_VALIDATION_AUTHORIZATION"
        or authorization_profile.get("issuer_role")
        != "LOCAL_TRUSTED_OPERATOR"
        or authorization_profile.get("max_transitions") != 1
        or authorization_profile.get("delegation_allowed") is not False
        or authorization_profile.get("signature_policy")
        != "NOT_APPLICABLE_SELF_USE_LOCAL_TRUSTED_OPERATOR"
        or authorization_profile.get("signature_value") is not None
        or authorization_profile.get(
            "external_cryptographic_signature_required"
        )
        is not False
        or set(authorization_profile.get("required_fields") or [])
        != required_authorization_fields
        or not isinstance(scope_contract, Mapping)
        or scope_contract.get("read_only_probe_commands") != probe_commands
        or scope_contract.get("runtime_internal_write_refs")
        != runtime_internal_write_refs
        or persistence_refs != set(runtime_internal_write_refs)
    ):
        findings.append(
            _finding(
                "PROGRAM_DRIVER_RUNTIME_VERIFICATION_CONTRACT_INVALID",
                "entrypoint, authorization, probe, or persistence binding is invalid",
            )
        )

    required = (
        execution.get("required_result_fields")
        if isinstance(execution, Mapping)
        else None
    )
    properties = schema.get("properties")
    if (
        not isinstance(required, list)
        or schema.get("type") != "object"
        or schema.get("additionalProperties") is not False
        or schema.get("required") != required
        or not isinstance(properties, Mapping)
        or set(properties) != set(required)
        or properties.get("next_node", {}).get("const")
        != successor_node_id
        or properties.get("driver_started", {}).get("const") is not False
        or properties.get("workpack_started", {}).get("const") is not False
        or properties.get("side_effects_allowed", {}).get("const") is not False
    ):
        findings.append(
            _finding(
                "PROGRAM_DRIVER_RUNTIME_VERIFICATION_RESULT_SCHEMA_INVALID",
                "result schema is not exact or permits a runtime-start claim",
            )
        )

    for name, required_functions in (
        (
            "entrypoint",
            {"status", "plan_next", "validate_transition", "main"},
        ),
        (
            "implementation",
            {
                "execute_action",
                "validate_static_contract",
                "validate_result_document",
                "_validate_runtime_inputs",
                "_run_read_only_probes",
            },
        ),
    ):
        try:
            tree = ast.parse(paths[name].read_text(encoding="utf-8"))
        except (OSError, UnicodeError, SyntaxError) as exc:
            findings.append(
                _finding(
                    "PROGRAM_DRIVER_RUNTIME_VERIFICATION_IMPLEMENTATION_INVALID",
                    str(exc),
                )
            )
            continue
        functions = {
            node.name
            for node in ast.walk(tree)
            if isinstance(node, ast.FunctionDef)
        }
        if not required_functions.issubset(functions):
            findings.append(
                _finding(
                    "PROGRAM_DRIVER_RUNTIME_VERIFICATION_IMPLEMENTATION_INVALID",
                    f"{name} lacks required read-only runtime functions",
                )
            )

    dag = _read_json(root / "ENGINEERING_PROJECT_DAG.json", findings)
    driver = _read_json(root / "PROGRAM_DRIVER_CONTRACT.json", findings)
    policy = _read_json(root / "AUTHORIZATION_POLICY.json", findings)
    if isinstance(dag, Mapping):
        node = next(
            (
                item
                for item in dag.get("nodes", [])
                if isinstance(item, Mapping)
                and item.get("node_id") == "PROGRAM_DRIVER_RUNTIME_VERIFIED"
            ),
            None,
        )
        if (
            not isinstance(node, Mapping)
            or node.get("action_contract_sha256")
            != _file_hash(paths["contract"])
            or node.get("executor_implementation_sha256")
            != _file_hash(paths["implementation"])
            or node.get("driver_entrypoint_sha256")
            != _file_hash(paths["entrypoint"])
            or node.get("result_schema_sha256") != _file_hash(paths["schema"])
            or node.get("read_only_probe_commands") != probe_commands
            or node.get("runtime_internal_write_refs")
            != runtime_internal_write_refs
            or node.get("transaction_protocol")
            != "JOURNALED_ONE_SHOT_STATE_CAS_V1"
        ):
            findings.append(
                _finding(
                    "PROGRAM_DRIVER_RUNTIME_VERIFICATION_DAG_BINDING_INVALID",
                    "DAG node does not bind the read-only executable closure",
                )
            )
    if isinstance(manifest, Mapping):
        binding = manifest.get("program_driver_runtime_verification")
        if (
            not isinstance(binding, Mapping)
            or binding.get("action_contract_sha256")
            != _file_hash(paths["contract"])
            or binding.get("executor_implementation_sha256")
            != _file_hash(paths["implementation"])
            or binding.get("driver_entrypoint_sha256")
            != _file_hash(paths["entrypoint"])
            or binding.get("result_schema_sha256")
            != _file_hash(paths["schema"])
            or binding.get("read_only_probe_commands") != probe_commands
            or binding.get("runtime_status") != "NOT_EXECUTED"
            or binding.get("driver_started") is not False
            or binding.get("workpack_started") is not False
        ):
            findings.append(
                _finding(
                    "PROGRAM_DRIVER_RUNTIME_VERIFICATION_MANIFEST_BINDING_INVALID",
                    "program manifest does not bind the unexecuted verifier",
                )
            )
    if isinstance(driver, Mapping):
        action = driver.get("project_validation_actions", {}).get(
            "PROGRAM_DRIVER_RUNTIME_VERIFIED"
        )
        if (
            driver.get("driver_entrypoint_ref") != refs["entrypoint"]
            or driver.get("driver_entrypoint_sha256")
            != _file_hash(paths["entrypoint"])
            or driver.get("runtime_verification_ref") != refs["contract"]
            or driver.get("runtime_verification_sha256")
            != _file_hash(paths["contract"])
            or not isinstance(action, Mapping)
            or action.get("required_execution_mode") != "PROJECT_VALIDATION"
            or action.get("read_only_probe_commands") != probe_commands
            or action.get("automatic_successor_advance_allowed") is not False
            or action.get("driver_start_allowed") is not False
            or action.get("workpack_start_allowed") is not False
        ):
            findings.append(
                _finding(
                    "PROGRAM_DRIVER_RUNTIME_VERIFICATION_DRIVER_BINDING_INVALID",
                    "Program Driver contract does not expose the bounded verifier",
                )
            )
    if isinstance(policy, Mapping):
        local = policy.get("profile_authorization_schemas", {}).get(
            "SELF_USE_LOCAL_TRUSTED_OPERATOR", {}
        )
        profile_schema = (
            local.get("PROJECT_VALIDATION_AUTHORIZATION")
            if isinstance(local, Mapping)
            else None
        )
        rules = policy.get("validation_rules")
        if (
            profile_schema != authorization_profile
            or not required_authorization_fields.issubset(
                set(policy.get("required_token_fields") or [])
            )
            or not isinstance(rules, Mapping)
            or any(
                rules.get(field) is not True
                for field in (
                    "project_validation_predecessor_hash_required",
                    "program_driver_entrypoint_hash_required",
                    "project_validation_state_cas_required",
                    "project_validation_event_tip_required",
                    "project_validation_one_shot_idempotency_fencing_required",
                    "project_validation_profile_schema_exact_match_required",
                    "project_validation_read_only_probe_set_required",
                    "project_validation_runtime_internal_write_containment_required",
                )
            )
        ):
            findings.append(
                _finding(
                    "PROGRAM_DRIVER_RUNTIME_VERIFICATION_AUTHORIZATION_POLICY_INVALID",
                    "local Project Validation policy is incomplete",
                )
            )
    negatives = _read_json(root / "validation/NEGATIVE_CASES.json", findings)
    if isinstance(negatives, Mapping) and profile_ref == "EPOCH38_GENERATION_PROFILE.json":
        cases = {
            str(case.get("case_id")): case
            for case in negatives.get("cases", [])
            if isinstance(case, Mapping)
            and str(case.get("case_id", "")).startswith(
                "NEG-V29-E43-DRIVER-VERIFY-"
            )
        }
        expected = {
            "NEG-V29-E43-DRIVER-VERIFY-AUTHORITY-SCOPE",
            "NEG-V29-E43-DRIVER-VERIFY-ENTRYPOINT-HASH",
            "NEG-V29-E43-DRIVER-VERIFY-READ-ONLY-BOUNDARY",
        }
        if (
            set(cases) != expected
            or any(
                case.get("fixture_kind") != "NON_EXECUTABLE_JSON"
                or not isinstance(case.get("input_fixture"), Mapping)
                for case in cases.values()
            )
        ):
            findings.append(
                _finding(
                    "PROGRAM_DRIVER_RUNTIME_VERIFICATION_NEGATIVE_FIXTURE_INVALID",
                    "non-executable Driver verification fixtures are incomplete",
                )
            )
    portable = _read_json(
        root / "validation/PORTABLE_FILE_MANIFEST.json", findings
    )
    if isinstance(portable, Mapping):
        files = portable.get("files")
        if not isinstance(files, Mapping) or any(
            files.get(ref) != _file_hash(root / ref) for ref in refs.values()
        ):
            findings.append(
                _finding(
                    "PROGRAM_DRIVER_RUNTIME_VERIFICATION_PORTABLE_BINDING_INVALID",
                    "portable inventory does not bind the complete Driver verifier",
                )
            )
    return findings


def _check_controlled_workpack_runtime_executable_closure(
    root: Path,
    *,
    active_requirement_epoch: int | None = None,
) -> list[dict[str, Any]]:
    """Require a real, portable sibling-Runtime provider for the root Workpack."""

    findings: list[dict[str, Any]] = []
    node_id = "MAIN_EXECUTION_PACKAGE_MATERIALIZED"
    dag = _read_json(root / "ENGINEERING_PROJECT_DAG.json", findings)
    node_matches = [item for item in (dag or {}).get("nodes", [])
                    if isinstance(item, Mapping) and item.get("node_id") == node_id]
    if len(node_matches) != 1:
        return findings + [_finding("CONTROLLED_WORKPACK_RUNTIME_CONTRACT_INVALID", "materialization node must resolve uniquely")]
    workpack_id = node_matches[0].get("workpack_id")
    if not isinstance(workpack_id, str) or not re.fullmatch(r"[A-Za-z0-9_-]+", workpack_id):
        return findings + [_finding("CONTROLLED_WORKPACK_RUNTIME_CONTRACT_INVALID", "invalid materialization Workpack id")]
    profile_ref = _control_startup_profile_ref(root, findings)
    legacy = profile_ref == "EPOCH38_GENERATION_PROFILE.json"
    if profile_ref is None:
        return findings + [_finding("CONTROLLED_WORKPACK_RUNTIME_CONTRACT_INVALID", "no applicable runtime profile")]
    refs = {
        "provider": "tools/harness_foundry_runtime/workpack_runtime.py",
        "coding_protocol": "tools/harness_foundry_runtime/coding_protocol.py",
        "coding_process": "tools/harness_foundry_runtime/coding_process.py",
        "coding_runtime": "tools/harness_foundry_runtime/coding_runtime.py",
        "workpack_acceptance": "tools/harness_foundry_runtime/workpack_acceptance.py",
        "lab_protocol": "tools/harness_foundry_runtime/lab_protocol.py",
        "lab_protocol_checks": "tools/harness_foundry_runtime/lab_protocol_checks.py",
        "project_verification": "tools/harness_foundry_runtime/project_verification.py",
        "lab_protocol_worker": "tools/lab_protocol_worker.py",
        "entrypoint": "tools/workpack_runtime.py",
        "contract": "validation/CONTROLLED_WORKPACK_RUNTIME_CONTRACT.json",
        "commands": f"commands/{workpack_id}.commands.json",
        "capsule": f"capsules/{workpack_id}.capsule.json",
        "index": "WORKPACK_INDEX.json",
        "profile": profile_ref,
    }
    paths = {name: root / relative for name, relative in refs.items()}
    if any(not path.is_file() for path in paths.values()):
        missing = sorted(name for name, path in paths.items() if not path.is_file())
        return [
            _finding(
                "CONTROLLED_WORKPACK_RUNTIME_ARTIFACT_MISSING",
                ",".join(missing),
            )
        ]
    contract = _read_json(paths["contract"], findings)
    manifest = _read_json(
        root / "THREE_PROJECT_PROGRAM_MANIFEST.json", findings
    )
    driver = _read_json(root / "PROGRAM_DRIVER_CONTRACT.json", findings)
    policy = _read_json(root / "AUTHORIZATION_POLICY.json", findings)
    index = _read_json(paths["index"], findings)
    commands = _read_json(paths["commands"], findings)
    capsule = _read_json(paths["capsule"], findings)
    profile = _read_json(paths["profile"], findings)
    if not all(
        isinstance(value, Mapping)
        for value in (
            contract,
            dag,
            manifest,
            driver,
            policy,
            index,
            commands,
            capsule,
            profile,
        )
    ):
        return findings
    contract_active_epoch = contract.get("active_requirement_epoch")
    allowed_write_refs = [
        (
            "harness-resource://execution/evidence/engineering_dag/"
            "MAIN_EXECUTION_PACKAGE_MATERIALIZED"
        ),
        (
            "harness-resource://execution/project_start_packages/"
            "main_build/repository"
        ),
    ]
    authorization = contract.get("authorization_profile")
    scope = (
        authorization.get("scope_contract")
        if isinstance(authorization, Mapping)
        else None
    )
    overlay = contract.get("command_overlay_contract")
    hydration = contract.get("hydration_contract")
    execution = contract.get("execution_contract")
    if (
        contract.get("contract_id") != (
            "EPOCH45_CONTROLLED_WORKPACK_RUNTIME_V1" if legacy
            else "LOCAL_CONTROLLED_WORKPACK_RUNTIME_V1"
        )
        or isinstance(contract_active_epoch, bool)
        or not isinstance(contract_active_epoch, int)
        or contract_active_epoch < (45 if legacy else 0)
        or (
            active_requirement_epoch is not None
            and contract_active_epoch != active_requirement_epoch
        )
        or (legacy and (
            workpack_id != "WP-HARNESS-FOUNDRY-V2-9-CHAT-FACTORY-G0-001"
            or contract.get("profile_origin_requirement_epoch") != 38
            or profile.get("profile_origin_requirement_epoch") != 38
            or profile.get("active_requirement_epoch") != contract_active_epoch
        ))
        or (not legacy and "profile_origin_requirement_epoch" in contract)
        or contract.get("assurance_profile")
        != "SELF_USE_LOCAL_TRUSTED_OPERATOR"
        or contract.get("node_id") != node_id
        or contract.get("workpack_id") != workpack_id
        or contract.get("provider_kind") != "CODEX_WORKPACK_PROVIDER"
        or contract.get("provider_implementation_ref") != refs["provider"]
        or contract.get("provider_implementation_sha256")
        != _file_hash(paths["provider"])
        or contract.get("runtime_entrypoint_ref") != refs["entrypoint"]
        or contract.get("runtime_entrypoint_sha256")
        != _file_hash(paths["entrypoint"])
        or contract.get("contract_sha256")
        != _hash_without_field(contract, "contract_sha256")
        or contract.get("factory_execution_allowed") is not False
        or contract.get("sibling_controlled_runtime_required") is not True
        or contract.get("test_adapter_or_schema_only_closure_allowed") is not False
        or contract.get("external_runtime_state_reuse_allowed") is not False
        or not isinstance(overlay, Mapping)
        or overlay.get("required") is not True
        or overlay.get("command_ids")
        != ["ROOT-CODEX-CODING", "ROOT-MATERIALIZATION-VERIFY"]
        or overlay.get("absolute_executable_and_sha256_required") is not True
        or overlay.get("exact_argv_required") is not True
        or overlay.get("shell_reparse_allowed") is not False
        or overlay.get("codex_required_sandbox") != "workspace-write"
        or not isinstance(hydration, Mapping)
        or hydration.get("side_effect_free") is not True
        or hydration.get("candidate_must_remain_read_only") is not True
        or hydration.get("status_after_hydration")
        != "READY_FOR_A3_PREPARATION"
        or hydration.get("execution_authorized_after_hydration") is not False
        or not isinstance(authorization, Mapping)
        or authorization.get("authorization_class") != "A3_PROGRAM_BOUNDED"
        or authorization.get("max_transitions") != 1
        or authorization.get("max_loop_rounds") != 1
        or authorization.get("delegation_allowed") is not False
        or not isinstance(scope, Mapping)
        or scope.get("node_id") != node_id
        or scope.get("workpack_id") != workpack_id
        or scope.get("allowed_write_refs") != allowed_write_refs
        or scope.get("network_allowed") is not False
        or scope.get("real_target_install_allowed") is not False
        or scope.get("automatic_successor_advance_allowed") is not False
        or not isinstance(execution, Mapping)
        or execution.get("max_transitions") != 1
        or execution.get("max_loop_rounds") != 1
        or execution.get("allowed_write_refs") != allowed_write_refs
        or execution.get("validation_scope")
        != "STRUCTURAL_PACKAGE_CONTRACT_ONLY"
        or execution.get("fresh_hydration_inputs_required_before_writes") is not True
        or execution.get("network_allowed") is not False
        or execution.get("real_target_install_allowed") is not False
        or execution.get("candidate_write_allowed") is not False
        or execution.get("automatic_postflight_required") is not True
        or execution.get("independent_structural_review_required") is not True
        or execution.get("automatic_successor_advance_allowed") is not False
    ):
        findings.append(
            _finding(
                "CONTROLLED_WORKPACK_RUNTIME_CONTRACT_INVALID",
                "provider, hydration, overlay, A3, or execution boundary is invalid",
            )
        )

    required_functions = {
        "plan_workpack_node",
        "candidate_identity",
        "verify_codex_cli_schema",
        "hydrate_workpack_runtime",
        "validate_a3_authorization",
        "execute_hydrated_workpack",
    }
    try:
        provider_tree = ast.parse(paths["provider"].read_text(encoding="utf-8"))
        entrypoint_tree = ast.parse(
            paths["entrypoint"].read_text(encoding="utf-8")
        )
    except (OSError, UnicodeError, SyntaxError) as exc:
        findings.append(
            _finding("CONTROLLED_WORKPACK_RUNTIME_IMPLEMENTATION_INVALID", str(exc))
        )
    else:
        provider_functions = {
            node.name
            for node in ast.walk(provider_tree)
            if isinstance(node, ast.FunctionDef)
        }
        entrypoint_functions = {
            node.name
            for node in ast.walk(entrypoint_tree)
            if isinstance(node, ast.FunctionDef)
        }
        provider_text = paths["provider"].read_text(encoding="utf-8")
        if (
            not required_functions.issubset(provider_functions)
            or "subprocess.run" not in provider_text
            or "TEST_ONLY_IDEMPOTENT_ADAPTERS" in provider_text
            or "test_adapter_results" in provider_text
            or "main" not in entrypoint_functions
        ):
            findings.append(
                _finding(
                    "CONTROLLED_WORKPACK_RUNTIME_IMPLEMENTATION_INVALID",
                    "real provider or portable entrypoint is incomplete",
                )
            )

    node = next(
        (
            item
            for item in dag.get("nodes", [])
            if isinstance(item, Mapping) and item.get("node_id") == node_id
        ),
        None,
    )
    binding = manifest.get("main_execution_package_runtime")
    driver_action = driver.get("workpack_execution_actions", {}).get(node_id)
    local_profile = policy.get("profile_authorization_schemas", {}).get(
        "SELF_USE_LOCAL_TRUSTED_OPERATOR", {}
    )
    policy_a3 = (
        local_profile.get("PROJECT_BOOTSTRAP_AUTHORIZATION")
        if isinstance(local_profile, Mapping)
        else None
    )
    rules = policy.get("validation_rules")
    expected_hashes = {
        "runtime_provider_sha256": _file_hash(paths["provider"]),
        "runtime_entrypoint_sha256": _file_hash(paths["entrypoint"]),
        "runtime_contract_sha256": _file_hash(paths["contract"]),
    }
    if (
        not isinstance(node, Mapping)
        or node.get("runtime_provider_ref") != refs["provider"]
        or node.get("runtime_entrypoint_ref") != refs["entrypoint"]
        or node.get("runtime_contract_ref") != refs["contract"]
        or node.get("active_requirement_epoch") != contract_active_epoch
        or any(node.get(key) != value for key, value in expected_hashes.items())
        or node.get("runtime_hydration_required") is not True
        or node.get("command_overlay_required") is not True
        or node.get("max_transitions") != 1
        or node.get("max_loop_rounds") != 1
        or node.get("automatic_successor_advance_allowed") is not False
        or not isinstance(binding, Mapping)
        or binding.get("runtime_status") != "PLANNED_NOT_HYDRATED"
        or binding.get("execution_authorized") is not False
        or binding.get("workpack_executed") is not False
        or binding.get("active_requirement_epoch") != contract_active_epoch
        or any(binding.get(key) != value for key, value in expected_hashes.items())
        or not isinstance(driver_action, Mapping)
        or driver_action.get("required_authorization_class")
        != "A3_PROGRAM_BOUNDED"
        or driver_action.get("active_requirement_epoch")
        != contract_active_epoch
        or driver_action.get("factory_execution_allowed") is not False
        or driver_action.get("automatic_successor_advance_allowed") is not False
        or policy_a3 != authorization
        or not isinstance(rules, Mapping)
        or any(
            rules.get(key) is not True
            for key in (
                "workpack_runtime_provider_hash_required",
                "workpack_runtime_overlay_hash_required",
                "workpack_runtime_cli_schema_hash_required",
                "workpack_runtime_candidate_hydration_required",
                "workpack_runtime_exact_write_roots_required",
                "workpack_runtime_a3_exact_scope_required",
                "workpack_runtime_external_state_reuse_forbidden",
            )
        )
    ):
        findings.append(
            _finding(
                "CONTROLLED_WORKPACK_RUNTIME_PROJECTION_INVALID",
                "DAG, Driver, Program Manifest, or local authorization policy drifted",
            )
        )

    for document, label in (
        (index, "WORKPACK_INDEX"),
        (commands, "COMMAND_MANIFEST"),
        (capsule, "CAPSULE"),
    ):
        if (
            document.get("runtime_provider_ref") != refs["provider"]
            or document.get("active_requirement_epoch")
            != contract_active_epoch
            or document.get("runtime_entrypoint_ref") != refs["entrypoint"]
            or document.get("runtime_contract_ref") != refs["contract"]
            or any(document.get(key) != value for key, value in expected_hashes.items())
            or document.get("runtime_hydration_required") is not True
            or document.get("command_overlay_required") is not True
        ):
            findings.append(
                _finding("CONTROLLED_WORKPACK_RUNTIME_PROJECTION_INVALID", label)
            )

    negatives = _read_json(root / "validation/NEGATIVE_CASES.json", findings)
    if legacy and isinstance(negatives, Mapping):
        cases = {
            str(case.get("case_id")): case
            for case in negatives.get("cases", [])
            if isinstance(case, Mapping)
            and str(case.get("case_id", "")).startswith(
                "NEG-V29-E45-WORKPACK-RUNTIME-"
            )
        }
        expected = {
            "NEG-V29-E45-WORKPACK-RUNTIME-CODEX-HASH": (
                "CODEX_HASH_MISMATCH",
                {"codex_executable_sha256": "0" * 64},
            ),
            "NEG-V29-E45-WORKPACK-RUNTIME-WRITE-ROOT": (
                "COMMAND_OVERLAY_WRITE_ROOT_INVALID",
                {"allowed_write_roots": [LOGICAL_CANDIDATE_ROOT]},
            ),
            "NEG-V29-E45-WORKPACK-RUNTIME-A3-SCOPE": (
                "A3_AUTHORIZATION_INVALID",
                {
                    "max_transitions": 2,
                    "max_loop_rounds": 2,
                    "real_target_install_allowed": True,
                },
            ),
        }
        artifact_manifest_path = (
            root / "canonical_sources/ARTIFACT_OBLIGATION_MANIFEST.json"
        )
        artifact_manifest = (
            _read_json(artifact_manifest_path, findings)
            if artifact_manifest_path.is_file()
            else {}
        )
        artifact_index = (
            artifact_manifest.get("artifact_index", {})
            if isinstance(artifact_manifest, Mapping)
            else {}
        )
        artifacts_declared = bool(artifact_index)
        if set(cases) != set(expected) or any(
            not _is_nonexecutable_negative_fixture(case)
            or case.get("origin")
            != "EPOCH45_CONTROLLED_RUNTIME_WORKPACK_EXECUTABLE_CLOSURE"
            or case.get("expected_failure") != expected[case_id][0]
            or not isinstance(case.get("input_fixture"), Mapping)
            or any(
                case["input_fixture"].get(field) != value
                for field, value in expected[case_id][1].items()
            )
            or not _concrete_negative_input(
                case["input_fixture"],
                case.get("expected_failure"),
                artifacts_declared=artifacts_declared,
                artifact_index=artifact_index,
            )
            for case_id, case in cases.items()
        ):
            findings.append(
                _finding(
                    "CONTROLLED_WORKPACK_RUNTIME_NEGATIVE_FIXTURE_INVALID",
                    "non-executable Runtime fixtures are incomplete",
                )
            )
    portable = _read_json(root / "validation/PORTABLE_FILE_MANIFEST.json", findings)
    if isinstance(portable, Mapping):
        files = portable.get("files")
        if not isinstance(files, Mapping) or any(
            files.get(relative) != _file_hash(root / relative)
            for relative in refs.values()
        ):
            findings.append(
                _finding(
                    "CONTROLLED_WORKPACK_RUNTIME_PORTABLE_BINDING_INVALID",
                    "portable inventory does not bind the Runtime closure",
                )
            )
    return findings


def _check_main_execution_package_validation_executable_closure(
    root: Path,
    *,
    active_requirement_epoch: int | None = None,
) -> list[dict[str, Any]]:
    """Require the Epoch 49 byte-backed structural validation provider."""

    findings: list[dict[str, Any]] = []
    node_id = "MAIN_EXECUTION_PACKAGE_VALIDATED"
    refs = {
        "provider": (
            "tools/harness_foundry_runtime/"
            "main_execution_package_validation.py"
        ),
        "entrypoint": "tools/main_execution_package_validation.py",
        "contract": (
            "validation/MAIN_EXECUTION_PACKAGE_VALIDATION_ACTION_CONTRACT.json"
        ),
        "schema": (
            "contracts/MAIN_EXECUTION_PACKAGE_VALIDATION_RESULT.schema.json"
        ),
        "profile": "EPOCH38_GENERATION_PROFILE.json",
    }
    paths = {name: root / relative for name, relative in refs.items()}
    if any(not path.is_file() for path in paths.values()):
        missing = sorted(name for name, path in paths.items() if not path.is_file())
        return [
            _finding(
                "MAIN_EXECUTION_PACKAGE_VALIDATION_ARTIFACT_MISSING",
                ",".join(missing),
            )
        ]
    contract = _read_json(paths["contract"], findings)
    schema = _read_json(paths["schema"], findings)
    profile = _read_json(paths["profile"], findings)
    dag = _read_json(root / "ENGINEERING_PROJECT_DAG.json", findings)
    manifest = _read_json(root / "THREE_PROJECT_PROGRAM_MANIFEST.json", findings)
    driver = _read_json(root / "PROGRAM_DRIVER_CONTRACT.json", findings)
    policy = _read_json(root / "AUTHORIZATION_POLICY.json", findings)
    if not all(
        isinstance(value, Mapping)
        for value in (contract, schema, profile, dag, manifest, driver, policy)
    ):
        return findings
    contract_epoch = contract.get("active_requirement_epoch")
    repository_ref = (
        "harness-resource://execution/project_start_packages/main_build/repository"
    )
    evidence_ref = (
        "harness-resource://execution/evidence/engineering_dag/"
        "MAIN_EXECUTION_PACKAGE_VALIDATED"
    )
    internal_write_refs = [
        (
            "harness-resource://execution/.harness-foundry/control/"
            "PROGRAM_CONTROL_STATE.json"
        ),
        (
            "harness-resource://execution/.harness-foundry/control/"
            "PROGRAM_CONTROL_EVENTS.jsonl"
        ),
        (
            "harness-resource://execution/.harness-foundry/control/transactions/"
            "MAIN_EXECUTION_PACKAGE_VALIDATED.transaction.json"
        ),
        (
            "harness-resource://execution/.harness-foundry/control/leases/"
            "MAIN_EXECUTION_PACKAGE_VALIDATED.lease.json"
        ),
        f"{evidence_ref}/result.json",
    ]
    authorization = contract.get("authorization_profile")
    scope = (
        authorization.get("scope_contract")
        if isinstance(authorization, Mapping)
        else None
    )
    execution = contract.get("execution_contract")
    persistence = contract.get("persistence_contract")
    persistence_refs = (
        {
            value
            for key, value in persistence.items()
            if str(key).endswith("_ref") and isinstance(value, str)
        }
        if isinstance(persistence, Mapping)
        else set()
    )
    if (
        contract.get("contract_id")
        != "MAIN_EXECUTION_PACKAGE_VALIDATION_CLOSURE_V1"
        or isinstance(contract_epoch, bool)
        or not isinstance(contract_epoch, int)
        or contract_epoch < 49
        or (
            active_requirement_epoch is not None
            and contract_epoch != active_requirement_epoch
        )
        or profile.get("active_requirement_epoch") != contract_epoch
        or contract.get("assurance_profile")
        != "SELF_USE_LOCAL_TRUSTED_OPERATOR"
        or contract.get("action_id")
        != "VALIDATE-MAIN-EXECUTION-PACKAGE-STRUCTURE"
        or contract.get("node_id") != node_id
        or contract.get("implementation_ref") != refs["provider"]
        or contract.get("executor_implementation_sha256")
        != _file_hash(paths["provider"])
        or contract.get("runtime_entrypoint_ref") != refs["entrypoint"]
        or contract.get("runtime_entrypoint_sha256")
        != _file_hash(paths["entrypoint"])
        or contract.get("result_schema_ref") != refs["schema"]
        or contract.get("result_schema_sha256") != _file_hash(paths["schema"])
        or contract.get("contract_sha256")
        != _hash_without_field(contract, "contract_sha256")
        or contract.get("validation_scope")
        != "STRUCTURAL_PACKAGE_CONTRACT_ONLY"
        or contract.get("predecessor_repository_write_allowed") is not False
        or contract.get("automatic_successor_advance_allowed") is not False
        or not isinstance(authorization, Mapping)
        or authorization.get("authorization_class")
        != "PROJECT_VALIDATION_AUTHORIZATION"
        or authorization.get("max_transitions") != 1
        or authorization.get("max_loop_rounds") != 1
        or authorization.get("delegation_allowed") is not False
        or not isinstance(scope, Mapping)
        or scope.get("predecessor_repository_ref") != repository_ref
        or scope.get("predecessor_repository_write_allowed") is not False
        or scope.get("node_evidence_write_ref") != evidence_ref
        or scope.get("runtime_internal_write_refs") != internal_write_refs
        or scope.get("automatic_successor_advance_allowed") is not False
        or not isinstance(execution, Mapping)
        or execution.get("required_predecessor_node_id")
        != "MAIN_EXECUTION_PACKAGE_MATERIALIZED"
        or execution.get("successor_node_id") != "MAIN_PROGRAM_REGISTRATION"
        or execution.get("predecessor_repository_ref") != repository_ref
        or execution.get("predecessor_repository_write_allowed") is not False
        or execution.get("node_evidence_write_ref") != evidence_ref
        or execution.get("validation_scope")
        != "STRUCTURAL_PACKAGE_CONTRACT_ONLY"
        or execution.get("max_transitions") != 1
        or execution.get("max_loop_rounds") != 1
        or execution.get("real_target_install_allowed") is not False
        or execution.get("automatic_successor_advance_allowed") is not False
        or execution.get("produced_capabilities")
        != ["MAIN_EXECUTION_PACKAGE_VALIDATED_PASS"]
        or persistence_refs != set(internal_write_refs)
        or schema.get("additionalProperties") is not False
        or schema.get("required") != execution.get("required_result_fields")
    ):
        findings.append(
            _finding(
                "MAIN_EXECUTION_PACKAGE_VALIDATION_CONTRACT_INVALID",
                "provider, authorization, repository, evidence, or promotion boundary drifted",
            )
        )

    try:
        provider_tree = ast.parse(paths["provider"].read_text(encoding="utf-8"))
        entrypoint_tree = ast.parse(paths["entrypoint"].read_text(encoding="utf-8"))
    except (OSError, UnicodeError, SyntaxError) as exc:
        findings.append(
            _finding(
                "MAIN_EXECUTION_PACKAGE_VALIDATION_IMPLEMENTATION_INVALID",
                str(exc),
            )
        )
    else:
        provider_functions = {
            node.name
            for node in ast.walk(provider_tree)
            if isinstance(node, ast.FunctionDef)
        }
        entrypoint_functions = {
            node.name
            for node in ast.walk(entrypoint_tree)
            if isinstance(node, ast.FunctionDef)
        }
        provider_text = paths["provider"].read_text(encoding="utf-8")
        if (
            not {
                "validate_static_contract",
                "_validate_materialized_repository",
                "_validate_runtime_inputs",
                "execute_action",
            }.issubset(provider_functions)
            or "subprocess.run" in provider_text
            or "TEST_ONLY_IDEMPOTENT_ADAPTERS" in provider_text
            or "main" not in entrypoint_functions
        ):
            findings.append(
                _finding(
                    "MAIN_EXECUTION_PACKAGE_VALIDATION_IMPLEMENTATION_INVALID",
                    "real non-executing structural provider or entrypoint is incomplete",
                )
            )

    node = next(
        (
            item
            for item in dag.get("nodes", [])
            if isinstance(item, Mapping) and item.get("node_id") == node_id
        ),
        None,
    )
    binding = manifest.get("main_execution_package_validation")
    driver_action = driver.get("project_validation_actions", {}).get(node_id)
    local_profile = policy.get("profile_authorization_schemas", {}).get(
        "SELF_USE_LOCAL_TRUSTED_OPERATOR", {}
    )
    policy_authorization = (
        local_profile.get("MAIN_EXECUTION_PACKAGE_VALIDATION_AUTHORIZATION")
        if isinstance(local_profile, Mapping)
        else None
    )
    rules = policy.get("validation_rules")
    expected_hashes = {
        "action_contract_sha256": _file_hash(paths["contract"]),
        "executor_implementation_sha256": _file_hash(paths["provider"]),
        "runtime_entrypoint_sha256": _file_hash(paths["entrypoint"]),
        "result_schema_sha256": _file_hash(paths["schema"]),
    }
    if (
        not isinstance(node, Mapping)
        or node.get("action_contract_ref") != refs["contract"]
        or node.get("executor_implementation_ref") != refs["provider"]
        or node.get("runtime_entrypoint_ref") != refs["entrypoint"]
        or node.get("result_schema_ref") != refs["schema"]
        or any(node.get(key) != value for key, value in expected_hashes.items())
        or node.get("predecessor_repository_ref") != repository_ref
        or node.get("predecessor_repository_write_allowed") is not False
        or node.get("allowed_write_paths") != [evidence_ref]
        or node.get("automatic_successor_advance_allowed") is not False
        or node.get("active_requirement_epoch") != contract_epoch
        or not isinstance(binding, Mapping)
        or binding.get("runtime_status") != "NOT_EXECUTED"
        or binding.get("predecessor_repository_write_allowed") is not False
        or binding.get("node_evidence_write_ref") != evidence_ref
        or binding.get("successor_started") is not False
        or any(binding.get(key) != value for key, value in expected_hashes.items())
        or not isinstance(driver_action, Mapping)
        or driver_action.get("action_contract_ref") != refs["contract"]
        or driver_action.get("executor_implementation_ref") != refs["provider"]
        or driver_action.get("runtime_entrypoint_ref") != refs["entrypoint"]
        or driver_action.get("predecessor_repository_write_allowed") is not False
        or driver_action.get("node_evidence_write_ref") != evidence_ref
        or driver_action.get("automatic_successor_advance_allowed") is not False
        or policy_authorization != authorization
        or not isinstance(rules, Mapping)
        or any(
            rules.get(key) is not True
            for key in (
                "main_package_validation_predecessor_result_hash_required",
                "main_package_validation_repository_tree_hash_required",
                "main_package_validation_predecessor_repository_read_only",
                "main_package_validation_node_evidence_only_command_write",
                "main_package_validation_one_shot_state_cas_required",
                "main_package_validation_no_successor_auto_advance",
                "main_package_validation_self_report_only_forbidden",
            )
        )
    ):
        findings.append(
            _finding(
                "MAIN_EXECUTION_PACKAGE_VALIDATION_PROJECTION_INVALID",
                "DAG, Driver, Manifest, or local policy binding drifted",
            )
        )

    negatives = _read_json(root / "validation/NEGATIVE_CASES.json", findings)
    if isinstance(negatives, Mapping):
        cases = {
            str(case.get("case_id")): case
            for case in negatives.get("cases", [])
            if isinstance(case, Mapping)
            and str(case.get("case_id", "")).startswith(
                "NEG-V29-E49-MAIN-PACKAGE-VALIDATION-"
            )
        }
        expected = {
            "NEG-V29-E49-MAIN-PACKAGE-VALIDATION-REPOSITORY-DRIFT",
            "NEG-V29-E49-MAIN-PACKAGE-VALIDATION-WRITE-ROOT",
            "NEG-V29-E49-MAIN-PACKAGE-VALIDATION-SELF-REPORT",
        }
        if set(cases) != expected or any(
            not _is_nonexecutable_negative_fixture(case)
            or case.get("origin")
            != "EPOCH49_MAIN_EXECUTION_PACKAGE_VALIDATION_CLOSURE"
            for case in cases.values()
        ):
            findings.append(
                _finding(
                    "MAIN_EXECUTION_PACKAGE_VALIDATION_NEGATIVE_FIXTURE_INVALID",
                    "non-executable structural validation fixtures are incomplete",
                )
            )
    portable = _read_json(root / "validation/PORTABLE_FILE_MANIFEST.json", findings)
    if isinstance(portable, Mapping):
        files = portable.get("files")
        if not isinstance(files, Mapping) or any(
            files.get(relative) != _file_hash(root / relative)
            for relative in refs.values()
        ):
            findings.append(
                _finding(
                    "MAIN_EXECUTION_PACKAGE_VALIDATION_PORTABLE_BINDING_INVALID",
                    "portable inventory does not bind the validation closure",
                )
            )
    return findings


