            "attempts/ATTEMPT-63F293065CC94E52ADA3CC586C9D01D0/LINK-PROTOCOL.stderr",
            "attempts/ATTEMPT-63F293065CC94E52ADA3CC586C9D01D0/LINK-PROTOCOL.stdout",
